// LEARN(design.architecture.styles): one module boundary, as a function call and as a network call.
package main

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"slices"
	"sync"
	"time"
)

// Invoicer is what the orders module needs from billing, declared by orders.
type Invoicer interface {
	Invoice(ctx context.Context, orderID int) error
}

// ledger is billing's data: which orders have an invoice.
type ledger struct {
	mu       sync.Mutex
	invoiced []int
}

func (l *ledger) Invoice(_ context.Context, orderID int) error {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.invoiced = append(l.invoiced, orderID)
	return nil
}

// remote is the same port over HTTP, as it would be after extracting billing.
type remote struct{ url string }

func (r remote) Invoice(ctx context.Context, orderID int) error {
	ctx, cancel := context.WithTimeout(ctx, 100*time.Millisecond)
	defer cancel()
	req, _ := http.NewRequestWithContext(ctx, "POST", fmt.Sprintf("%s/invoices?order=%d", r.url, orderID), nil)
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return err
	}
	return resp.Body.Close()
}

func placeOrders(label string, billing Invoicer) {
	for id := 1; id <= 3; id++ {
		err := billing.Invoice(context.Background(), id)
		switch {
		case err == nil:
			fmt.Printf("%s: order %d invoiced\n", label, id)
		case errors.Is(err, context.DeadlineExceeded):
			fmt.Printf("%s: order %d: timeout; invoiced or not? unknown\n", label, id)
		default:
			fmt.Printf("%s: order %d: %v\n", label, id, err)
		}
	}
}

func main() {
	local := &ledger{}
	placeOrders("in-process", local)

	svc := &ledger{}
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var id int
		fmt.Sscan(r.URL.Query().Get("order"), &id)
		if id == 2 {
			time.Sleep(300 * time.Millisecond) // a GC pause, a deploy, a slow disk
		}
		svc.Invoice(r.Context(), id)
	}))
	placeOrders("over HTTP", remote{url: srv.URL})
	srv.Close() // waits for the slow request to finish
	fmt.Println("billing service's ledger:", slices.Sorted(slices.Values(svc.invoiced)))
}

// LEARN(design.architecture.styles): REST conditional requests: ETag and If-Match turn a lost update into 412.
package main

import (
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
)

// note is one editable resource; its version goes out as a strong ETag.
type note struct {
	mu      sync.Mutex
	body    string
	version int
}

func (n *note) get(w http.ResponseWriter, r *http.Request) {
	n.mu.Lock()
	defer n.mu.Unlock()
	w.Header().Set("ETag", fmt.Sprintf(`"%d"`, n.version))
	io.WriteString(w, n.body)
}

// put replaces the note only if the client's copy is still current.
func (n *note) put(w http.ResponseWriter, r *http.Request) {
	n.mu.Lock() // check and write as one step; example 3 does it in one UPDATE
	defer n.mu.Unlock()
	switch r.Header.Get("If-Match") {
	case "":
		http.Error(w, "send If-Match with the ETag you read", http.StatusPreconditionRequired)
	case fmt.Sprintf(`"%d"`, n.version):
		body, _ := io.ReadAll(io.LimitReader(r.Body, 64<<10))
		n.body, n.version = string(body), n.version+1
		w.Header().Set("ETag", fmt.Sprintf(`"%d"`, n.version))
		w.WriteHeader(http.StatusNoContent)
	default:
		http.Error(w, "the note changed since you read it", http.StatusPreconditionFailed)
	}
}

func main() {
	n := &note{body: "defer runs LIFO", version: 1}
	mux := http.NewServeMux()
	mux.HandleFunc("GET /notes/go.basics.defer", n.get)
	mux.HandleFunc("PUT /notes/go.basics.defer", n.put)

	call := func(tab, method, etag, body string) string {
		req := httptest.NewRequest(method, "/notes/go.basics.defer", strings.NewReader(body))
		if etag != "" {
			req.Header.Set("If-Match", etag)
		}
		rec := httptest.NewRecorder()
		mux.ServeHTTP(rec, req)
		fmt.Printf("%s %-3s If-Match=%-4s -> %d %s ETag=%s\n", tab, method, etag,
			rec.Code, http.StatusText(rec.Code), rec.Header().Get("ETag"))
		return rec.Header().Get("ETag")
	}
	a := call("tab A", "GET", "", "")
	b := call("tab B", "GET", "", "")
	call("tab A", "PUT", a, "defer runs LIFO, at function exit")
	call("tab B", "PUT", b, "defer evaluates arguments early") // B's copy is stale
	call("tab B", "PUT", "", "just overwrite it")
	b = call("tab B", "GET", "", "")
	call("tab B", "PUT", b, "defer runs LIFO, at function exit; arguments early")
}

-- LEARN(design.architecture.styles): optimistic locking in one UPDATE: check the version and move it forward.
-- Tabs A and B both read version 1 and save at the same moment.

A: BEGIN;
B: BEGIN;
A: UPDATE notes SET body = 'defer runs LIFO, at function exit', version = version + 1
   WHERE lesson_id = 'go.basics.defer' AND version = 1 RETURNING version;
B: UPDATE notes SET body = 'defer evaluates arguments early', version = version + 1
   WHERE lesson_id = 'go.basics.defer' AND version = 1 RETURNING version;
A: COMMIT;
B: COMMIT;

