-- LEARN(design.architecture.business-rules): a read-then-write rule races, in the app and in a trigger alike.
-- Rule: a course never has more bookings than seats. Both courses have one seat.

-- 1. The rule in the application: count, compare, insert.
A: BEGIN;
B: BEGIN;
A: SELECT count(*) FROM bookings WHERE course_id = 1;   -- 0 < 1, go ahead
B: SELECT count(*) FROM bookings WHERE course_id = 1;   -- 0 < 1, go ahead
A: INSERT INTO bookings VALUES (1, 'Ayşe');
B: INSERT INTO bookings VALUES (1, 'Işıl');
A: COMMIT;
B: COMMIT;

-- 2. The same rule "in the database", as a BEFORE INSERT trigger.
A: CREATE FUNCTION check_seats() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (SELECT count(*) FROM bookings WHERE course_id = NEW.course_id)
       >= (SELECT seats FROM courses WHERE id = NEW.course_id) THEN
        RAISE EXCEPTION 'course % is full', NEW.course_id;
    END IF;
    RETURN NEW;
END $$;
A: CREATE TRIGGER bookings_check_seats BEFORE INSERT ON bookings
    FOR EACH ROW EXECUTE FUNCTION check_seats();
A: BEGIN;
B: BEGIN;
A: INSERT INTO bookings VALUES (2, 'Ayşe');
B: INSERT INTO bookings VALUES (2, 'Işıl');   -- A's row is invisible to B's count
A: COMMIT;
B: COMMIT;

-- One at a time, the trigger works, which is why tests pass.
A: INSERT INTO bookings VALUES (2, 'Can');

A: SELECT course_id, count(*) AS booked FROM bookings GROUP BY course_id ORDER BY course_id;

-- LEARN(design.architecture.business-rules): a counter on the parent row plus a CHECK serializes the rule.
-- courses.booked is kept with each booking; the CHECK states the rule itself.

A: BEGIN;
B: BEGIN;
A: UPDATE courses SET booked = booked + 1 WHERE id = 1;
A: INSERT INTO bookings VALUES (1, 'Ayşe');
B: UPDATE courses SET booked = booked + 1 WHERE id = 1;   -- waits for A's row lock
A: COMMIT;
B: ROLLBACK;

A: SELECT c.id, c.seats, c.booked, count(b.student) AS bookings
   FROM courses AS c LEFT JOIN bookings AS b ON b.course_id = c.id GROUP BY c.id;

// LEARN(design.architecture.business-rules): a rule written twice drifts; give it one home and ask that home.
package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"os"
	"strings"
	"unicode"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
)

// The rule: "usernames are unique, ignoring case". Four implementations of
// "ignoring case" (JavaScript's toLowerCase would turn İ into i + U+0307, a fifth).
func main() {
	ctx := context.Background()
	conn, err := pgx.Connect(ctx, os.Getenv("DATABASE_URL"))
	if err != nil {
		log.Fatal(err)
	}
	defer conn.Close(ctx)

	fmt.Printf("%-8s %-8s %-8s %-8s %s\n", "input", "Go", "Go tr", "PG", `PG "tr-x-icu"`)
	for _, name := range []string{"IŞIL", "Isparta", "İsmail"} {
		var pg, pgTR string
		err := conn.QueryRow(ctx, `SELECT lower($1), lower($1 COLLATE "tr-x-icu")`, name).Scan(&pg, &pgTR)
		if err != nil {
			log.Fatal(err)
		}
		fmt.Printf("%-8s %-8s %-8s %-8s %s\n", name, strings.ToLower(name),
			strings.ToLowerSpecial(unicode.TurkishCase, name), pg, pgTR)
	}

	// One home: a unique index on the Turkish-aware expression. The app asks it
	// by inserting, and maps the violation to a domain error.
	_, err = conn.Exec(ctx, `CREATE TABLE users (username text NOT NULL);
		CREATE UNIQUE INDEX users_username_ci ON users (lower(username COLLATE "tr-x-icu"))`)
	if err != nil {
		log.Fatal(err)
	}
	for _, name := range []string{"ışıl", "IŞIL", "Işıl", "işil"} {
		fmt.Printf("sign up %-5s -> %v\n", name, signUp(ctx, conn, name))
	}
}

var ErrUsernameTaken = errors.New("username taken")

func signUp(ctx context.Context, conn *pgx.Conn, name string) error {
	_, err := conn.Exec(ctx, "INSERT INTO users (username) VALUES ($1)", name)
	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) && pgErr.ConstraintName == "users_username_ci" {
		return ErrUsernameTaken
	}
	return err
}

