-- LEARN(design.architecture.reliability): the server's half of an idempotency key, with two attempts racing.
-- A is the first attempt of a payment, B its retry; both carry the key k-7f3a.

A: BEGIN;
A: INSERT INTO idempotency_keys (key) VALUES ('k-7f3a') ON CONFLICT DO NOTHING RETURNING key;
B: BEGIN;
B: INSERT INTO idempotency_keys (key) VALUES ('k-7f3a') ON CONFLICT DO NOTHING RETURNING key;
A: WITH p AS (INSERT INTO payments (kurus) VALUES (125000) RETURNING id)
   UPDATE idempotency_keys SET payment_id = (SELECT id FROM p)
   WHERE key = 'k-7f3a' RETURNING payment_id;
A: COMMIT;
-- B got no row: someone else owns the key. Replay the stored result, charge nothing.
B: SELECT payment_id FROM idempotency_keys WHERE key = 'k-7f3a';
B: COMMIT;

-- Key k-9c1d: this time the first attempt fails before it commits.
A: BEGIN;
A: INSERT INTO idempotency_keys (key) VALUES ('k-9c1d') ON CONFLICT DO NOTHING RETURNING key;
B: BEGIN;
B: INSERT INTO idempotency_keys (key) VALUES ('k-9c1d') ON CONFLICT DO NOTHING RETURNING key;
A: ROLLBACK;
-- The key went with A's transaction, so B now owns it and does the work.
B: WITH p AS (INSERT INTO payments (kurus) VALUES (125000) RETURNING id)
   UPDATE idempotency_keys SET payment_id = (SELECT id FROM p)
   WHERE key = 'k-9c1d' RETURNING payment_id;
B: COMMIT;

A: SELECT k.key, k.payment_id, p.kurus
   FROM idempotency_keys AS k JOIN payments AS p ON p.id = k.payment_id ORDER BY k.key;

// LEARN(design.architecture.reliability): degrade per dependency, each with its own deadline, and say so.

// A stand-in backend: the lesson answers, recommendations hang, progress is down
// (503), and /healthz still says ok because it checks nothing.
function backend(path: string, signal?: AbortSignal): Promise<Response> {
  switch (path) {
    case "/api/lessons/go.basics.defer":
      return Promise.resolve(Response.json({ title: "Defer" }));
    case "/api/progress":
      return Promise.resolve(new Response("db down", { status: 503 }));
    case "/healthz":
      return Promise.resolve(new Response("ok"));
  }
  return new Promise((_, reject) => {
    const timer = setTimeout(() => reject(new Error("never answers")), 60_000);
    signal?.addEventListener("abort", () => {
      clearTimeout(timer);
      reject(signal.reason);
    });
  });
}

type Loaded<T> =
  | { source: "live"; value: T }
  | { source: "cached" | "default"; value: T; reason: string };

async function load<T>(path: string, ms: number, cached: T | undefined, dflt: T): Promise<Loaded<T>> {
  try {
    const res = await backend(path, AbortSignal.timeout(ms));
    if (!res.ok) throw new Error(`HTTP ${res.status}`); // fetch resolves on 503
    return { source: "live", value: (await res.json()) as T };
  } catch (e) {
    const timedOut = e instanceof DOMException && e.name === "TimeoutError";
    const reason = timedOut ? `no answer in ${ms} ms` : (e as Error).message;
    return cached !== undefined
      ? { source: "cached", value: cached, reason }
      : { source: "default", value: dflt, reason };
  }
}

// The lesson is critical: no fallback, a failure is an error page.
const lesson = (await (await backend("/api/lessons/go.basics.defer")).json()) as { title: string };
// The rest is optional: each call has its own budget, and they run in parallel.
const [recs, progress] = await Promise.all([
  load<string[]>("/api/recommendations", 100, undefined, []),
  load<string[]>("/api/progress", 500, ["go.basics.defer"], []),
]);

console.log("lesson:", lesson.title);
for (const [name, r] of [["recommendations", recs], ["progress", progress]] as const) {
  const why = r.source === "live" ? "" : ` (${r.reason})`;
  console.log(`${name.padEnd(15)} ${r.source.padEnd(7)} ${JSON.stringify(r.value)}${why}`);
}
const degraded = [recs, progress].filter((r) => r.source !== "live").length;
console.log(`banner: ${degraded} of 2 panels degraded`);

// A one-time start-up probe would have said "backend is fine" and never looked again.
const health = await backend("/healthz");
const api = await backend("/api/progress");
console.log("probe /healthz:", health.status, "| /api/progress:", api.status);

// LEARN(design.architecture.reliability): one structured event per request; liveness vs readiness.
package main

import (
	"context"
	"fmt"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"os"
	"sync/atomic"
	"time"
)

type eventKey struct{}

// annotate adds fields to the request's event; the middleware writes it once.
func annotate(ctx context.Context, attrs ...slog.Attr) {
	if ev, ok := ctx.Value(eventKey{}).(*[]slog.Attr); ok {
		*ev = append(*ev, attrs...)
	}
}

type statusRecorder struct {
	http.ResponseWriter
	status int
}

func (s *statusRecorder) WriteHeader(code int) { s.status = code; s.ResponseWriter.WriteHeader(code) }

func observe(log *slog.Logger, now func() time.Time, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start, ev := now(), &[]slog.Attr{}
		rec := &statusRecorder{ResponseWriter: w, status: http.StatusOK}
		r = r.WithContext(context.WithValue(r.Context(), eventKey{}, ev))
		next.ServeHTTP(rec, r) // the mux sets r.Pattern on this request, not the original
		log.LogAttrs(r.Context(), slog.LevelInfo, "request", append([]slog.Attr{
			slog.String("route", r.Pattern), // low cardinality, unlike r.URL.Path
			slog.Int("status", rec.status),
			slog.Duration("dur", now().Sub(start)),
		}, *ev...)...)
	})
}

func main() {
	var elapsed atomic.Int64 // a fake clock, so the durations below are stable
	now := func() time.Time { return time.Unix(0, elapsed.Load()) }
	var dbDown atomic.Bool
	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", func(http.ResponseWriter, *http.Request) {}) // alive: don't restart me
	mux.HandleFunc("GET /readyz", func(w http.ResponseWriter, r *http.Request) {
		if dbDown.Load() { // ready: send me traffic only while my dependencies work
			w.WriteHeader(http.StatusServiceUnavailable)
		}
	})
	mux.HandleFunc("GET /notes/{id}", func(w http.ResponseWriter, r *http.Request) {
		if dbDown.Load() {
			elapsed.Add(int64(2 * time.Second)) // the query ran into its own deadline
			annotate(r.Context(), slog.String("db", "timeout"), slog.String("note", r.PathValue("id")))
			w.WriteHeader(http.StatusServiceUnavailable)
			return
		}
		elapsed.Add(int64(12 * time.Millisecond))
		annotate(r.Context(), slog.String("db", "ok"))
	})
	noTime := func(_ []string, a slog.Attr) slog.Attr {
		if a.Key == slog.TimeKey {
			return slog.Attr{}
		}
		return a
	}
	h := observe(slog.New(slog.NewTextHandler(os.Stdout, &slog.HandlerOptions{ReplaceAttr: noTime})), now, mux)
	get := func(path string) { h.ServeHTTP(httptest.NewRecorder(), httptest.NewRequest("GET", path, nil)) }
	get("/notes/go.basics.defer")
	fmt.Println("-- the database goes down")
	dbDown.Store(true)
	get("/healthz")
	get("/readyz")
	get("/notes/sql.joins.inner")
}

