package main

import (
	"cmp"
	"fmt"
	"maps"
	"slices"
)

// A named type documents intent, but an untyped string constant is assignable
// to it: "pased" compiles wherever a Status is expected. The switch checks.
type Status string

const (
	Passed Status = "passed"
	Failed Status = "failed"
)

type Run struct {
	Req, Test string
	Status    Status
}

type Tally struct {
	Req            string
	Passed, Failed int
}

func report(runs []Run) ([]Tally, error) {
	byReq := map[string]Tally{}
	for _, r := range runs {
		t := byReq[r.Req] // a missing key gives the zero Tally, ready to count
		t.Req = r.Req
		switch r.Status {
		case Passed:
			t.Passed++
		case Failed:
			t.Failed++
		default:
			return nil, fmt.Errorf("run %s: unknown status %q", r.Test, r.Status)
		}
		byReq[r.Req] = t // t is a copy: store it back
	}
	return slices.SortedFunc(maps.Values(byReq), func(a, b Tally) int {
		return cmp.Or(cmp.Compare(b.Failed, a.Failed), cmp.Compare(a.Req, b.Req))
	}), nil
}

func main() {
	tallies, err := report([]Run{
		{"REQ-LOGIN", "TC-1", Passed}, {"REQ-LOGIN", "TC-2", Failed},
		{"REQ-LOGIN", "TC-3", Passed}, {"REQ-EXPORT", "TC-4", Passed},
		{"REQ-SEARCH", "TC-5", Failed}, {"REQ-SEARCH", "TC-6", Failed},
	})
	if err != nil {
		fmt.Println("error:", err)
		return
	}
	for _, t := range tallies {
		fmt.Printf("%-10s passed=%d failed=%d\n", t.Req, t.Passed, t.Failed)
	}

	_, err = report([]Run{{"REQ-LOGIN", "TC-7", "pased"}})
	fmt.Println("error:", err)
}

// LEARN(design.paradigms.side-by-side): TS types describe shapes; the checker enforces them, the runtime never sees them.
type Status = "passed" | "failed";

interface Run {
  readonly req: string;
  readonly test: string;
  readonly status: Status;
}

interface Tally {
  req: string;
  passed: number;
  failed: number;
}

function report(runs: readonly Run[]): Tally[] {
  const count = (rs: Run[], s: Status) => rs.filter((r) => r.status === s).length;
  return [...Map.groupBy(runs, (r) => r.req)]
    .map(([req, rs]) => ({ req, passed: count(rs, "passed"), failed: count(rs, "failed") }))
    .sort((a, b) => b.failed - a.failed || (a.req < b.req ? -1 : 1));
}

const run = (req: string, test: string, status: Status): Run => ({ req, test, status });
const tallies = report([
  run("REQ-LOGIN", "TC-1", "passed"),
  run("REQ-LOGIN", "TC-2", "failed"),
  run("REQ-LOGIN", "TC-3", "passed"),
  run("REQ-EXPORT", "TC-4", "passed"),
  run("REQ-SEARCH", "TC-5", "failed"),
  run("REQ-SEARCH", "TC-6", "failed"),
]);
for (const t of tallies) {
  console.log(`${t.req.padEnd(10)} passed=${t.passed} failed=${t.failed}`);
}

// report([run("REQ-LOGIN", "TC-7", "pased")]);
// error TS2345: Argument of type '"pased"' is not assignable to parameter of type 'Status'.

// Any object with the right shape fits, extra fields included. The cast is a
// promise the checker believes; nothing checks this data at run time.
const fromApi = JSON.parse('[{"req":"REQ-LOGIN","test":"TC-7","status":"pased","ms":12}]') as Run[];
console.log(report(fromApi));

