package main

import (
	"fmt"
	"sync"
)

// Stock is shared by every buyer goroutine, so its state is guarded.
type Stock struct {
	mu   sync.Mutex // guards left
	left int
}

// Reserve checks and writes under one lock: no other goroutine, on any
// core, can run between the check and the decrement.
func (s *Stock) Reserve() bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.left == 0 {
		return false
	}
	s.left--
	return true
}

func main() {
	s := &Stock{left: 10}
	results := make(chan bool, 20)

	var wg sync.WaitGroup
	for range 20 { // 20 buyers at once, in parallel where there are cores
		wg.Go(func() { results <- s.Reserve() })
	}
	wg.Wait()
	close(results)

	sold, refused := 0, 0
	for ok := range results {
		if ok {
			sold++
		} else {
			refused++
		}
	}
	fmt.Printf("sold %d, refused %d, left %d\n", sold, refused, s.left)
}

// LEARN(design.paradigms.concurrency): one thread and no data races, but every await lets other tasks run between a check and a write.
// Stands in for the payment call: any I/O that is awaited.
const pay = () => new Promise<void>((resolve) => setTimeout(resolve, 0));

let left = 10;

// Racy: the await sits between the check and the write.
async function reserveRacy(): Promise<boolean> {
  if (left === 0) return false;
  await pay();
  left--;
  return true;
}

// Fixed: check and write in one synchronous step, then await.
async function reserve(): Promise<boolean> {
  if (left === 0) return false;
  left--;
  await pay(); // if payment fails, put the item back: left++
  return true;
}

async function twentyBuyers(buy: () => Promise<boolean>): Promise<string> {
  left = 10;
  const results = await Promise.all(Array.from({ length: 20 }, () => buy()));
  const sold = results.filter((ok) => ok).length;
  return `sold ${sold}, refused ${20 - sold}, left ${left}`;
}

console.log(`racy:  ${await twentyBuyers(reserveRacy)}`);
console.log(`fixed: ${await twentyBuyers(reserve)}`);

export {}; // a module, so top-level await is allowed

-- LEARN(design.paradigms.concurrency): transactions run at once on snapshots; only writers of the same row wait for each other.
-- A: and B: are two connections, two buyers. Each product has one item left.
A: CREATE TABLE stock (sku text PRIMARY KEY, left_qty int NOT NULL CHECK (left_qty >= 0));
A: INSERT INTO stock VALUES ('racy', 1), ('fixed', 1);

-- Racy: read, decide in the application, write the value it computed.
A: BEGIN;
B: BEGIN;
A: SELECT left_qty FROM stock WHERE sku = 'racy';
B: SELECT left_qty FROM stock WHERE sku = 'racy';
A: UPDATE stock SET left_qty = 0 WHERE sku = 'racy';
B: UPDATE stock SET left_qty = 0 WHERE sku = 'racy';
A: COMMIT;
B: COMMIT;

-- Fixed: the check is part of the write.
A: BEGIN;
B: BEGIN;
A: UPDATE stock SET left_qty = left_qty - 1 WHERE sku = 'fixed' AND left_qty > 0;
B: SELECT left_qty FROM stock WHERE sku = 'fixed';
B: UPDATE stock SET left_qty = left_qty - 1 WHERE sku = 'fixed' AND left_qty > 0;
A: COMMIT;
B: COMMIT;

