package main

import (
	"cmp"
	"fmt"
	"slices"
)

// MinOf returns the smallest element, or the zero value and false. A type
// parameter has no "nothing" of its own, so absence travels as the bool.
func MinOf[T cmp.Ordered](xs []T) (T, bool) {
	if len(xs) == 0 {
		var zero T
		return zero, false
	}
	return slices.Min(xs), true // slices.Min panics on an empty slice
}

func main() {
	offers := map[string][]int64{ // prices in kuruş
		"kahve": {},
		"simit": {1500, 1250},
		"su":    {500, 0}, // a free promotion: 0 is a real price
	}
	for _, p := range []string{"ayran", "kahve", "simit", "su"} {
		prices, listed := offers[p] // missing key: a nil slice and false
		cheapest, ok := MinOf(prices)
		switch {
		case !listed:
			fmt.Printf("%-6s not listed\n", p)
		case !ok:
			fmt.Printf("%-6s no offers\n", p)
		default:
			fmt.Printf("%-6s cheapest %d\n", p, cheapest)
		}
	}

	// Drop the bools and three different situations print the same 0.
	missing, _ := MinOf(offers["ayran"])
	none, _ := MinOf(offers["kahve"])
	free, _ := MinOf(offers["su"])
	fmt.Println("without the bools:", missing, none, free)
}

// LEARN(design.paradigms.generics-absence): in TS absence is part of the type, T | undefined, and must be narrowed away.
function minOf<T>(xs: readonly T[], compare: (a: T, b: T) => number): T | undefined {
  if (xs.length === 0) return undefined; // reduce without a seed throws on []
  return xs.reduce((best, x) => (compare(x, best) < 0 ? x : best));
}

// Prices in kuruş; "ayran" is not listed at all.
const offers = new Map<string, number[]>([
  ["kahve", []],
  ["simit", [1500, 1250]],
  ["su", [500, 0]], // a free promotion: 0 is a real price
]);
const byPrice = (a: number, b: number) => a - b;

for (const p of ["ayran", "kahve", "simit", "su"]) {
  const prices = offers.get(p); // number[] | undefined
  if (prices === undefined) {
    console.log(`${p.padEnd(6)} not listed`);
    continue;
  }
  const cheapest = minOf(prices, byPrice); // number | undefined
  console.log(`${p.padEnd(6)} ${cheapest === undefined ? "no offers" : `cheapest ${cheapest}`}`);
}

// Shortcuts that turn absence into a wrong answer:
console.log(`Math.min() of no prices: ${Math.min(...[])}`);
console.log(`and in JSON: ${JSON.stringify({ cheapest: Math.min() })}`);
console.log(`free price with ||: ${minOf([0], byPrice) || "no offers"}`);
console.log(`free price with ??: ${minOf([0], byPrice) ?? "no offers"}`);

-- LEARN(design.paradigms.generics-absence): NULL belongs to every type; an aggregate over nothing returns it, and no row is not a NULL.
CREATE TABLE products (name text PRIMARY KEY);
CREATE TABLE offers (
  product     text NOT NULL REFERENCES products,
  price_kurus int CHECK (price_kurus >= 0) -- NULL: price on request
);
INSERT INTO products VALUES ('kahve'), ('simit'), ('su');
INSERT INTO offers VALUES
  ('simit', 1500), ('simit', 1250),
  ('su', 500), ('su', 0), ('su', NULL);

SELECT p.name,
       min(o.price_kurus)   AS cheapest,
       count(o.product)     AS offers,
       count(o.price_kurus) AS priced
FROM products p
LEFT JOIN offers o ON o.product = p.name
GROUP BY p.name
ORDER BY p.name;

-- 'ayran' isn't listed: asking for its row returns no row at all...
SELECT name FROM products WHERE name = 'ayran';

-- ...while an aggregate over no rows still returns one row.
SELECT min(price_kurus) AS cheapest, count(*) AS offers
FROM offers WHERE product = 'ayran';

-- Saying what NULL means, where the reader needs words instead of a gap.
SELECT p.name, coalesce(min(o.price_kurus)::text, 'no offers') AS cheapest
FROM products p
LEFT JOIN offers o ON o.product = p.name
GROUP BY p.name
ORDER BY p.name;

