package main

import (
	"fmt"
	"maps"
)

// PriceList is immutable by API: the map is unexported, nothing writes it
// after construction, and With returns a new list (copy-on-write).
type PriceList struct {
	prices map[string]int64 // kuruş
}

func NewPriceList(prices map[string]int64) PriceList {
	return PriceList{prices: maps.Clone(prices)} // keep no alias to the caller's map
}

func (p PriceList) Price(sku string) int64 { return p.prices[sku] }

func (p PriceList) With(sku string, kurus int64) PriceList {
	next := maps.Clone(p.prices)
	next[sku] = kurus
	return PriceList{prices: next}
}

// The trap, for comparison: a value receiver copies the struct, not the map.
func (p PriceList) SetInPlace(sku string, kurus int64) { p.prices[sku] = kurus }

type Order struct {
	ID     string
	Prices PriceList // the list the order was priced with
}

func main() {
	october := NewPriceList(map[string]int64{"ayran": 1000, "simit": 1250})
	order := Order{ID: "S-1", Prices: october}

	november := october.With("simit", 1500)
	fmt.Println("order S-1 simit:", order.Prices.Price("simit"))
	fmt.Println("current simit:  ", november.Price("simit"))

	copied := november // a new struct around the same map
	copied.SetInPlace("ayran", 0)
	fmt.Println("november ayran after writing to a copy:", november.Price("ayran"))
	fmt.Println("october ayran, isolated by With:       ", october.Price("ayran"))
}

// LEARN(design.paradigms.immutability): readonly is a compile-time promise, Object.freeze a shallow run-time one; a change is a new object.
type PriceList = Readonly<Record<string, number>>; // kuruş

const october: PriceList = Object.freeze({ ayran: 1000, simit: 1250 });
const order = { id: "S-1", prices: october };

// Copy-on-write: spread builds a new object and october is untouched.
const november: PriceList = Object.freeze({ ...october, simit: 1500 });
console.log(`order S-1 simit: ${order.prices.simit}`);
console.log(`current simit:   ${november.simit}`);

// november.ayran = 0;
// error TS2542: Index signature in type 'Readonly<Record<string, number>>' only permits reading.

// A cast removes readonly; only the freeze stops the write at run time
// (modules run in strict mode, so it throws instead of failing silently).
const writable = november as Record<string, number>;
try {
  writable.ayran = 0;
} catch (e) {
  console.log(`writing to a frozen list: ${(e as Error).name}`);
}

// Both freeze and Readonly<T> are shallow: the nested object is still writable.
const draft = Object.freeze({ id: "S-2", prices: { ...november } });
draft.prices.ayran = 0;
console.log(`frozen draft ayran after a write: ${draft.prices.ayran}`);

-- LEARN(design.paradigms.immutability): an INSERT-only table: a change is a new row, and the past is a query.
CREATE TABLE prices (
  sku        text NOT NULL,
  kurus      int  NOT NULL CHECK (kurus >= 0),
  valid_from date NOT NULL,
  PRIMARY KEY (sku, valid_from)
);

-- Refuse UPDATE, DELETE and TRUNCATE; only the owner or a superuser can undo this.
CREATE FUNCTION refuse_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION '% is append-only: % refused', TG_TABLE_NAME, TG_OP;
END $$;
CREATE TRIGGER prices_append_only
  BEFORE UPDATE OR DELETE OR TRUNCATE ON prices
  FOR EACH STATEMENT EXECUTE FUNCTION refuse_change();

INSERT INTO prices VALUES ('ayran', 1000, '2026-10-01'), ('simit', 1250, '2026-10-01');
-- The November price change is a new row; October's stays as it was.
INSERT INTO prices VALUES ('simit', 1500, '2026-11-01');

-- What order S-1, placed on 20 October, was charged.
SELECT kurus FROM prices
WHERE sku = 'simit' AND valid_from <= '2026-10-20'
ORDER BY valid_from DESC
LIMIT 1;

-- The current list: the newest row per sku.
SELECT DISTINCT ON (sku) sku, kurus, valid_from
FROM prices
ORDER BY sku, valid_from DESC;

UPDATE prices SET kurus = 0 WHERE sku = 'ayran';

