// LEARN(design.patterns.constructors): a builder earns its place when construction accumulates; its errors stick.
package main

import (
	"fmt"
	"strings"
)

// Query accumulates conditions and their arguments over several calls. Each
// method returns the receiver so calls chain, and the first error sticks.
type Query struct {
	where []string
	args  []any
	order string
	err   error
}

// Where takes a condition with one ? and its value. The builder numbers the
// placeholders, so no caller can get $3 wrong or splice a value into the SQL.
func (q *Query) Where(cond string, value any) *Query {
	q.args = append(q.args, value)
	q.where = append(q.where, strings.Replace(cond, "?", fmt.Sprintf("$%d", len(q.args)), 1))
	return q
}

// Column names can't be parameters: map public sort keys to fixed SQL.
var sortKeys = map[string]string{"title": "title", "newest": "created_at DESC"}

func (q *Query) OrderBy(key string) *Query {
	col, ok := sortKeys[key]
	if !ok && q.err == nil {
		q.err = fmt.Errorf("unknown sort key %q", key)
	}
	q.order = col
	return q
}

// Build is the one place the error surfaces, like bufio.Writer's Flush.
func (q *Query) Build() (string, []any, error) {
	if q.err != nil {
		return "", nil, q.err
	}
	sql := "SELECT id, title FROM lessons"
	if len(q.where) > 0 {
		sql += " WHERE " + strings.Join(q.where, " AND ")
	}
	if q.order != "" {
		sql += " ORDER BY " + q.order
	}
	return sql, q.args, nil
}

func main() {
	// A search form: any subset of the filters may be filled in.
	forms := []struct{ track, level, sort string }{
		{track: "go", sort: "newest"},
		{track: "sql", level: "advanced", sort: "title"},
		{level: "basic", sort: "title; DROP TABLE lessons"},
	}
	for _, f := range forms {
		q := &Query{}
		if f.track != "" {
			q.Where("track = ?", f.track)
		}
		if f.level != "" {
			q.Where("level = ?", f.level)
		}
		sql, args, err := q.OrderBy(f.sort).Build()
		if err != nil {
			fmt.Println("error:", err)
			continue
		}
		fmt.Printf("%s\n  args %q\n", sql, args)
	}
}

// LEARN(design.patterns.constructors): a composition root wires once; React context is the injection channel.
import { createContext, useContext, useEffect, useState } from "react";
import { flushSync } from "react-dom";
import { createRoot } from "react-dom/client";

// The port, declared by the code that uses it.
type Progress = { completed(): Promise<string[]> };

// Factory: a function that closes over its configuration and returns the object.
function httpProgress(opts: { baseUrl: string; fetch: typeof fetch }): Progress {
  return {
    async completed() {
      const res = await opts.fetch(`${opts.baseUrl}/api/progress`);
      if (!res.ok) throw new Error(`GET /api/progress: ${res.status}`);
      const rows: { lessonId: string; status: string }[] = await res.json();
      return rows.filter((r) => r.status === "completed").map((r) => r.lessonId);
    },
  };
}

const ProgressContext = createContext<Progress | null>(null);
function useProgress(): Progress {
  const p = useContext(ProgressContext);
  if (!p) throw new Error("no Progress provided: wire it in the composition root");
  return p;
}

function Completed() {
  const progress = useProgress(); // the component names what it needs, not where it comes from
  const [ids, setIds] = useState<string[] | null>(null);
  useEffect(() => {
    progress.completed().then(setIds);
  }, [progress]);
  return <p>{ids === null ? "loading" : `completed: ${ids.join(", ") || "none"}`}</p>;
}

// Render, then give the effect's promise a few turns to land.
async function mount(progress: Progress, label: string) {
  const el = document.createElement("div");
  const root = createRoot(el);
  flushSync(() =>
    root.render(
      <ProgressContext.Provider value={progress}>
        <Completed />
      </ProgressContext.Provider>,
    ),
  );
  for (let i = 0; i < 10 && el.textContent === "loading"; i++) {
    await new Promise((r) => setTimeout(r, 0));
  }
  console.log(label.padEnd(14), el.textContent);
  root.unmount();
}

const backend: typeof fetch = async () =>
  Response.json([
    { lessonId: "go.basics.defer", status: "completed" },
    { lessonId: "sql.basics.select", status: "viewed" },
  ]);
// Composition roots: the only lines that name concrete implementations.
await mount(httpProgress({ baseUrl: "http://127.0.0.1:8080", fetch: backend }), "production:");
await mount({ completed: async () => ["design.patterns.classic"] }, "test fake:");

-- LEARN(design.patterns.constructors): search_path is the database's wiring, and binding time matters.

-- Two implementations of one name, in two schemas.
CREATE SCHEMA catalog_live;
CREATE SCHEMA catalog_fixture;
CREATE TABLE catalog_live.lessons (id text PRIMARY KEY, minutes int NOT NULL);
CREATE TABLE catalog_fixture.lessons (LIKE catalog_live.lessons INCLUDING ALL);
INSERT INTO catalog_live.lessons VALUES ('go.basics.defer', 9), ('sql.basics.select', 12);
INSERT INTO catalog_fixture.lessons VALUES ('fixture', 1);

SET LOCAL search_path = catalog_live;

-- A string body is parsed at each call: "lessons" is looked up late.
CREATE FUNCTION minutes_late() RETURNS bigint LANGUAGE sql
    AS $$ SELECT sum(minutes) FROM lessons $$;
-- A SQL-standard body (PG 14) is parsed now: "lessons" is bound at creation.
CREATE FUNCTION minutes_bound() RETURNS bigint LANGUAGE sql
    RETURN (SELECT sum(minutes) FROM lessons);
-- A pinned search_path: late lookup, but in a fixed place.
CREATE FUNCTION minutes_pinned() RETURNS bigint LANGUAGE sql
    SET search_path = catalog_live
    AS $$ SELECT sum(minutes) FROM lessons $$;

SELECT minutes_late(), minutes_bound(), minutes_pinned();

-- The caller changes the path, as a test, a tenant switch or an attacker might.
SET LOCAL search_path = catalog_fixture, catalog_live;
SELECT minutes_late(), minutes_bound(), minutes_pinned();

-- The early-bound function is a recorded dependency of the table it uses.
DROP TABLE catalog_live.lessons;

