// LEARN(design.patterns.anti-patterns): getters, setters and a rule in a service vs a type that keeps its invariant.
package main

import (
	"errors"
	"fmt"
)

// Java-shaped: an interface for the only implementation, Get/Set pairs, and
// the rule kept in a service that any caller can walk around.
type IAccount interface {
	GetBalance() int
	SetBalance(int)
}

type accountImpl struct{ balance int }

func (a *accountImpl) GetBalance() int  { return a.balance }
func (a *accountImpl) SetBalance(b int) { a.balance = b }

type AccountService struct{}

func (AccountService) Withdraw(a IAccount, amount int) error {
	if a.GetBalance() < amount {
		return errors.New("insufficient funds")
	}
	a.SetBalance(a.GetBalance() - amount)
	return nil
}

// Go-shaped: the type owns its rule. The getter is Balance, not GetBalance,
// and there is no setter, because no caller should set a balance.
type Account struct{ balance int }

var ErrInsufficient = errors.New("insufficient funds")

func (a *Account) Balance() int { return a.balance }

func (a *Account) Withdraw(amount int) error {
	if amount <= 0 {
		return fmt.Errorf("withdraw %d: amount must be positive", amount)
	}
	if a.balance < amount {
		return ErrInsufficient
	}
	a.balance -= amount
	return nil
}

func show(who string, err error, balance int) {
	fmt.Printf("%-8s balance=%-4d err=%v\n", who, balance, err)
}

func main() {
	var anemic IAccount = &accountImpl{balance: 100}
	err := AccountService{}.Withdraw(anemic, -400) // a negative withdrawal deposits
	show("anemic", err, anemic.GetBalance())
	anemic.SetBalance(-50) // or skip the service altogether
	show("anemic", nil, anemic.GetBalance())

	acc := &Account{balance: 100}
	for _, amount := range []int{-400, 150, 30} {
		err := acc.Withdraw(amount)
		show("account", err, acc.Balance())
	}
}

// LEARN(design.patterns.anti-patterns): a deep class hierarchy vs a discriminated union with an exhaustive switch.

// Java-shaped: each level overrides a little, and defaults live far away.
class Item {
  constructor(readonly title: string) {}
  minutes(): number {
    return 15; // a "sensible default" for every subclass, forever
  }
  label() {
    return `${this.title}: ${this.minutes()} min`;
  }
}
class Lesson extends Item {
  constructor(title: string, readonly examples: number) {
    super(title);
  }
  minutes() {
    return 4 + 3 * this.examples;
  }
}
class SqlLesson extends Lesson {
  label() {
    return `[sql] ${super.label()}`;
  }
}
// Added months later: "an exam is a kind of lesson", so it extends Lesson.
class Exam extends Lesson {
  constructor(title: string, readonly questions: number) {
    super(title, 0);
  }
}

for (const item of [new Lesson("Defer", 2), new SqlLesson("Joins", 3), new Exam("Final", 30)]) {
  console.log("class:", item.label());
}

// TS-shaped: the variants are data; behaviour is a function over the union.
type Content =
  | { kind: "lesson"; title: string; examples: number; sql: boolean }
  | { kind: "exam"; title: string; questions: number };

function minutes(c: Content): number {
  switch (c.kind) {
    case "lesson":
      return 4 + 3 * c.examples;
    case "exam":
      return 2 * c.questions;
  }
}
const label = (c: Content) =>
  `${c.kind === "lesson" && c.sql ? "[sql] " : ""}${c.title}: ${minutes(c)} min`;

const items: Content[] = [
  { kind: "lesson", title: "Defer", examples: 2, sql: false },
  { kind: "lesson", title: "Joins", examples: 3, sql: true },
  { kind: "exam", title: "Final", questions: 30 },
];
for (const c of items) console.log("union:", label(c));

// Add | { kind: "project"; title: string; days: number } to Content and tsc stops at minutes:
// error TS2366: Function lacks ending return statement and return type does not include 'undefined'.

// LEARN(design.patterns.anti-patterns): row by row from Go fights SQL; a set-based statement doesn't.
package main

import (
	"context"
	"fmt"
	"log"
	"os"

	"github.com/jackc/pgx/v5"
)

// statements is a pgx QueryTracer: it counts every Query, QueryRow and Exec.
type statements struct{ n int }

func (s *statements) TraceQueryStart(ctx context.Context, _ *pgx.Conn, _ pgx.TraceQueryStartData) context.Context {
	s.n++
	return ctx
}
func (s *statements) TraceQueryEnd(context.Context, *pgx.Conn, pgx.TraceQueryEndData) {}

// newPrice is the business rule: add 10 %, round to whole lira.
func newPrice(kurus int) int { return (kurus*110/100 + 50) / 100 * 100 }

func main() {
	ctx := context.Background()
	cfg, err := pgx.ParseConfig(os.Getenv("DATABASE_URL"))
	check(err)
	sent := &statements{}
	cfg.Tracer = sent
	conn, err := pgx.ConnectConfig(ctx, cfg)
	check(err)
	defer conn.Close(ctx)
	_, err = conn.Exec(ctx, `CREATE TABLE a (sku text PRIMARY KEY, kurus int NOT NULL);
		INSERT INTO a SELECT 'sku-' || i, 1999 * i FROM generate_series(1, 300) AS i;
		CREATE TABLE b AS TABLE a; CREATE TABLE c AS TABLE a`)
	check(err)

	// Java/ORM habit: load the rows, loop, save each one (and commit each one).
	sent.n = 0
	type price struct {
		SKU   string
		Kurus int
	}
	rows, _ := conn.Query(ctx, "SELECT sku, kurus FROM a")
	all, err := pgx.CollectRows(rows, pgx.RowToStructByPos[price])
	check(err)
	for _, p := range all {
		_, err := conn.Exec(ctx, "UPDATE a SET kurus = $1 WHERE sku = $2", newPrice(p.Kurus), p.SKU)
		check(err)
	}
	fmt.Println("row by row:     ", sent.n, "statements")

	// The rule stays in Go, but the write is one statement over two arrays.
	sent.n = 0
	skus, prices := make([]string, len(all)), make([]int, len(all))
	for i, p := range all {
		skus[i], prices[i] = p.SKU, newPrice(p.Kurus)
	}
	_, err = conn.Exec(ctx, `UPDATE b SET kurus = v.kurus
		FROM unnest($1::text[], $2::int[]) AS v(sku, kurus) WHERE b.sku = v.sku`, skus, prices)
	check(err)
	fmt.Println("arrays:         ", sent.n, "statement (the read is reused)")

	// The rule in SQL: say what must be true of every row, once.
	sent.n = 0
	_, err = conn.Exec(ctx, "UPDATE c SET kurus = (kurus * 110 / 100 + 50) / 100 * 100")
	check(err)
	fmt.Println("set-based:      ", sent.n, "statement")
	var diff int
	check(conn.QueryRow(ctx, `SELECT count(*) FROM a JOIN b USING (sku) JOIN c USING (sku)
		WHERE a.kurus <> b.kurus OR a.kurus <> c.kurus`).Scan(&diff))
	fmt.Println("rows that differ:", diff)
}

func check(err error) {
	if err != nil {
		log.Fatal(err)
	}
}

