// --- internal/store as sqlc writes it (db.go, models.go, requirements.sql.go), typed out.
type DBTX interface {
	Exec(context.Context, string, ...any) (pgconn.CommandTag, error)
	Query(context.Context, string, ...any) (pgx.Rows, error)
	QueryRow(context.Context, string, ...any) pgx.Row
}

type Queries struct{ db DBTX }

func New(db DBTX) *Queries { return &Queries{db: db} }

type Requirement struct { // one field per column, in table order (the table is abridged)
	ID        uuid.UUID
	ProjectID uuid.UUID
	ParentID  *uuid.UUID // parent_id is nullable
	Code      string
	Title     string
	Status    string
}

// From this query in queries/requirements.sql:
//
//	-- name: CreateRequirement :one
//	INSERT INTO requirements (project_id, parent_id, code, title)
//	VALUES (@project_id, @parent_id, @code, @title) RETURNING *;
const createRequirement = `-- name: CreateRequirement :one
INSERT INTO requirements (project_id, parent_id, code, title)
VALUES ($1, $2, $3, $4) RETURNING id, project_id, parent_id, code, title, status
`

type CreateRequirementParams struct {
	ProjectID uuid.UUID
	ParentID  *uuid.UUID
	Code      string
	Title     string
}

func (q *Queries) CreateRequirement(ctx context.Context, arg CreateRequirementParams) (Requirement, error) {
	row := q.db.QueryRow(ctx, createRequirement, arg.ProjectID, arg.ParentID, arg.Code, arg.Title)
	var i Requirement
	err := row.Scan(&i.ID, &i.ProjectID, &i.ParentID, &i.Code, &i.Title, &i.Status)
	return i, err
}

func main() {
	ctx := context.Background()
	conn, err := pgx.Connect(ctx, os.Getenv("DATABASE_URL"))
	if err == nil {
		_, err = conn.Exec(ctx, schema)
	}
	if err != nil {
		log.Fatal(err)
	}
	defer conn.Close(ctx)
	q := New(conn) // a pool, a connection or a transaction: all satisfy DBTX
	project := uuid.MustParse("01937b6e-0000-7000-8000-00000000000a")
	auth, err := q.CreateRequirement(ctx, CreateRequirementParams{project, nil, "AUTH", "Kimlik doğrulama"})
	fmt.Printf("AUTH: parent=%v status=%s err=%v\n", auth.ParentID, auth.Status, err)
	_, err = q.CreateRequirement(ctx, CreateRequirementParams{project, nil, "AUTH", "Yine"})
	fmt.Println("duplicate:", err) // the driver's error, untranslated
}

const schema = `CREATE TABLE projects (id uuid PRIMARY KEY);
INSERT INTO projects VALUES ('01937b6e-0000-7000-8000-00000000000a');
CREATE TABLE requirements (id uuid PRIMARY KEY DEFAULT uuidv7(), project_id uuid NOT NULL REFERENCES projects,
  parent_id uuid, code text COLLATE "C" NOT NULL, title text NOT NULL, status text NOT NULL DEFAULT 'draft',
  CONSTRAINT requirements_code_key UNIQUE (project_id, code))`

package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"os"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"
)

// --- Generated, abridged (example 1 has the full shape).
type DBTX interface {
	Exec(context.Context, string, ...any) (pgconn.CommandTag, error)
}
type Queries struct{ db DBTX }

func (q *Queries) WithTx(tx pgx.Tx) *Queries { return &Queries{db: tx} }

func (q *Queries) CreateRequirement(ctx context.Context, code string) error {
	_, err := q.db.Exec(ctx, "INSERT INTO requirements (code) VALUES ($1)", code)
	return err
}

// --- store.go, hand-written.
var ErrDuplicateCode = errors.New("duplicate code")

type Store struct {
	db *pgxpool.Pool
	q  *Queries // on the pool: for single statements, outside any transaction
}

// WithTx runs fn on Queries bound to one transaction: commit if fn returns nil, else roll back.
func (s *Store) WithTx(ctx context.Context, fn func(q *Queries) error) error {
	return pgx.BeginFunc(ctx, s.db, func(tx pgx.Tx) error { return fn(s.q.WithTx(tx)) })
}

// storeError turns what PostgreSQL reported into the store's vocabulary.
func storeError(err error) error {
	if pgErr, ok := errors.AsType[*pgconn.PgError](err); ok && pgErr.ConstraintName == "requirements_code_key" {
		return ErrDuplicateCode
	}
	return err
}

func main() {
	ctx := context.Background()
	pool, err := pgxpool.New(ctx, os.Getenv("DATABASE_URL"))
	if err == nil {
		_, err = pool.Exec(ctx, `CREATE TABLE requirements (code text CONSTRAINT requirements_code_key UNIQUE)`)
	}
	if err != nil {
		log.Fatal(err)
	}
	defer pool.Close()
	store := &Store{db: pool, q: &Queries{db: pool}}

	// An import of three rows, the third a duplicate: all of them, or none.
	importAll := func(q *Queries) error {
		for _, code := range []string{"AUTH", "EXPORT", "AUTH"} {
			if err := q.CreateRequirement(ctx, code); err != nil {
				return err
			}
		}
		return nil
	}
	var rows int
	err = store.WithTx(ctx, func(q *Queries) error { return importAll(q) })
	pool.QueryRow(ctx, "SELECT count(*) FROM requirements").Scan(&rows)
	fmt.Printf("through q:       %v, %d rows left\n", storeError(err), rows)

	err = store.WithTx(ctx, func(q *Queries) error { return importAll(store.q) })
	pool.QueryRow(ctx, "SELECT count(*) FROM requirements").Scan(&rows)
	fmt.Printf("through store.q: %v, %d rows left\n", storeError(err), rows)
}

-- LEARN(fullstack.tracelite.step-03-store): MoveRequirement's statements, in two sessions at once.
-- A moves AUTH under EXPORT, B moves EXPORT under AUTH. Each move is legal on its own.

-- Step 2's walk up from the new parent: does it reach the moved requirement?
A: CREATE FUNCTION would_cycle(moved text, new_parent text) RETURNS boolean LANGUAGE sql AS $$
     WITH RECURSIVE up AS (
       SELECT id, parent_id FROM requirements WHERE code = new_parent
       UNION ALL SELECT r.id, r.parent_id FROM requirements r JOIN up ON r.id = up.parent_id
     ) CYCLE id SET is_cycle USING path
     SELECT EXISTS (SELECT FROM up JOIN requirements m USING (id) WHERE m.code = moved) $$;

-- 1. Check, then write, without a lock.
A: BEGIN;
B: BEGIN;
A: SELECT would_cycle('AUTH', 'EXPORT');
B: SELECT would_cycle('EXPORT', 'AUTH');
A: UPDATE requirements SET parent_id = (SELECT id FROM requirements WHERE code = 'EXPORT') WHERE code = 'AUTH';
B: UPDATE requirements SET parent_id = (SELECT id FROM requirements WHERE code = 'AUTH') WHERE code = 'EXPORT';
A: COMMIT;
B: COMMIT;
A: SELECT r.code, p.code AS parent FROM requirements r JOIN requirements p ON p.id = r.parent_id ORDER BY r.code;
A: UPDATE requirements SET parent_id = NULL;

-- 2. What MoveRequirement does: lock the project row, then check, then write.
A: BEGIN;
B: BEGIN;
A: SELECT p.name FROM projects p JOIN requirements r ON r.project_id = p.id WHERE r.code = 'AUTH' FOR UPDATE OF p;
B: SELECT p.name FROM projects p JOIN requirements r ON r.project_id = p.id WHERE r.code = 'EXPORT' FOR UPDATE OF p;
A: SELECT would_cycle('AUTH', 'EXPORT');
A: UPDATE requirements SET parent_id = (SELECT id FROM requirements WHERE code = 'EXPORT') WHERE code = 'AUTH';
A: COMMIT;
B: SELECT would_cycle('EXPORT', 'AUTH');
B: ROLLBACK;

