// LEARN(fullstack.tracelite.step-09-realtime): a trigger NOTIFYs at commit, one Go connection LISTENs, a hub fans out per project, and SSE carries it to the browser.
package main

import (
	"context"
	"encoding/json/v2"
	"fmt"
	"log"
	"os"
	"time"
	"uuid"

	"github.com/jackc/pgx/v5"
)

// Listen keeps one dedicated connection LISTENing, for the life of the server.
func Listen(ctx context.Context, dsn string, publish func(uuid.UUID, string), resync func()) {
	for ctx.Err() == nil {
		err := listen(ctx, dsn, publish, resync)
		log.Printf("listener: %v; reconnecting in 1 s", err)
		time.Sleep(time.Second)
	}
}

func listen(ctx context.Context, dsn string, publish func(uuid.UUID, string), resync func()) error {
	conn, err := pgx.Connect(ctx, dsn)
	if err != nil {
		return err
	}
	defer conn.Close(context.WithoutCancel(ctx))
	if _, err := conn.Exec(ctx, "LISTEN tracelite_changes"); err != nil {
		return err
	}
	resync() // only now: whatever changed before this point was not heard
	for {
		n, err := conn.WaitForNotification(ctx)
		if err != nil {
			return err
		}
		var change struct {
			ProjectID uuid.UUID `json:"projectId"`
			Topic     string    `json:"topic"`
		}
		if err := json.Unmarshal([]byte(n.Payload), &change); err != nil {
			return err // unknown change: reconnecting resyncs everyone
		}
		publish(change.ProjectID, change.Topic)
	}
}

func main() {
	ctx, dsn := context.Background(), os.Getenv("DATABASE_URL")
	db, err := pgx.Connect(ctx, dsn)
	if err != nil {
		log.Fatal(err)
	}
	exec := func(sql string) {
		if _, err := db.Exec(ctx, sql); err != nil {
			log.Fatal(err)
		}
	}
	migration, _ := os.ReadFile("migrations/002_change_events.sql") // this example's fixture
	exec(schema + string(migration))
	calls := make(chan string) // stands in for the hub of example 2
	publish := func(p uuid.UUID, topic string) { calls <- "Publish(" + p.String() + ", " + topic + ")" }
	go Listen(ctx, dsn, publish, func() { calls <- "Resync()" })
	fmt.Println("LISTEN is active:", <-calls)
	exec("INSERT INTO trace_links SELECT '01937b6e-0000-7000-8000-00000000000a' FROM generate_series(1, 3)")
	fmt.Println("three links, one statement:", <-calls)
	exec("INSERT INTO test_runs SELECT id FROM test_cases")
	fmt.Println("a test run, whose project is found through test_cases:", <-calls)
	exec("SELECT pg_terminate_backend(pid) FROM pg_stat_activity WHERE query = 'LISTEN tracelite_changes'")
	fmt.Println("the listener's connection was killed:", <-calls)
}

// Only the columns migration 002 reads; one test case of project Ödeme.
const schema = `CREATE TABLE requirements (project_id uuid); CREATE TABLE trace_links (project_id uuid);
CREATE TABLE test_cases (id uuid, project_id uuid); CREATE TABLE test_runs (test_case_id uuid);
INSERT INTO test_cases VALUES (uuidv7(), '01937b6e-0000-7000-8000-00000000000a');
`

package main

import (
	"fmt"
	"sync"
	"uuid"
)

// Hub (internal/events) hands each event, a topic to refetch, to its project's streams.
type Hub struct {
	mu   sync.Mutex
	subs map[chan string]uuid.UUID // every open stream, and its project
}

func (h *Hub) Subscribe(project uuid.UUID) (<-chan string, func()) {
	ch := make(chan string, 8)
	h.mu.Lock()
	defer h.mu.Unlock()
	h.subs[ch] = project
	return ch, func() {
		h.mu.Lock()
		defer h.mu.Unlock()
		h.drop(ch)
	}
}

func (h *Hub) Publish(project uuid.UUID, topic string) {
	h.mu.Lock()
	defer h.mu.Unlock()
	for ch, p := range h.subs {
		if p == project {
			h.send(ch, topic)
		}
	}
}

func (h *Hub) Resync() {
	h.mu.Lock()
	defer h.mu.Unlock()
	for ch := range h.subs {
		h.send(ch, "resync")
	}
}

// send and drop run with h.mu held.
func (h *Hub) send(ch chan string, topic string) {
	select {
	case ch <- topic:
	default: // eight unread events: end the stream; its browser reconnects and refetches
		h.drop(ch)
	}
}

func (h *Hub) drop(ch chan string) {
	if _, ok := h.subs[ch]; ok { // the hub and the stream's handler may both drop it
		delete(h.subs, ch)
		close(ch)
	}
}

func main() {
	odeme, raporlama := uuid.New(), uuid.New()
	hub := &Hub{subs: map[chan string]uuid.UUID{}}
	tab, closeTab := hub.Subscribe(odeme)
	stalled, _ := hub.Subscribe(odeme) // a tab that stopped reading
	other, _ := hub.Subscribe(raporlama)
	for range 9 {
		hub.Publish(odeme, "trace-links")
		<-tab // this tab keeps up
	}
	n := 0
	for range stalled { // ends because the hub closed the channel
		n++
	}
	fmt.Println("stalled tab:", n, "events, then closed; Raporlama's stream:", len(other), "events")
	hub.Resync()
	fmt.Println("after Resync:", <-tab, <-other)
	closeTab()
	fmt.Println("open streams:", len(hub.subs))
}

package main

import (
	"bufio"
	"context"
	"fmt"
	"io"
	"log"
	"net/http"
	"net/http/httptest"
	"time"
	"uuid"
)

// GET /api/projects/{projectId}/events
func eventsHandler(exists func(uuid.UUID) bool, subscribe func(uuid.UUID) (<-chan string, func())) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		project, err := uuid.Parse(r.PathValue("projectId"))
		if err != nil || !exists(project) {
			http.Error(w, "no such project", http.StatusNotFound) // writeError in TraceLite
			return
		}
		events, unsubscribe := subscribe(project)
		defer unsubscribe()
		w.Header().Set("Content-Type", "text/event-stream")
		w.Header().Set("Cache-Control", "no-cache")
		rc := http.NewResponseController(w)
		rc.SetWriteDeadline(time.Time{}) // a stream must outlive any server WriteTimeout
		io.WriteString(w, "retry: 3000\n\n")
		ping := time.NewTicker(25 * time.Second)
		defer ping.Stop()
		for {
			if err := rc.Flush(); err != nil {
				return
			}
			select {
			case topic, ok := <-events:
				if !ok {
					return // dropped by the hub: EventSource reconnects and refetches
				}
				fmt.Fprintf(w, "event: %s\ndata: {\"topic\":%q}\n\n", topic, topic)
			case <-ping.C:
				io.WriteString(w, ": ping\n\n")
			case <-r.Context().Done():
				return // the tab closed
			}
		}
	}
}

func main() {
	odeme := uuid.MustParse("01937b6e-0000-7000-8000-00000000000a")
	events, unsubscribed := make(chan string), make(chan bool)
	subscribe := func(uuid.UUID) (<-chan string, func()) { return events, func() { close(unsubscribed) } }
	mux := http.NewServeMux()
	mux.Handle("GET /api/projects/{projectId}/events", eventsHandler(func(p uuid.UUID) bool { return p == odeme }, subscribe))
	srv := httptest.NewServer(mux)
	defer srv.Close()
	open := func(ctx context.Context, project uuid.UUID) *http.Response {
		req, _ := http.NewRequestWithContext(ctx, "GET", srv.URL+"/api/projects/"+project.String()+"/events", nil)
		resp, err := http.DefaultClient.Do(req)
		if err != nil {
			log.Fatal(err)
		}
		fmt.Println(resp.Status, resp.Header.Get("Content-Type"))
		return resp
	}
	open(context.Background(), uuid.New()) // an unknown project
	ctx, closeTab := context.WithCancel(context.Background())
	stream := bufio.NewReader(open(ctx, odeme).Body)
	events <- "trace-links"
	events <- "resync"
	for range 8 {
		line, _ := stream.ReadString('\n')
		fmt.Printf("%q\n", line)
	}
	closeTab()
	<-unsubscribed // the handler saw the request end and unsubscribed
	fmt.Println("tab closed, unsubscribed")
}

import {
  QueryClient,
  QueryClientProvider,
  useQuery,
  useQueryClient,
} from "@tanstack/react-query";
import { useEffect, useState } from "react";
import { flushSync } from "react-dom";
import { createRoot } from "react-dom/client";
interface Source {
  readonly readyState: number; // 0 connecting, 1 open, 2 closed for good
  addEventListener(type: string, listener: () => void): void;
  close(): void;
}
type Live = "connecting" | "live" | "reconnecting" | "closed";
const topics = ["requirements", "trace-links", "test-runs", "resync"];
function useProjectEvents(id: string, connect: (url: string) => Source) {
  const client = useQueryClient();
  const [state, setState] = useState<Live>("connecting");
  useEffect(() => {
    const source = connect(`/api/projects/${id}/events`);
    const refetch = () =>
      client.invalidateQueries({ queryKey: ["projects", id] });
    source.addEventListener("open", () => {
      setState("live");
      refetch(); // whatever changed while there was no stream
    });
    source.addEventListener("error", () =>
      setState(source.readyState === 2 ? "closed" : "reconnecting"),
    );
    for (const topic of topics) source.addEventListener(topic, refetch);
    return () => source.close();
  }, [id, client, connect]);
  return state;
}
// --- Harness: the iframe has no network, so the script plays the server.
const source = Object.assign(new EventTarget(), {
  readyState: 0,
  close: () => console.log("unmounted: the page closed the stream"),
});
function emit(type: string, readyState = source.readyState) {
  source.readyState = readyState;
  source.dispatchEvent(new Event(type));
}
const connect = () => source;
let requests = 0;
function Matrix({ id }: { id: string }) {
  const state = useProjectEvents(id, connect);
  const { data } = useQuery({
    queryKey: ["projects", id, "trace-links"],
    queryFn: async () => ++requests, // stands in for request()
  });
  return `${state}, requests: ${data}`;
}
const client = new QueryClient({
  defaultOptions: { queries: { gcTime: Infinity } },
});
const host = document.createElement("div");
const root = createRoot(host);
flushSync(() =>
  root.render(
    <QueryClientProvider client={client}>
      <Matrix id="01937b6e-0000-7000-8000-00000000000a" />
    </QueryClientProvider>,
  ),
);
async function step(what: string, action: () => void) {
  action();
  do await new Promise((r) => setTimeout(r, 0));
  while (client.isFetching() > 0);
  await new Promise((r) => setTimeout(r, 0)); // renders come in a 0 ms timer
  console.log(`${what.padEnd(32)} ${host.textContent}`);
}
await step("mounted", () => {});
await step("the stream opens", () => emit("open", 1));
await step("a trace-links event", () => emit("trace-links"));
await step("the network drops", () => emit("error", 0));
await step("EventSource reconnects by itself", () => emit("open", 1));
await step("the server refuses a reconnect", () => emit("error", 2));
