// LEARN(fullstack.tracelite.step-10-external): every call to another service has a deadline, a reason to retry or not, and a cached answer to fall back on.
package main

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strconv"
	"sync/atomic"
	"time"
)

var (
	ErrUnknownClause = errors.New("no such clause")
	errTransient     = errors.New("may go away") // a network error, a timeout, 429 or 5xx
)

// try is one attempt. For 429 and 5xx it also returns the server's Retry-After.
func try(ctx context.Context, client *http.Client, clauseURL string) (string, time.Duration, error) {
	ctx, cancel := context.WithTimeout(ctx, 300*time.Millisecond) // 2 s in TraceLite
	defer cancel()
	req, err := http.NewRequestWithContext(ctx, "GET", clauseURL, nil)
	if err != nil {
		return "", 0, err
	}
	resp, err := client.Do(req)
	if err != nil {
		return "", 0, fmt.Errorf("%w: %w", errTransient, err)
	}
	defer resp.Body.Close()
	switch code := resp.StatusCode; {
	case code == http.StatusOK:
		title, err := io.ReadAll(io.LimitReader(resp.Body, 4<<10))
		return string(title), 0, err
	case code == http.StatusNotFound:
		return "", 0, ErrUnknownClause // an answer, which example 3 caches
	case code == http.StatusTooManyRequests || code >= 500:
		secs, _ := strconv.Atoi(resp.Header.Get("Retry-After"))
		return "", time.Duration(secs) * time.Second, fmt.Errorf("%w: status %d", errTransient, code)
	default:
		return "", 0, fmt.Errorf("status %d", code) // TraceLite's mistake: no retry fixes it
	}
}

func main() {
	answers := []string{"200", "slow", "503", "429", "404", "400"}
	var calls atomic.Int64
	catalogue := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		answer := answers[calls.Add(1)-1]
		if answer == "slow" {
			<-r.Context().Done() // answers only after the client has given up
			return
		}
		if answer == "429" {
			w.Header().Set("Retry-After", "120")
		}
		code, _ := strconv.Atoi(answer)
		w.WriteHeader(code)
		fmt.Fprint(w, "Authentication information")
	}))
	defer catalogue.Close()
	client := &http.Client{Timeout: 10 * time.Second}                       // a backstop; http.DefaultClient has none
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second) // the API request's budget
	defer cancel()
	for _, answer := range answers {
		title, retryAfter, err := try(ctx, client, catalogue.URL+"/clauses/ISO27001:A.5.17")
		switch {
		case err == nil:
			fmt.Printf("%-4s -> %q\n", answer, title)
		case errors.Is(err, errTransient):
			fmt.Printf("%-4s -> retry, Retry-After %v\n", answer, retryAfter)
		default:
			fmt.Printf("%-4s -> final: %v\n", answer, err)
		}
	}
}

package main

import (
	"context"
	"errors"
	"fmt"
	"math/rand/v2"
	"time"
)

var errTransient = errors.New("may go away") // example 1's: a network error, a timeout, 429 or 5xx

// fetchTitle repeats example 1's try until it succeeds, fails for good, or the budget runs out.
func fetchTitle(ctx context.Context, try func() (string, time.Duration, error)) (string, error) {
	for attempt := 1; ; attempt++ {
		title, retryAfter, err := try()
		if !errors.Is(err, errTransient) {
			return title, err // done, a 404, or a mistake that retrying won't fix
		}
		if attempt == 3 {
			return "", fmt.Errorf("gave up after %d attempts: %w", attempt, err)
		}
		wait := max(retryAfter, rand.N(100*time.Millisecond<<attempt)) // full jitter, or the server's wish
		if deadline, ok := ctx.Deadline(); ok && time.Until(deadline) < wait {
			return "", fmt.Errorf("asked to wait %v, past our deadline: %w", wait, err)
		}
		select {
		case <-time.After(wait):
		case <-ctx.Done():
			return "", ctx.Err()
		}
	}
}

// catalogue plays example 1's try: each call returns the next scripted answer.
func catalogue(answers ...string) func() (string, time.Duration, error) {
	return func() (string, time.Duration, error) {
		answer := answers[0]
		answers = answers[1:]
		fmt.Println("  attempt:", answer)
		switch answer {
		case "200":
			return "Authentication information", 0, nil
		case "429":
			return "", 120 * time.Second, fmt.Errorf("%w: 429", errTransient)
		default: // 5xx, or no answer within the attempt's timeout
			return "", 0, fmt.Errorf("%w: %s", errTransient, answer)
		}
	}
}

func main() {
	for _, answers := range [][]string{{"503", "timeout", "200"}, {"429"}, {"502", "502", "502"}} {
		ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second) // the API request's budget
		title, err := fetchTitle(ctx, catalogue(answers...))
		cancel()
		fmt.Printf("lookup: %q, err: %v\n", title, err)
	}
}

package main

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"
)

var ErrUnknownClause = errors.New("no such clause") // example 1's answer to a 404

// Clause is the answer of GET /api/standards/{ref}.
type Clause struct {
	Ref   string `json:"ref"`
	Title string `json:"title"`
	Stale bool   `json:"stale"` // from the cache, because the catalogue didn't answer
}

type entry struct {
	clause  Clause
	err     error // ErrUnknownClause: a remembered 404
	expires time.Time
}

type Standards struct {
	fetch func(ctx context.Context, ref string) (string, error) // example 2's fetchTitle
	now   func() time.Time
	mu    sync.Mutex // requests look up concurrently
	cache map[string]entry
}

func (s *Standards) Lookup(ctx context.Context, ref string) (Clause, error) {
	s.mu.Lock()
	e, cached := s.cache[ref]
	s.mu.Unlock()
	if cached && s.now().Before(e.expires) {
		return e.clause, e.err
	}
	title, err := s.fetch(ctx, ref) // not under the lock: it may take the whole budget
	switch {
	case err == nil:
		e = entry{clause: Clause{Ref: ref, Title: title}, expires: s.now().Add(24 * time.Hour)}
	case errors.Is(err, ErrUnknownClause):
		e = entry{err: err, expires: s.now().Add(10 * time.Minute)}
	case cached && e.err == nil:
		e.clause.Stale = true // an old title beats an error page
		return e.clause, nil
	default:
		return Clause{}, err
	}
	s.mu.Lock()
	s.cache[ref] = e
	s.mu.Unlock()
	return e.clause, e.err
}

func main() {
	clock := time.Date(2026, 11, 13, 9, 0, 0, 0, time.UTC)
	s := &Standards{now: func() time.Time { return clock }, cache: map[string]entry{}}
	s.fetch = func(ctx context.Context, ref string) (string, error) {
		fmt.Println("  catalogue asked for", ref)
		if ref == "ISO27001:Z.9" {
			return "", ErrUnknownClause
		}
		return "Authentication information", nil
	}
	lookup := func(ref string) {
		c, err := s.Lookup(context.Background(), ref)
		fmt.Printf("%s %s: %q, stale: %v, err: %v\n", clock.Format("Jan 2 15:04"), ref, c.Title, c.Stale, err)
	}
	for _, ref := range []string{"ISO27001:A.5.17", "ISO27001:A.5.17", "ISO27001:Z.9", "ISO27001:Z.9"} {
		lookup(ref) // each second lookup is answered from the cache, the 404 too
	}
	clock = clock.Add(11 * time.Minute)
	lookup("ISO27001:Z.9") // a 404 is kept for 10 minutes only
	clock = clock.Add(25 * time.Hour)
	s.fetch = func(context.Context, string) (string, error) { return "", errors.New("gave up: 503") } // down
	lookup("ISO27001:A.5.17")
}

package main

import (
	"bytes"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/json/v2"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"sync"
	"time"
	"uuid"
)

// Event is the body of every delivery. Its id is the receivers' idempotency key.
type Event struct {
	ID        uuid.UUID `json:"id"`
	Type      string    `json:"type"`
	CreatedAt time.Time `json:"createdAt"`
	Data      any       `json:"data"`
}

// mac is the scheme of go.services.webhooks-hmac: HMAC-SHA256 over "<unix time>.<body>".
func mac(secret string, unix int64, body []byte) []byte {
	m := hmac.New(sha256.New, []byte(secret))
	fmt.Fprintf(m, "%d.%s", unix, body)
	return m.Sum(nil)
}

// receiver is a subscriber's endpoint: the other half of the contract.
type receiver struct {
	secret string
	now    func() time.Time
	seen   sync.Map // event ids; in production, a table with the id as primary key
}

func (rc *receiver) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, 64<<10))
	var unix int64
	var got []byte
	fmt.Sscanf(r.Header.Get("TraceLite-Signature"), "t=%d,v1=%x", &unix, &got) // a bad header leaves got empty
	age := rc.now().Sub(time.Unix(unix, 0)).Abs()
	if err != nil || !hmac.Equal(got, mac(rc.secret, unix, body)) || age > 5*time.Minute {
		http.Error(w, "bad or old signature", http.StatusUnauthorized)
		return
	}
	var e Event
	if err := json.Unmarshal(body, &e); err != nil {
		http.Error(w, "not an event", http.StatusBadRequest)
		return
	}
	if _, again := rc.seen.LoadOrStore(e.ID, true); again { // SQL: INSERT ... ON CONFLICT DO NOTHING
		fmt.Fprintln(w, "seen before, nothing done") // still 2xx, or TraceLite would keep retrying
		return
	}
	fmt.Fprintln(w, "processed", e.Type)
}

func main() {
	clock := time.Date(2026, 11, 13, 6, 2, 30, 0, time.UTC)
	ci := &receiver{secret: "ci-secret-26-characters-xx", now: func() time.Time { return clock }}
	body, _ := json.Marshal(Event{uuid.MustParse("01937b6e-0000-7000-8000-0000000000e1"), "test-run.failed", clock,
		map[string]any{"testCase": "TC-3", "requirements": []string{"AUTH-RESET"}}}) // once: every attempt sends these bytes
	deliver := func(label, secret string, signedAt time.Time) {
		req := httptest.NewRequest("POST", "/hooks/ci", bytes.NewReader(body))
		req.Header.Set("TraceLite-Signature", fmt.Sprintf("t=%d,v1=%x", signedAt.Unix(), mac(secret, signedAt.Unix(), body)))
		w := httptest.NewRecorder()
		ci.ServeHTTP(w, req)
		fmt.Printf("%-38s %d %s", label, w.Code, w.Body)
	}
	deliver("attempt 1 (its answer never arrives)", ci.secret, clock)
	clock = clock.Add(time.Minute)
	deliver("attempt 2: the same bytes, signed now", ci.secret, clock)
	deliver("signed with a guessed secret", "guessed", clock)
	deliver("a request signed 10 minutes ago", ci.secret, clock.Add(-10*time.Minute))
}

