type service struct{ db *pgxpool.Pool } // step 4's service, reduced to its pool

// handleCreate is step 4's handler, reduced to a rule only the database knows.
func (s service) handleCreate(w http.ResponseWriter, r *http.Request) {
	var in struct {
		Code     string  `json:"code"`
		ParentID *string `json:"parentId"`
	}
	if err := json.UnmarshalRead(r.Body, &in, json.RejectUnknownMembers(true)); err != nil {
		w.WriteHeader(http.StatusBadRequest)
		return
	}
	_, err := s.db.Exec(r.Context(), "INSERT INTO requirements (project_id, code, parent_id) VALUES ($1, $2, $3)",
		r.PathValue("projectId"), in.Code, in.ParentID)
	if pgErr, ok := errors.AsType[*pgconn.PgError](err); ok && pgErr.ConstraintName == "requirements_parent_fkey" {
		w.WriteHeader(http.StatusUnprocessableEntity) // step 4 writes a problem naming #/parentId
	} else if err != nil {
		w.WriteHeader(http.StatusInternalServerError)
	} else {
		w.WriteHeader(http.StatusCreated)
	}
}

var db *pgxpool.Pool
var api = http.NewServeMux() // the router

// TestMain runs once per test binary: one pool, the migrations (goose.Up in TraceLite), the routes.
func TestMain(m *testing.M) {
	var err error
	if db, err = pgxpool.New(context.Background(), os.Getenv("DATABASE_URL")); err == nil {
		_, err = db.Exec(context.Background(), `CREATE TABLE requirements ( -- migration 001, abridged
			id uuid PRIMARY KEY DEFAULT uuidv7(), project_id uuid NOT NULL, parent_id uuid, code text NOT NULL, UNIQUE (project_id, id),
			CONSTRAINT requirements_parent_fkey FOREIGN KEY (project_id, parent_id) REFERENCES requirements (project_id, id))`)
	}
	if err != nil {
		panic(err)
	}
	api.HandleFunc("POST /api/projects/{projectId}/requirements", service{db}.handleCreate)
	os.Exit(m.Run())
}

// newProject commits a requirement, AUTH, in a project of the test's own.
func newProject(t *testing.T) (project, auth string) {
	row := db.QueryRow(t.Context(), "INSERT INTO requirements (project_id, code) VALUES (uuidv7(), 'AUTH') RETURNING project_id, id")
	if err := row.Scan(&project, &auth); err != nil {
		t.Fatal(err)
	}
	return project, auth
}

func create(project, parent string) (status int) {
	rec, body := httptest.NewRecorder(), strings.NewReader(`{"code": "AUTH-RESET", "parentId": "`+parent+`"}`)
	api.ServeHTTP(rec, httptest.NewRequest("POST", "/api/projects/"+project+"/requirements", body))
	return rec.Code
}

func TestCreateUnderParent(t *testing.T) {
	t.Parallel() // safe: every row this test reads or writes is in its own projects
	project, auth := newProject(t)
	_, elsewhere := newProject(t)
	if same, other := create(project, auth), create(project, elsewhere); same != 201 || other != 422 {
		t.Errorf("parent in the same project: %d, in another: %d; want 201 and 422", same, other)
	}
}

// LEARN(fullstack.tracelite.step-14-testing): each layer gets the test that can see its bugs; the client's is real fetch against MSW answers.
import { http, HttpResponse } from "msw";
import { setupServer } from "msw/node";
import { afterAll, afterEach, beforeAll, expect, it } from "vitest";
import { z } from "zod";

// --- src/api, abridged from step 5: every answer is checked at the boundary.
const Requirement = z.object({
  code: z.string(),
  parentId: z.uuid().nullable(),
});
const FieldError = z.object({ pointer: z.string(), detail: z.string() });
const Problem = z.object({
  type: z.string(),
  title: z.string(),
  status: z.number(),
  errors: z.array(FieldError).optional(),
});

class ApiError extends Error {
  constructor(readonly problem: z.infer<typeof Problem>) {
    super(`${problem.status} ${problem.title}`);
  }
}

async function request<T>(
  schema: z.ZodType<T>,
  path: string,
  init: RequestInit,
) {
  // A browser resolves "/api/..." against the page; Node's fetch needs it done.
  const res = await fetch(new URL(path, location.href), init);
  const body: unknown = await res.json().catch(() => null);
  if (!res.ok) {
    const { status, statusText: title } = res;
    const made = { type: "about:blank", title, status };
    throw new ApiError(Problem.safeParse(body).data ?? made);
  }
  return schema.parse(body);
}

const save = () =>
  request(Requirement, "/api/projects/P1/requirements", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ code: "AUTH", parentId: null }),
  });

// --- The tests: MSW answers as the Go server, or a proxy before it, would.
const server = setupServer();
beforeAll(() => server.listen({ onUnhandledFrame: "error" }));
afterEach(() => server.resetHandlers());
afterAll(() => server.close());
const answer = (res: Response) =>
  server.use(http.post("*/api/projects/:projectId/requirements", () => res));

it("passes the server's 409 problem on, field pointer included", async () => {
  const conflict = {
    type: "https://tracelite.example/problems/conflict",
    title: "Conflict",
    status: 409,
    errors: [{ pointer: "#/code", detail: "bu kod projede zaten var" }],
  };
  answer(HttpResponse.json(conflict, { status: 409 }));
  await expect(save()).rejects.toMatchObject({ problem: conflict });
});

it("makes a problem out of the proxy's 502 page", async () => {
  const page = "<html><body>Bad Gateway</body></html>";
  answer(new HttpResponse(page, { status: 502, statusText: "Bad Gateway" }));
  const problem = { type: "about:blank", title: "Bad Gateway", status: 502 };
  await expect(save()).rejects.toMatchObject({ problem });
});

it("refuses a 201 whose body broke the contract", async () => {
  // A Go tag typo, json:"parentID": the member the spec names is missing.
  answer(HttpResponse.json({ code: "AUTH", parentID: null }, { status: 201 }));
  await expect(save()).rejects.toThrow(z.ZodError);
});

import { expect, test } from "@playwright/test";
import { readFile } from "node:fs/promises";
import { createServer, type Server } from "node:http";
import type { AddressInfo } from "node:net";

const P = "01937b6e-0000-7000-8000-00000000000a";
const exportPath = `/api/projects/${P}/requirement-export`;

