{{range .Items -}}
- {{printf "%-6s" .Name}} x{{.Qty}} {{printf "%7.2f" .Total}} TL
{{else -}}
- (no items)
{{end -}}
{{with .Note}}Note: {{.}}
{{end -}}
`

func main() {
