package main

import (
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"sync/atomic"
)

// cors labels responses for allowed origins and answers preflights. It never
// blocks anything: the browser enforces CORS, by hiding responses from pages.
func cors(allowed map[string]bool, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		origin := r.Header.Get("Origin")
		w.Header().Add("Vary", "Origin") // the answer depends on Origin: tell caches
		if allowed[origin] {
			w.Header().Set("Access-Control-Allow-Origin", origin)
		}
		if r.Method == http.MethodOptions && r.Header.Get("Access-Control-Request-Method") != "" {
			if allowed[origin] { // a preflight: may this origin send that request?
				w.Header().Set("Access-Control-Allow-Methods", "GET, PUT")
				w.Header().Set("Access-Control-Allow-Headers", "Content-Type")
				w.Header().Set("Access-Control-Max-Age", "600")
			}
			w.WriteHeader(http.StatusNoContent)
			return
		}
		next.ServeHTTP(w, r)
	})
}

func main() {
	var ran atomic.Int64 // how often the real handler executed
	mux := http.NewServeMux()
	mux.HandleFunc("PUT /notes/{id}", func(w http.ResponseWriter, r *http.Request) {
		ran.Add(1)
		io.WriteString(w, "saved")
	})
	allowed := map[string]bool{"http://127.0.0.1:5173": true}
	srv := httptest.NewServer(cors(allowed, mux))
	defer srv.Close()

	for _, c := range []struct{ method, origin, note string }{
		{"OPTIONS", "http://127.0.0.1:5173", "preflight from the app"},
		{"PUT", "http://127.0.0.1:5173", "the real request"},
		{"OPTIONS", "https://evil.example", "preflight from another site"},
		{"PUT", "https://evil.example", "sent anyway, e.g. by curl"},
		{"PUT", "null", "from a sandboxed iframe"},
	} {
		req, _ := http.NewRequest(c.method, srv.URL+"/notes/1", nil)
		req.Header.Set("Origin", c.origin)
		if c.method == "OPTIONS" {
			req.Header.Set("Access-Control-Request-Method", "PUT")
			req.Header.Set("Access-Control-Request-Headers", "content-type")
		}
		resp, err := http.DefaultClient.Do(req)
		if err != nil {
			fmt.Println("error:", err)
			continue
		}
		resp.Body.Close()
		h := resp.Header
		fmt.Printf("%-7s %-21s %d allow-origin=%q methods=%q  (%s)\n", c.method, c.origin,
			resp.StatusCode, h.Get("Access-Control-Allow-Origin"), h.Get("Access-Control-Allow-Methods"), c.note)
	}
	fmt.Println("the PUT handler ran", ran.Load(), "times")
}

package main

import (
	"encoding/base64"
	"fmt"
	"io"
	"net/http"
	"net/http/cookiejar"
	"net/http/httptest"
	"strings"
)

func session(value string, maxAge int) *http.Cookie {
	return &http.Cookie{
		Name:     "__Host-session", // browsers require Secure, Path=/ and no Domain
		Value:    value,            // an opaque ID; the session data stays on the server
		Path:     "/",
		MaxAge:   maxAge,
		HttpOnly: true,                 // invisible to JavaScript, so XSS can't steal it
		Secure:   true,                 // only sent over HTTPS
		SameSite: http.SameSiteLaxMode, // not sent on cross-site POSTs or subrequests
	}
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("POST /login", func(w http.ResponseWriter, r *http.Request) {
		http.SetCookie(w, session("s3cr3t-id", 3600))
		http.SetCookie(w, &http.Cookie{Name: "raw", Value: "Ayşe"}) // see stderr
		http.SetCookie(w, &http.Cookie{Name: "name", Value: base64.RawURLEncoding.EncodeToString([]byte("Ayşe"))})
	})
	mux.HandleFunc("GET /me", func(w http.ResponseWriter, r *http.Request) {
		if _, err := r.Cookie("__Host-session"); err != nil {
			http.Error(w, "not logged in", http.StatusUnauthorized)
			return
		}
		raw, _ := r.Cookie("raw")
		c, _ := r.Cookie("name")
		name, _ := base64.RawURLEncoding.DecodeString(c.Value)
		fmt.Fprintf(w, "logged in: raw=%q decoded=%q\n", raw.Value, name)
	})
	mux.HandleFunc("POST /logout", func(w http.ResponseWriter, r *http.Request) {
		http.SetCookie(w, session("", -1)) // MaxAge < 0 sends Max-Age=0: delete now
	})
	// Rejects unsafe cross-origin browser requests (CSRF), Go 1.25.
	srv := httptest.NewTLSServer(http.NewCrossOriginProtection().Handler(mux))
	defer srv.Close()

	client := srv.Client() // trusts the test server's certificate
	client.Jar, _ = cookiejar.New(nil)
	do := func(method, path, fetchSite string) {
		req, _ := http.NewRequest(method, srv.URL+path, nil)
		if fetchSite != "" {
			req.Header.Set("Sec-Fetch-Site", fetchSite) // what a browser would send
		}
		resp, err := client.Do(req)
		if err != nil {
			fmt.Println("error:", err)
			return
		}
		defer resp.Body.Close()
		body, _ := io.ReadAll(resp.Body)
		fmt.Println(strings.TrimSpace(fmt.Sprintf("%s %s %d %s", method, path, resp.StatusCode, body)))
		for _, sc := range resp.Header.Values("Set-Cookie") {
			fmt.Println("    Set-Cookie:", sc)
		}
	}
	do("POST", "/login", "same-origin")
	do("GET", "/me", "")
	do("POST", "/logout", "cross-site") // a form on another site, posting here
	do("GET", "/me", "")
	do("POST", "/logout", "same-origin")
	do("GET", "/me", "")
}

package main

import (
	"io"
	"net/http"
	"net/http/httptest"
	"testing"
)

// The code under test: one JSON route.
func newRouter() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /notes/{id}", func(w http.ResponseWriter, r *http.Request) {
		if r.PathValue("id") != "1" {
			http.Error(w, "no such note", http.StatusNotFound)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		io.WriteString(w, `{"id":1,"text":"Merhaba"}`)
	})
	return mux
}

// No server, no client, no network: ServeHTTP is called directly.
func TestRoutes(t *testing.T) {
	for _, tc := range []struct {
		name, method, target string
		wantStatus           int
		wantType             string
	}{
		{"found", "GET", "/notes/1", http.StatusOK, "application/json"},
		{"missing", "GET", "/notes/2", http.StatusNotFound, "text/plain; charset=utf-8"},
		{"wrong method", "DELETE", "/notes/1", http.StatusMethodNotAllowed, "text/plain; charset=utf-8"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			rec := httptest.NewRecorder()
			newRouter().ServeHTTP(rec, httptest.NewRequest(tc.method, tc.target, nil))
			res := rec.Result() // the response as sent, not the live header map
			if res.StatusCode != tc.wantStatus || res.Header.Get("Content-Type") != tc.wantType {
				t.Errorf("%s %s = %d %q, want %d %q", tc.method, tc.target,
					res.StatusCode, res.Header.Get("Content-Type"), tc.wantStatus, tc.wantType)
			}
		})
	}
}

// A real client and server, still without a network: NewTestServer
// (Go 1.27) uses an in-memory network and shuts down when the test ends.
func TestEndToEnd(t *testing.T) {
	srv := httptest.NewTestServer(t, newRouter())
	resp, err := srv.Client().Get("http://notes.example/notes/1")
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	body, _ := io.ReadAll(resp.Body)
	if resp.StatusCode != http.StatusOK {
		t.Errorf("status = %d, want 200", resp.StatusCode)
	}
	t.Logf("GET http://notes.example/notes/1 -> %d %s", resp.StatusCode, body)
}

