package main

import (
	"fmt"
	"strconv"
	"strings"
	"testing"
)

var ids = []string{
	"go.basics.defer", "go.basics.pointers", "go.composite.structs", "go.http.handlers",
	"go.postgres.pgx", "sql.joins.lateral", "sql.search.turkish", "ts.react.query",
}

var (
	sink  string
	sinks []string
)

func concat() string {
	s := ""
	for _, id := range ids {
		s += id + "\n" // a new string every iteration
	}
	return s
}

func build(grow bool) string {
	var b strings.Builder
	if grow {
		b.Grow(len(ids) * 24) // one allocation, if the estimate is big enough
	}
	for _, id := range ids {
		b.WriteString(id)
		b.WriteByte('\n')
	}
	return b.String()
}

func collect(prealloc bool) []string {
	var out []string
	if prealloc {
		out = make([]string, 0, len(ids))
	}
	for _, id := range ids {
		out = append(out, id)
	}
	return out
}

func main() {
	measure := func(name string, f func()) {
		fmt.Printf("%-26s %v\n", name, testing.AllocsPerRun(1000, f))
	}
	measure("s += id", func() { sink = concat() })
	measure("strings.Builder", func() { sink = build(false) })
	measure("Builder after Grow", func() { sink = build(true) })
	measure("strings.Join", func() { sink = strings.Join(ids, "\n") })

	measure("append, no capacity", func() { sinks = collect(false) })
	measure("append into make(0, n)", func() { sinks = collect(true) })

	measure("fmt.Sprintf", func() { sink = fmt.Sprintf("%s:%d", ids[0], 1234) })
	buf := make([]byte, 0, 64)
	measure("strconv.AppendInt, reused", func() {
		buf = strconv.AppendInt(append(append(buf[:0], ids[0]...), ':'), 1234, 10)
	})

	runs := map[string]int{"go.basics.defer": 3}
	key := []byte("go.basics.defer")
	measure("m[string(key)]", func() { _ = runs[string(key)] })
}

package main

import (
	"bytes"
	"fmt"
	"strconv"
	"sync"
	"testing"
)

var (
	sink string
	ids  = []string{
		"go.basics.defer", "go.basics.pointers", "go.composite.structs", "go.http.handlers",
		"go.postgres.pgx", "sql.joins.lateral", "sql.search.turkish", "ts.react.query",
	}
)

// render writes one line per lesson into b and returns the text.
func render(b *bytes.Buffer, runs map[string]int) string {
	for _, id := range ids {
		b.WriteString(id)
		b.WriteByte(' ')
		b.Write(strconv.AppendInt(b.AvailableBuffer(), int64(runs[id]), 10))
		b.WriteByte('\n')
	}
	return b.String()
}

var bufPool = sync.Pool{New: func() any { return new(bytes.Buffer) }}

func renderPooled(runs map[string]int) string {
	b := bufPool.Get().(*bytes.Buffer)
	b.Reset() // pooled objects come back dirty
	defer func() {
		if b.Cap() <= 64<<10 { // keep huge buffers out of the pool, as fmt does
			bufPool.Put(b)
		}
	}()
	return render(b, runs)
}

// A pool of slices: Put([]byte) boxes the slice header into an interface.
var slicePool = sync.Pool{New: func() any { return make([]byte, 0, 512) }}
var ptrPool = sync.Pool{New: func() any { b := make([]byte, 0, 512); return &b }}

func main() {
	runs := map[string]int{"go.basics.defer": 1200, "sql.joins.lateral": 95, "ts.react.query": 7}
	measure := func(name string, f func()) {
		fmt.Printf("%-24s %v\n", name, testing.AllocsPerRun(1000, f))
	}
	measure("new buffer per call", func() { sink = render(new(bytes.Buffer), runs) })
	measure("buffer from a Pool", func() { sink = renderPooled(runs) })

	measure("Pool of []byte", func() {
		buf := slicePool.Get().([]byte)
		sink = string(append(buf[:0], "go.basics.defer"...))
		slicePool.Put(buf[:0]) // allocates: a slice is not pointer-shaped
	})
	measure("Pool of *[]byte", func() {
		bp := ptrPool.Get().(*[]byte)
		*bp = append((*bp)[:0], "go.basics.defer"...)
		sink = string(*bp)
		ptrPool.Put(bp)
	})
	fmt.Println(renderPooled(runs) == render(new(bytes.Buffer), runs))
}

package main

import (
	"fmt"
	"math"
	"runtime"
	"runtime/debug"
)

var sink []byte

// churn allocates 64 MiB in 4 KiB pieces and keeps only the last one.
func churn() {
	for range 16 << 10 {
		sink = make([]byte, 4<<10)
	}
}

// reuse does the same number of writes into one buffer.
func reuse() {
	buf := sink
	for range 16 << 10 {
		clear(buf)
	}
}

// cycles counts the GC cycles that ran while f did.
func cycles(f func()) uint32 {
	var before, after runtime.MemStats
	runtime.GC() // start from a collected heap
	runtime.ReadMemStats(&before)
	f()
	runtime.ReadMemStats(&after)
	return after.NumGC - before.NumGC
}

func main() {
	fmt.Println("GOGC=100, allocating:   cycles > 0:", cycles(churn) > 0)
	fmt.Println("GOGC=100, reusing:      cycles =", cycles(reuse))

	old := debug.SetGCPercent(-1) // GOGC=off: no proportional trigger at all
	fmt.Println("GOGC=off, allocating:   cycles =", cycles(churn))

	debug.SetMemoryLimit(16 << 20) // GOMEMLIMIT=16MiB still triggers collections
	fmt.Println("GOGC=off, 16 MiB limit: cycles > 0:", cycles(churn) > 0)

	debug.SetMemoryLimit(math.MaxInt64)
	debug.SetGCPercent(old)
	fmt.Println("default GOGC was", old)
}

