package main

import (
	"strings"
	"testing"
)

// joinPlus builds the line with +=: every step copies everything so far.
func joinPlus(fields []string) string {
	s := ""
	for i, f := range fields {
		if i > 0 {
			s += ";"
		}
		s += f
	}
	return s
}

// joinBuilder sizes one buffer up front and writes into it.
func joinBuilder(fields []string) string {
	n := len(fields)
	for _, f := range fields {
		n += len(f)
	}
	var b strings.Builder
	b.Grow(n)
	for i, f := range fields {
		if i > 0 {
			b.WriteByte(';')
		}
		b.WriteString(f)
	}
	return b.String()
}

var cities = strings.Fields("İstanbul Ankara İzmir Bursa Antalya Konya Adana Şanlıurfa")

// Benchmarks run only with go test -bench; plain go test skips them.
func BenchmarkJoinPlus(b *testing.B) {
	for b.Loop() { // Go 1.24; timer, iteration count and dead-code guard in one
		joinPlus(cities)
	}
}

func BenchmarkJoinBuilder(b *testing.B) {
	for b.Loop() {
		joinBuilder(cities)
	}
}

// Allocation counts are exact, so a plain test can pin them.
func TestJoinAllocs(t *testing.T) {
	plus := testing.AllocsPerRun(100, func() { joinPlus(cities) })
	builder := testing.AllocsPerRun(100, func() { joinBuilder(cities) })
	t.Logf("allocations per call: += %v, Builder %v", plus, builder)
	if builder != 1 {
		t.Errorf("joinBuilder allocates %v times per call, want 1", builder)
	}
}

// testing.Benchmark runs a benchmark function without -bench (for about a
// second). Timings vary from run to run; the allocation count doesn't.
func TestBenchmarkByHand(t *testing.T) {
	r := testing.Benchmark(BenchmarkJoinBuilder)
	t.Logf("iterations > 0: %v, allocs/op: %d", r.N > 0, r.AllocsPerOp())
}

package main

import (
	"strings"
	"testing"
	"unicode/utf8"
)

// Truncate shortens s to at most n bytes without splitting a character,
// e.g. to fit a column whose limit is in bytes.
func Truncate(s string, n int) string {
	if n <= 0 {
		return "" // the fuzzer found Truncate("0", -42) panicking
	}
	if len(s) <= n {
		return s
	}
	for n > 0 && !utf8.RuneStart(s[n]) {
		n-- // back up to the first byte of the character that doesn't fit
	}
	return s[:n]
}

func FuzzTruncate(f *testing.F) {
	f.Add("Iğdır", 2) // seeds: run by plain go test, mutated by go test -fuzz
	f.Add("şçöğü", 5)
	f.Add("", 0)
	f.Fuzz(func(t *testing.T, s string, n int) {
		got := Truncate(s, n)
		// Properties, not examples: true for every input.
		if len(got) > max(n, 0) || !strings.HasPrefix(s, got) {
			t.Fatalf("Truncate(%q, %d) = %q: too long or not a prefix", s, n, got)
		}
		if utf8.ValidString(s) && !utf8.ValidString(got) {
			t.Fatalf("Truncate(%q, %d) = %q: split a character", s, n, got)
		}
		t.Logf("Truncate(%q, %d) = %q", s, n, got)
	})
}

package main

import (
	"fmt"
	"strings"
	"unicode"
)

var ascii = strings.NewReplacer(
	"ı", "i", "ğ", "g", "ü", "u", "ş", "s", "ö", "o", "ç", "c",
	"â", "a", "î", "i", "û", "u", // kâr, Kâğıthane, millî
)

// Slug turns a Turkish title into a URL path segment.
func Slug(title string) string {
	var b strings.Builder
	dash := false
	for _, r := range ascii.Replace(strings.ToLower(title)) {
		switch {
		case 'a' <= r && r <= 'z', '0' <= r && r <= '9':
			b.WriteRune(r)
			dash = false
		case r == '\'' || r == '’' || unicode.Is(unicode.Mn, r):
			// apostrophes and combining marks vanish: İzmir'de -> izmirde
		case !dash && b.Len() > 0:
			b.WriteByte('-')
			dash = true
		}
	}
	return strings.TrimSuffix(b.String(), "-")
}

func ExampleSlug() {
	fmt.Println(Slug("Şanlıurfa'da Kış Turizmi"))
	fmt.Println(Slug("  IĞDIR — Kâğıthane  "))
	fmt.Println(Slug("i\u0307stanbul")) // lowercased by JavaScript's toLowerCase
	// Output:
	// sanliurfada-kis-turizmi
	// igdir-kagithane
	// istanbul
}

func ExampleSlug_plates() {
	plates := map[string]int{"İzmir": 35, "Muğla": 48, "Çanakkale": 17}
	for city, plate := range plates { // map order varies from run to run
		fmt.Println(plate, Slug(city))
	}
	// Unordered output:
	// 35 izmir
	// 48 mugla
	// 17 canakkale
}

// An example without an output comment is compiled, shown in the docs,
// and never run.
func ExampleSlug_untested() {
	fmt.Println(Slug("Ölüdeniz"))
}

