// LEARN(inside.codebase.testing-pyramid): the base of the pyramid: pure functions, a table of cases, no I/O, milliseconds per run.
package main

import (
	"slices"
	"strings"
	"testing"
)

// splitStatements is a miniature of sqlrun's splitter: split on ';' outside
// single-quoted strings and -- comments. The real one also knows dollar
// quotes, escape strings (E'...'), block comments and quoted identifiers.
func splitStatements(script string) []string {
	var out []string
	var cur strings.Builder
	inString, inComment := false, false
	for _, r := range script { // runes, not bytes: ş and İ are two bytes each
		switch {
		case inComment:
			inComment = r != '\n'
		case r == '\'':
			inString = !inString // '' inside a string toggles twice: still inside
		case !inString && r == '-' && strings.HasSuffix(cur.String(), "-"):
			inComment = true
		case !inString && r == ';':
			if s := strings.TrimSpace(cur.String()); s != "" {
				out = append(out, s)
			}
			cur.Reset()
			continue
		}
		cur.WriteRune(r)
	}
	if s := strings.TrimSpace(cur.String()); s != "" {
		out = append(out, s)
	}
	return out
}

func TestSplitStatements(t *testing.T) {
	tests := []struct {
		name, script string
		want         []string
	}{
		{"two statements", "SELECT 1; SELECT 2;", []string{"SELECT 1", "SELECT 2"}},
		{"semicolon in a string", "SELECT 'a;b'; SELECT 2", []string{"SELECT 'a;b'", "SELECT 2"}},
		{"doubled quote", "SELECT 'it''s; fine';", []string{"SELECT 'it''s; fine'"}},
		{"semicolon in a comment", "SELECT 1 -- a; b\n;", []string{"SELECT 1 -- a; b"}},
		{"Turkish identifier", "SELECT 1 AS şehir; SELECT 'İ'", []string{"SELECT 1 AS şehir", "SELECT 'İ'"}},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if got := splitStatements(tc.script); !slices.Equal(got, tc.want) {
				t.Errorf("got  %q\nwant %q", got, tc.want)
			}
		})
	}
}

// LEARN(inside.codebase.testing-pyramid): the missing layer: a handler test with a fake Runner, the seam httpapi.Runner was declared for.
package main

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

type Request struct{ Runtime string }
type Result struct{ Stdout string }
type Refusal struct {
	Status int
	Detail string
}
type Runner interface {
	Run(ctx context.Context, req Request) (*Result, *Refusal, error)
}

func handleRun(runner Runner, record func(Request)) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		var req Request
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil || req.Runtime == "" {
			http.Error(w, "invalid request body", http.StatusBadRequest)
			return
		}
		res, refusal, err := runner.Run(r.Context(), req)
		switch {
		case err != nil:
			http.Error(w, "runner or playground database unavailable", http.StatusBadGateway)
		case refusal != nil:
			http.Error(w, refusal.Detail, refusal.Status)
		default:
			if r.Header.Get("X-Stacklab-No-History") == "" {
				record(req)
			}
			_ = json.NewEncoder(w).Encode(res)
		}
	}
}

type fakeRunner struct { // returns what it holds: no Go toolchain, no database
	res     *Result
	refusal *Refusal
	err     error
}

func (f fakeRunner) Run(context.Context, Request) (*Result, *Refusal, error) {
	return f.res, f.refusal, f.err
}

func TestHandleRun(t *testing.T) {
	tests := []struct {
		name, body, noHistory string
		runner                fakeRunner
		code, recorded        int
	}{
		{"ok, recorded", `{"Runtime":"go"}`, "", fakeRunner{res: &Result{}}, 200, 1},
		{"ok, verify run", `{"Runtime":"go"}`, "1", fakeRunner{res: &Result{}}, 200, 0},
		{"bad body", `{`, "", fakeRunner{}, 400, 0},
		{"both slots busy", `{"Runtime":"go"}`, "", fakeRunner{refusal: &Refusal{503, "server busy"}}, 503, 0},
		{"playground down", `{"Runtime":"sql"}`, "", fakeRunner{err: errors.New("dial tcp: refused")}, 502, 0},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			recorded := 0
			req := httptest.NewRequest("POST", "/api/run", strings.NewReader(tc.body))
			req.Header.Set("X-Stacklab-No-History", tc.noHistory)
			rec := httptest.NewRecorder()
			handleRun(tc.runner, func(Request) { recorded++ })(rec, req)
			if rec.Code != tc.code || recorded != tc.recorded {
				t.Errorf("got %d, %d recorded; want %d, %d (body %q)", rec.Code, recorded, tc.code, tc.recorded, rec.Body)
			}
		})
	}
}

// LEARN(inside.codebase.testing-pyramid): judge.ts is the cheapest next frontend test.
import { describe, expect, it } from "vitest";

// A miniature of src/features/runner/judge.ts: same rules, same order, regex left out.
type Check = "exact" | "contains" | "sorted-lines" | "none";
interface RunResult { stdout: string; exitCode: number }

function normalize(s: string, check: Check): string {
  const text = s.replace(/\r\n/g, "\n").trimEnd();
  return check === "sorted-lines" ? text.split("\n").sort().join("\n") : text;
}

function judge(r: RunResult, check: Check, expected: string | null): { pass: boolean } | null {
  if (check === "none" || expected === null) return null;
  if (r.exitCode !== 0) return { pass: false };
  const actual = normalize(r.stdout, check);
  const want = normalize(expected, check);
  if (check === "contains") return { pass: want.split("\n").every((l) => actual.includes(l.trim())) };
  return { pass: actual === want };
}

describe("judge", () => {
  it.each([
    ["exact ignores CRLF and whitespace at the very end", "a\r\nb  \r\n", "exact", "a\nb\n", true],
    ["exact still sees spaces ending an inner line", "a  \nb\n", "exact", "a\nb\n", false],
    ["exact sees a changed line", "a\nc\n", "exact", "a\nb\n", false],
    ["sorted-lines ignores order", "b\na\n", "sorted-lines", "a\nb\n", true],
    ["contains matches trimmed lines", "--- PASS: TestX (0.00s)\nok\n", "contains", "  --- PASS: TestX", true],
  ] as const)("%s", (_name, stdout, check, expected, pass) => {
    expect(judge({ stdout, exitCode: 0 }, check, expected)).toEqual({ pass });
  });

  it("fails any check when the program failed, whatever it printed", () => {
    expect(judge({ stdout: "a\n", exitCode: 1 }, "exact", "a\n")).toEqual({ pass: false });
  });

  it("has no verdict without an expected file or with check none", () => {
    expect(judge({ stdout: "x", exitCode: 0 }, "exact", null)).toBeNull();
    expect(judge({ stdout: "x", exitCode: 0 }, "none", "x")).toBeNull();
  });
});

