-- Checked at the end of each statement instead of row by row.
CREATE TABLE steps (
  id  int PRIMARY KEY,
  pos int NOT NULL,
  CONSTRAINT steps_pos_key UNIQUE (pos) DEFERRABLE INITIALLY IMMEDIATE
