package main

import (
	"context"
	"fmt"
	"log"
	"os"
	"strings"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
)

const file = "case_code;run_on;seconds\n" +
	"TC-1;2026-11-09;1.5\n" +
	"TC-2;09.11.2026;2\n" +
	"TC-3;13.11.2026;2\n" +
	"TC-4;2026-11-10;0,75\n" +
	"TC-5;2026-11-10;3\n"

func main() {
	ctx := context.Background()
	cfg, err := pgx.ParseConfig(os.Getenv("DATABASE_URL"))
	if err != nil {
		log.Fatal(err)
	}
	cfg.RuntimeParams["DateStyle"] = "ISO, MDY" // the built-in default; initdb may pick another
	cfg.OnNotice = func(_ *pgconn.PgConn, n *pgconn.Notice) { fmt.Println("  NOTICE:", n.Message) }
	conn, err := pgx.ConnectConfig(ctx, cfg)
	if err != nil {
		log.Fatal(err)
	}
	defer conn.Close(ctx)
	_, err = conn.Exec(ctx, `CREATE TABLE runs (case_code text NOT NULL, run_on date NOT NULL,
		seconds numeric(6,2) NOT NULL CHECK (seconds >= 0))`)
	if err != nil {
		log.Fatal(err)
	}
	load := func(data, opts string) {
		fmt.Println(opts)
		sql := "COPY runs FROM STDIN WITH (FORMAT csv, HEADER, DELIMITER ';', " + opts + ")"
		tag, err := conn.PgConn().CopyFrom(ctx, strings.NewReader(data), sql)
		if err != nil {
			fmt.Printf("  %v\n", err)
			return
		}
		fmt.Printf("  %v\n", tag)
	}
	load(file, "ON_ERROR ignore, LOG_VERBOSITY verbose")
	load(file, "ON_ERROR ignore, REJECT_LIMIT 1")
	load(file+"TC-6;2026-11-11;-1\n", "ON_ERROR ignore")
	load(file+"TC-7;2026-11-11\n", "ON_ERROR ignore")

	rows, _ := conn.Query(ctx, "SELECT format('%s %s %s', case_code, run_on, seconds) FROM runs ORDER BY case_code")
	loaded, err := pgx.CollectRows(rows, pgx.RowTo[string])
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println("loaded:", strings.Join(loaded, ", "))
}

files.sql/files-movement/03-dump-generate/exam:
-- random() keeps its state per session. setseed() fixes the starting
-- point, so the same statements after the same seed produce the same rows.
SELECT setseed(0.42);
CREATE TABLE draw1 AS
SELECT i, random(1, 6) AS die FROM generate_series(1, 100000) AS i;

SELECT setseed(0.42);
CREATE TABLE draw2 AS
SELECT i, random(1, 6) AS die FROM generate_series(1, 100000) AS i;

-- No new seed: the sequence continues where draw2 left it.
CREATE TABLE draw3 AS
SELECT i, random(1, 6) AS die FROM generate_series(1, 100000) AS i;

-- Compare tables rather than print values: the docs promise repeatability
-- within a session, not the same numbers on another version.
SELECT NOT EXISTS (TABLE draw1 EXCEPT TABLE draw2) AS same_seed_same_rows,
       NOT EXISTS (TABLE draw1 EXCEPT TABLE draw3) AS no_reseed_same_rows,
       (SELECT min(die) || '..' || max(die) FROM draw1) AS die_range;

-- Dates in, timestamptz out: generate_series has no date variant.
SELECT pg_typeof(d) AS returns, d::date AS day
FROM generate_series(date '2026-11-01', date '2026-11-03', interval '1 day') AS d;

package main

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"log"
	"os"

	"github.com/jackc/pgx/v5"
)

func main() {
	ctx := context.Background()
	// Two connections, as if to two databases: in real life dst gets another URL.
	src, err := pgx.Connect(ctx, os.Getenv("DATABASE_URL"))
	if err != nil {
		log.Fatal(err)
	}
	defer src.Close(ctx)
	dst, err := pgx.Connect(ctx, os.Getenv("DATABASE_URL"))
	if err != nil {
		log.Fatal(err)
	}
	defer dst.Close(ctx)

	_, err = src.Exec(ctx, `CREATE TABLE runs AS
		SELECT i AS id, 'TC-' || i AS case_code, (i % 7) * 1.25 AS seconds,
		       CASE WHEN i % 3 > 0 THEN 'ayşe' END AS tester
		FROM generate_series(1, 50000) AS i;
		CREATE TABLE runs_copy (LIKE runs)`)
	if err != nil {
		log.Fatal(err)
	}

	// The text format: tab-separated, \N for NULL. A plain pg_dump stores
	// each table's rows like this, between COPY ... FROM stdin; and \.
	var head bytes.Buffer
	_, err = src.PgConn().CopyTo(ctx, &head, "COPY (SELECT * FROM runs ORDER BY id LIMIT 3) TO STDOUT")
	fmt.Printf("%q %v\n", head.String(), err)

	// Stream one table into the other: no file, and io.Pipe holds no data.
	pr, pw := io.Pipe()
	done := make(chan error, 1)
	go func() {
		_, err := src.PgConn().CopyTo(ctx, pw, "COPY runs TO STDOUT")
		pw.CloseWithError(err) // nil: the reader sees EOF and the COPY completes
		done <- err
	}()
	tag, err := dst.PgConn().CopyFrom(ctx, pr, "COPY runs_copy FROM STDIN")
	pr.CloseWithError(err) // if CopyFrom stopped early, unblock the writer
	fmt.Println(tag, err, <-done)

	var same bool
	err = dst.QueryRow(ctx, `SELECT NOT EXISTS (TABLE runs EXCEPT ALL TABLE runs_copy)
		AND NOT EXISTS (TABLE runs_copy EXCEPT ALL TABLE runs)`).Scan(&same)
	fmt.Println("identical:", same, err)
}

files.sql/indexes/01-btree/examples/01_explain:
-- LEARN(sql.indexes.btree): EXPLAIN predicts, EXPLAIN ANALYZE runs and measures.
CREATE TABLE orders (
  id          bigint PRIMARY KEY,
  customer_id int NOT NULL,
  total       numeric(10,2) NOT NULL
);
INSERT INTO orders
SELECT g, g % 1000 + 1, g % 500 + 0.99 FROM generate_series(1, 20000) AS g;
ANALYZE orders;

-- No index on customer_id: the only plan is to read every row.
EXPLAIN (COSTS OFF)
SELECT id, total FROM orders WHERE customer_id = 42;

CREATE INDEX orders_customer_id ON orders (customer_id);

-- Same query, new plan. Still a prediction: nothing has run.
EXPLAIN (COSTS OFF)
SELECT id, total FROM orders WHERE customer_id = 42;

-- ANALYZE executes it: real row counts, and the pages it touched.
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT id, total FROM orders WHERE customer_id = 42;

-- Plain EXPLAIN of a DELETE only plans it...
EXPLAIN (COSTS OFF)
DELETE FROM orders WHERE customer_id = 42;
-- ...with ANALYZE it executes: this DELETE deletes.
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
DELETE FROM orders WHERE customer_id = 42;
SELECT count(*) AS orders_left FROM orders WHERE customer_id = 42;

files.sql/indexes/01-btree/examples/02_btree_d:
-- Three tables that differ only in size. Each primary key is a B-tree index.
CREATE TABLE small  (id int PRIMARY KEY, pad text);
CREATE TABLE medium (id int PRIMARY KEY, pad text);
CREATE TABLE large  (id int PRIMARY KEY, pad text);
INSERT INTO small  SELECT g, 'row ' || g FROM generate_series(1, 100) AS g;
INSERT INTO medium SELECT g, 'row ' || g FROM generate_series(1, 10000) AS g;
INSERT INTO large  SELECT g, 'row ' || g FROM generate_series(1, 200000) AS g;

-- Warm-up: plan each lookup once, so the measurements below count only
-- the pages the lookup itself visits, not the planner's catalog reads.
SELECT s.pad, m.pad, l.pad
FROM small s, medium m, large l
WHERE s.id = 42 AND m.id = 42 AND l.id = 42;

-- One page per tree level, plus one heap page for the row itself.
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT pad FROM small WHERE id = 42;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT pad FROM medium WHERE id = 42;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT pad FROM large WHERE id = 42;

-- A range descends once, then walks the linked leaf pages sideways.
EXPLAIN (COSTS OFF)
SELECT pad FROM large WHERE id BETWEEN 1000 AND 1999;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT pad FROM large WHERE id BETWEEN 1000 AND 1999;

files.sql/indexes/01-btree/examples/03_index_i:
-- amount is spread over the table in no particular order, like most columns.
CREATE TABLE payments (
  id     bigint PRIMARY KEY,
  amount int NOT NULL,
  note   text NOT NULL
);
INSERT INTO payments
SELECT g, (g * 7919) % 1000, 'payment ' || g FROM generate_series(1, 20000) AS g;
CREATE INDEX payments_amount ON payments (amount);
ANALYZE payments;

-- 1% of the rows: the index pays off.
EXPLAIN (COSTS OFF)
SELECT max(note) FROM payments WHERE amount < 10;

-- 90% of the rows: the index exists, and the planner ignores it.
EXPLAIN (COSTS OFF)
SELECT max(note) FROM payments WHERE amount < 900;

-- Measure the planner's choice...
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT max(note) FROM payments WHERE amount < 900;

-- ...against the index it rejected. SET LOCAL lasts until the transaction ends.
SET LOCAL enable_seqscan = off;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT max(note) FROM payments WHERE amount < 900;

SET LOCAL enable_bitmapscan = off;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT max(note) FROM payments WHERE amount < 900;

files.sql/indexes/02-plans/examples/01_scans.s:
-- LEARN(sql.indexes.plans): one table, the planner's whole scan menu.
CREATE TABLE readings (
  id        int PRIMARY KEY,
  sensor_id int NOT NULL,
  value     int NOT NULL
);
INSERT INTO readings
SELECT g, g % 200, (g * 7919) % 10000 FROM generate_series(1, 20000) AS g;
CREATE INDEX readings_value ON readings (value);
CREATE INDEX readings_sensor ON readings (sensor_id);
ANALYZE readings;

-- Most of the table: read all of it.
EXPLAIN (COSTS OFF) SELECT * FROM readings WHERE value > 1000;

-- One row: descend the index, then fetch the row from the table.
EXPLAIN (COSTS OFF) SELECT * FROM readings WHERE id = 4242;

-- Only indexed columns are needed: the table may not be visited at all.
EXPLAIN (COSTS OFF) SELECT id FROM readings WHERE id BETWEEN 10000 AND 10099;

-- 200 scattered rows: collect their locations, then visit pages in order.
EXPLAIN (COSTS OFF) SELECT * FROM readings WHERE value < 100;

-- Two conditions on two indexes, combined as bitmaps.
EXPLAIN (COSTS OFF) SELECT * FROM readings WHERE value < 20 OR sensor_id = 7;

-- The index already delivers rows in order: no sort, and LIMIT stops it early.
EXPLAIN (COSTS OFF) SELECT * FROM readings ORDER BY value LIMIT 5;

-- "May not": these rows are not yet known visible to everyone, so each one
-- is still checked in the table.
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT id FROM readings WHERE id BETWEEN 10000 AND 10099;

files.sql/indexes/02-plans/examples/02_joins.s:
CREATE TABLE customers (id int PRIMARY KEY, city text NOT NULL);
CREATE TABLE orders (
  id          int PRIMARY KEY,
  customer_id int NOT NULL REFERENCES customers,
  total       int NOT NULL
);
INSERT INTO customers
SELECT g, (ARRAY['İstanbul', 'Ankara', 'İzmir', 'Bursa'])[g % 4 + 1]
FROM generate_series(1, 2000) AS g;
-- 10 orders per customer.
INSERT INTO orders SELECT g, g % 2000 + 1, g % 300 FROM generate_series(1, 20000) AS g;
CREATE INDEX orders_customer ON orders (customer_id);
ANALYZE customers, orders;

-- Three customers: for each one, look up its orders in the index.
EXPLAIN (COSTS OFF)
SELECT c.id, o.total
FROM customers c JOIN orders o ON o.customer_id = c.id
WHERE c.id IN (1, 2, 3);

-- Every row on both sides: hash the smaller side, stream the larger past it.
EXPLAIN (COSTS OFF)
SELECT c.city, sum(o.total)
FROM customers c JOIN orders o ON o.customer_id = c.id
GROUP BY c.city;

-- The result must come out sorted by the join key: merge two sorted inputs.
EXPLAIN (COSTS OFF)
SELECT c.id, o.id
FROM customers c JOIN orders o ON o.customer_id = c.id
ORDER BY c.id;

