CREATE TABLE customers (id int PRIMARY KEY, city text NOT NULL);
CREATE TABLE orders (
  id          int PRIMARY KEY,
  customer_id int NOT NULL REFERENCES customers,
  total       int NOT NULL
);
INSERT INTO customers
SELECT g, (ARRAY['İstanbul', 'Ankara', 'İzmir', 'Bursa'])[g % 4 + 1]
FROM generate_series(1, 2000) AS g;
INSERT INTO orders SELECT g, g % 2000 + 1, g % 300 FROM generate_series(1, 20000) AS g;
CREATE INDEX orders_customer ON orders (customer_id);
ANALYZE customers, orders;

-- İzmir's 500 customers and their 5,000 orders. The planner's choice:
EXPLAIN (COSTS OFF)
SELECT sum(o.total) FROM customers c JOIN orders o ON o.customer_id = c.id
WHERE c.city = 'İzmir';

-- Its price in pages...
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT sum(o.total) FROM customers c JOIN orders o ON o.customer_id = c.id
WHERE c.city = 'İzmir';

-- ...against the alternatives it rejected, one switched off at a time.
SET LOCAL enable_hashjoin = off;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT sum(o.total) FROM customers c JOIN orders o ON o.customer_id = c.id
WHERE c.city = 'İzmir';

SET LOCAL enable_nestloop = off;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT sum(o.total) FROM customers c JOIN orders o ON o.customer_id = c.id
WHERE c.city = 'İzmir';

-- Nothing left to choose: "off" discourages, it doesn't forbid.
SET LOCAL enable_mergejoin = off;
EXPLAIN (COSTS OFF)
SELECT sum(o.total) FROM customers c JOIN orders o ON o.customer_id = c.id
WHERE c.city = 'İzmir';

files.sql/indexes/03-composite/examples/01_col:
-- LEARN(sql.indexes.composite): equality columns first, then the range or sort column.
CREATE TABLE orders (
  id        bigint PRIMARY KEY,
  shop_id   int NOT NULL,
  placed_on date NOT NULL,
  total     numeric(10,2) NOT NULL
);
-- 100 shops, 100 orders a day for 200 days: one order per shop per day.
INSERT INTO orders
SELECT g, g % 100 + 1, date '2026-01-01' + g / 100, g % 500 + 0.99
FROM generate_series(0, 19999) AS g;
ANALYZE orders;

-- The question: shop 7's orders in March and April.
SELECT count(*) FROM orders
WHERE shop_id = 7 AND placed_on BETWEEN '2026-03-01' AND '2026-04-30';

-- Range column first: the scan covers two months of every shop's entries.
CREATE INDEX orders_day_shop ON orders (placed_on, shop_id);
EXPLAIN (COSTS OFF)
SELECT id, total FROM orders
WHERE shop_id = 7 AND placed_on BETWEEN '2026-03-01' AND '2026-04-30';
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT id, total FROM orders
WHERE shop_id = 7 AND placed_on BETWEEN '2026-03-01' AND '2026-04-30';
DROP INDEX orders_day_shop;

-- Equality column first: shop 7's entries are adjacent, already sorted by day.
CREATE INDEX orders_shop_day ON orders (shop_id, placed_on);
EXPLAIN (COSTS OFF)
SELECT id, total FROM orders
WHERE shop_id = 7 AND placed_on BETWEEN '2026-03-01' AND '2026-04-30';
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT id, total FROM orders
WHERE shop_id = 7 AND placed_on BETWEEN '2026-03-01' AND '2026-04-30';

-- The same index serves the leading column alone, in index order...
EXPLAIN (COSTS OFF)
SELECT id, total FROM orders WHERE shop_id = 7 ORDER BY placed_on DESC LIMIT 10;

-- ...but a sort on a column it doesn't hold still needs a Sort.
EXPLAIN (COSTS OFF)
SELECT id, total FROM orders WHERE shop_id = 7 ORDER BY total DESC LIMIT 10;

files.sql/indexes/03-composite/examples/02_par:
CREATE TABLE tickets (
  id        bigint PRIMARY KEY,
  status    text NOT NULL,
  opened_on date NOT NULL,
  city      text NOT NULL
);
-- 2% open, the rest closed; city names arrive in capitals from an import.
INSERT INTO tickets
SELECT g,
       CASE WHEN g % 50 = 0 THEN 'open' ELSE 'closed' END,
       date '2026-01-01' + g / 100,
       (ARRAY['ISPARTA', 'IĞDIR', 'İZMİR', 'ANKARA'])[g % 4 + 1] || '-' || g
FROM generate_series(1, 20000) AS g;
ANALYZE tickets;

-- Partial: only rows matching the WHERE get an entry.
CREATE INDEX tickets_opened ON tickets (opened_on);
CREATE INDEX tickets_open_opened ON tickets (opened_on) WHERE status = 'open';
SELECT pg_relation_size('tickets_opened') / 8192 AS full_pages,
       pg_relation_size('tickets_open_opened') / 8192 AS partial_pages;

-- The query states the index's condition, so the planner can use it.
EXPLAIN (COSTS OFF)
SELECT id FROM tickets WHERE status = 'open' ORDER BY opened_on LIMIT 10;

-- Expression: index what the query compares, here Turkish lower-casing.
SELECT lower('ISPARTA') AS default_rules,
       lower('ISPARTA' COLLATE "tr-x-icu") AS turkish_rules;
CREATE INDEX tickets_city_tr ON tickets (lower(city COLLATE "tr-x-icu"));
ANALYZE tickets;

-- Same expression as the index, collation included: index scan, one match.
EXPLAIN (COSTS OFF)
SELECT id, city FROM tickets WHERE lower(city COLLATE "tr-x-icu") = 'ısparta-8';
SELECT id, city FROM tickets WHERE lower(city COLLATE "tr-x-icu") = 'ısparta-8';

-- A different expression: no index, and no match under the default rules.
EXPLAIN (COSTS OFF)
SELECT id, city FROM tickets WHERE lower(city) = 'ısparta-8';
SELECT id, city FROM tickets WHERE lower(city) = 'ısparta-8';

files.sql/indexes/03-composite/examples/03_cov:
-- Runtime sql-nontx: each statement commits on its own, so VACUUM can run
-- and record which table pages are visible to every transaction.
CREATE TABLE orders (
  id          bigint PRIMARY KEY,
  customer_id int NOT NULL,
  total       numeric(10,2) NOT NULL,
  note        text NOT NULL
);
INSERT INTO orders
SELECT g, g % 1000 + 1, g % 500 + 0.99, 'order ' || g FROM generate_series(1, 20000) AS g;
CREATE INDEX orders_customer ON orders (customer_id);
VACUUM (ANALYZE) orders;

-- Customer 42's total: the index finds 20 rows, the table supplies total.
EXPLAIN (COSTS OFF)
SELECT sum(total) FROM orders WHERE customer_id = 42;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT sum(total) FROM orders WHERE customer_id = 42;

-- Carry total in the index as payload: no table visits left.
CREATE INDEX orders_customer_total ON orders (customer_id) INCLUDE (total);
EXPLAIN (COSTS OFF)
SELECT sum(total) FROM orders WHERE customer_id = 42;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT sum(total) FROM orders WHERE customer_id = 42;

-- Payload is not a search key...
EXPLAIN (COSTS OFF)
SELECT count(*) FROM orders WHERE total = 42.99;

-- ...and it isn't free: an index with INCLUDE never deduplicates keys.
SELECT pg_relation_size('orders_customer') / 8192 AS key_only_pages,
       pg_relation_size('orders_customer_total') / 8192 AS covering_pages;

-- UNIQUE with INCLUDE: unique on email alone; name only rides along.
CREATE TABLE users (id int PRIMARY KEY, email text NOT NULL, name text NOT NULL);
CREATE UNIQUE INDEX users_email ON users (email) INCLUDE (name);
INSERT INTO users VALUES (1, 'ayse@example.com', 'Ayşe');
INSERT INTO users VALUES (2, 'ayse@example.com', 'Ayşe Yılmaz');

