CREATE TABLE project_settings (
  project text  PRIMARY KEY,
  prefs   jsonb NOT NULL
);
INSERT INTO project_settings VALUES
  ('TraceLite', '{"theme": "dark", "lang": "tr",
                  "notify": {"email": true, "slack": false}}');

-- || merges the top level only: the nested notify object is replaced whole.
SELECT prefs || '{"notify": {"slack": true}}' AS shallow_merge
FROM project_settings;

-- Change one nested value: a subscript assignment (PG 14) or jsonb_set.
UPDATE project_settings SET prefs['notify']['slack'] = 'true'
RETURNING prefs;
UPDATE project_settings SET prefs = jsonb_set(prefs, '{notify,sms}', 'false')
RETURNING prefs;

-- Delete a key with -, a nested one with #-.
UPDATE project_settings SET prefs = prefs - 'lang' #- '{notify,email}'
RETURNING prefs;

-- jsonb_set returns NULL when the new value is SQL NULL: an UPDATE built
-- this way nulls the whole document. jsonb_set_lax lets you choose.
SELECT jsonb_set(prefs, '{theme}', to_jsonb(NULL::text))          AS set_null,
       jsonb_set_lax(prefs, '{theme}', NULL)                      AS lax_default,
       jsonb_set_lax(prefs, '{theme}', NULL, true, 'delete_key')  AS lax_delete
FROM project_settings;

files.sql/json/03-indexing-design/examples/01_:
-- LEARN(sql.json.indexing-design): index the expression your query writes, not the document.
CREATE TABLE tickets (
  id  int   PRIMARY KEY,
  doc jsonb NOT NULL
);
INSERT INTO tickets
SELECT g, jsonb_build_object(
         'priority', CASE WHEN g % 100 = 0 THEN 1 ELSE 3 + g % 3 END,
         'reporter', 'user-' || g % 300,
         'labels',   CASE WHEN g % 50 = 0 THEN '["kvkk", "ui"]'::jsonb
                          ELSE '["ui"]'::jsonb END)
FROM generate_series(1, 20000) AS g;

CREATE INDEX tickets_doc ON tickets USING gin (doc jsonb_path_ops);
CREATE INDEX tickets_priority ON tickets (((doc ->> 'priority')::int));
ANALYZE tickets;

-- GIN with jsonb_path_ops serves jsonpath matches (@?, @@) as well as @>.
EXPLAIN (COSTS OFF)
SELECT id FROM tickets WHERE doc @? '$.labels[*] ? (@ == "kvkk")';

-- Ranges and sorting on one key are B-tree work: the expression index.
EXPLAIN (COSTS OFF)
SELECT id FROM tickets WHERE (doc ->> 'priority')::int <= 1;
EXPLAIN (COSTS OFF)
SELECT id, doc ->> 'reporter' AS reporter
FROM tickets
ORDER BY (doc ->> 'priority')::int
LIMIT 5;

-- A different expression with the same meaning doesn't match the index.
EXPLAIN (COSTS OFF)
SELECT id FROM tickets WHERE (doc -> 'priority')::int <= 1;

