-- Conventions: snake_case ASCII names, plural tables, id as the primary
-- key, <singular>_id for foreign keys, audit columns on every table.
CREATE TABLE projects (
  id   bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name text NOT NULL
);
CREATE TABLE test_cases (
  id         bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  project_id bigint NOT NULL REFERENCES projects,
  code       text   NOT NULL,
  title      text   NOT NULL CHECK (title <> ''),
  UNIQUE (project_id, code),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by text        NOT NULL DEFAULT current_user,
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- The names PostgreSQL generated: <table>_<columns>_<kind>.
SELECT conname, contype
FROM pg_constraint
WHERE conrelid = 'test_cases'::regclass AND contype <> 'n'
ORDER BY conname;

INSERT INTO projects (name) VALUES ('Checkout');
INSERT INTO test_cases (project_id, code, title) VALUES (1, 'TC-1', 'Valid card');
UPDATE test_cases SET title = 'Valid Visa card' WHERE code = 'TC-1';

-- A DEFAULT fires on INSERT only, so updated_at didn't move.
SELECT code, title, created_by, updated_at = created_at AS updated_at_unchanged
FROM test_cases;

-- Unquoted names fold to lower case, but only their ASCII letters.
CREATE TABLE "TestRuns" (id int);
CREATE TABLE Ürünler (Fiyat int);
SELECT c.relname, a.attname
FROM pg_class c
JOIN pg_attribute a ON a.attrelid = c.oid AND a.attnum = 1
WHERE c.relnamespace = current_schema()::regnamespace
  AND c.relname IN ('TestRuns', 'Ürünler')
ORDER BY c.relname;

SELECT * FROM ürünler;

files.sql/modeling/03-temporal/examples/03_bit:
CREATE EXTENSION btree_gist;

-- Bitemporal: valid_at is when a price applies in the world,
-- recorded_at is when the database believed it. Rows are never
-- overwritten; a change of mind closes recorded_at and adds new rows.
CREATE TABLE prices (
  sku         text,
  price       numeric(10, 2) NOT NULL,
  valid_at    daterange NOT NULL,
  recorded_at daterange NOT NULL,
  -- WITHOUT OVERLAPS handles one period; two periods need EXCLUDE.
  EXCLUDE USING gist (sku WITH =, valid_at WITH &&, recorded_at WITH &&)
);

-- 1 January: the cable costs 129.00, until further notice.
INSERT INTO prices VALUES ('usb-c', 129.00, '[2026-01-01,)', '[2026-01-01,)');

-- 1 March: from today it costs 149.00. The old belief is closed, and
-- the new belief is two rows: 129.00 until today, 149.00 from today.
UPDATE prices SET recorded_at = '[2026-01-01,2026-03-01)'
WHERE sku = 'usb-c' AND upper_inf(recorded_at);
INSERT INTO prices VALUES
  ('usb-c', 129.00, '[2026-01-01,2026-03-01)', '[2026-03-01,)'),
  ('usb-c', 149.00, '[2026-03-01,)',            '[2026-03-01,)');

-- 20 March: 149.00 was a typo, it should have been 139.00 all along.
UPDATE prices SET recorded_at = '[2026-03-01,2026-03-20)'
WHERE sku = 'usb-c' AND price = 149.00 AND upper_inf(recorded_at);
INSERT INTO prices VALUES ('usb-c', 139.00, '[2026-03-01,)', '[2026-03-20,)');

-- The price on 10 March, as the database knew it on three dates.
SELECT k.known_on, p.price
FROM (VALUES (date '2026-02-15'), (date '2026-03-15'), (date '2026-11-13')) AS k(known_on)
JOIN prices p
  ON p.sku = 'usb-c' AND p.valid_at @> date '2026-03-10' AND p.recorded_at @> k.known_on
ORDER BY k.known_on;

-- A second current belief about March would contradict the first.
INSERT INTO prices VALUES ('usb-c', 145.00, '[2026-03-15,)', '[2026-03-20,)');

files.sql/modeling/04-anti-patterns/examples/0:
CREATE TABLE requirements (id int PRIMARY KEY, code text NOT NULL);
CREATE TABLE test_cases   (id int PRIMARY KEY, code text NOT NULL);
INSERT INTO requirements VALUES (1, 'REQ-1');
INSERT INTO test_cases   VALUES (1, 'TC-1'), (2, 'TC-2');

-- Polymorphic association: target_type says which table target_id
-- points into. No foreign key can express "one of these tables".
CREATE TABLE comments_poly (
  id          int  PRIMARY KEY,
  target_type text NOT NULL,         -- 'requirement' or 'test_case'
  target_id   int  NOT NULL,
  body        text NOT NULL
);
INSERT INTO comments_poly VALUES
  (1, 'requirement', 1, 'Needs a 3-D Secure case'),
  (2, 'test_case',   2, 'Flaky on Android'),
  (3, 'test_case',   9, 'Points at nothing');
DELETE FROM test_cases WHERE id = 2;   -- comment 2 is now an orphan

-- Every read joins every possible target and sorts it out per row.
SELECT p.id, p.target_type, p.target_id, coalesce(r.code, t.code) AS target
FROM comments_poly p
LEFT JOIN requirements r ON p.target_type = 'requirement' AND r.id = p.target_id
LEFT JOIN test_cases t   ON p.target_type = 'test_case'   AND t.id = p.target_id
ORDER BY p.id;

-- Exclusive arc: one real foreign key per target, exactly one of them set.
CREATE TABLE comments (
  id             int  PRIMARY KEY,
  requirement_id int  REFERENCES requirements ON DELETE CASCADE,
  test_case_id   int  REFERENCES test_cases   ON DELETE CASCADE,
  body           text NOT NULL,
  CONSTRAINT comments_one_target
    CHECK (num_nonnulls(requirement_id, test_case_id) = 1)
);
CREATE INDEX ON comments (requirement_id);
CREATE INDEX ON comments (test_case_id);
INSERT INTO comments (id, requirement_id, body) VALUES (1, 1, 'Needs a 3-D Secure case');
INSERT INTO comments (id, test_case_id, body)   VALUES (2, 1, 'Passes on iOS 18');
DELETE FROM test_cases WHERE id = 1;   -- its comment goes with it
SELECT id, requirement_id, test_case_id, body FROM comments ORDER BY id;

INSERT INTO comments (id, test_case_id, body) VALUES (3, 9, 'Points at nothing');

CREATE TABLE requirements (id int PRIMARY KEY, code text NOT NULL UNIQUE);
INSERT INTO requirements VALUES (1, 'REQ-1'), (2, 'REQ-2'), (12, 'REQ-12');

-- 1. A comma-separated list of requirement ids in a text column.
CREATE TABLE test_cases_csv (code text PRIMARY KEY, req_ids text NOT NULL);
INSERT INTO test_cases_csv VALUES ('TC-1', '1,12'), ('TC-2', '2'), ('TC-3', '12, 99');

-- "Which tests cover requirement 1?" LIKE matches characters, not ids.
SELECT code FROM test_cases_csv WHERE req_ids LIKE '%1%' ORDER BY code;

-- 2. The same lists in a jsonb document: parsed, so matching is exact...
CREATE TABLE test_cases_doc (code text PRIMARY KEY, doc jsonb NOT NULL);
INSERT INTO test_cases_doc VALUES
  ('TC-1', '{"req_ids": [1, 12]}'),
  ('TC-2', '{"req_ids": [2]}'),
  ('TC-3', '{"req_ids": [12, 99]}');
SELECT code FROM test_cases_doc WHERE doc -> 'req_ids' @> '1' ORDER BY code;

-- ...but no foreign key reaches inside a string or a document. 99 was
-- accepted twice, and finding it means unpacking every row.
SELECT d.code, e.id AS dangling_id
FROM test_cases_doc d, jsonb_array_elements_text(d.doc -> 'req_ids') AS e(id)
WHERE e.id::int NOT IN (SELECT id FROM requirements)
ORDER BY d.code;

-- 3. A junction table: one row per link, a foreign key on each side.
CREATE TABLE test_cases (code text PRIMARY KEY);
CREATE TABLE test_case_requirements (
  test_case      text REFERENCES test_cases,
  requirement_id int  REFERENCES requirements,
  PRIMARY KEY (test_case, requirement_id)
);
CREATE INDEX ON test_case_requirements (requirement_id);
INSERT INTO test_cases VALUES ('TC-1'), ('TC-2'), ('TC-3');
INSERT INTO test_case_requirements VALUES
  ('TC-1', 1), ('TC-1', 12), ('TC-2', 2), ('TC-3', 12);
SELECT test_case FROM test_case_requirements WHERE requirement_id = 1 ORDER BY test_case;

INSERT INTO test_case_requirements VALUES ('TC-3', 99);

files.sql/modeling/05-multi-tenant/examples/01:
-- LEARN(sql.modeling.multi-tenant): the tenant is part of every key, so no row can point across tenants.
CREATE TABLE tenants (id int PRIMARY KEY, name text NOT NULL);
CREATE TABLE projects (
  id        int  PRIMARY KEY,
  tenant_id int  NOT NULL REFERENCES tenants,
  name      text NOT NULL,
  UNIQUE (tenant_id, id)                   -- the target for tenant-aware FKs
);
INSERT INTO tenants VALUES (1, 'Kuzey'), (2, 'Güney');
INSERT INTO projects VALUES (10, 1, 'Checkout'), (20, 2, 'Checkout');

-- Naive: the FK proves project 10 exists, not that it is Güney's.
CREATE TABLE requirements_naive (
  id         int  PRIMARY KEY,
  tenant_id  int  NOT NULL REFERENCES tenants,
  project_id int  NOT NULL REFERENCES projects,
  code       text NOT NULL
);
INSERT INTO requirements_naive VALUES (1, 2, 10, 'REQ-1');   -- accepted

-- Tenant-aware: the FK includes tenant_id, and so does uniqueness.
CREATE TABLE requirements (
  id         int  PRIMARY KEY,
  tenant_id  int  NOT NULL REFERENCES tenants,
  project_id int  NOT NULL,
  code       text NOT NULL,
  UNIQUE (tenant_id, code),
  FOREIGN KEY (tenant_id, project_id) REFERENCES projects (tenant_id, id)
);
CREATE INDEX ON requirements (tenant_id, project_id);
INSERT INTO requirements VALUES (1, 1, 10, 'REQ-1'), (2, 2, 20, 'REQ-1');

-- Every query filters by tenant. Forget it once, and the page shows both.
SELECT id, code, project_id FROM requirements WHERE tenant_id = 2 ORDER BY id;
SELECT tenant_id, id, code FROM requirements ORDER BY id;

-- Güney's requirement in Kuzey's project: (2, 10) is not a project.
INSERT INTO requirements VALUES (3, 2, 10, 'REQ-2');

files.sql/modeling/05-multi-tenant/examples/02:
-- One schema per tenant with the same tables in each. search_path picks
-- the tenant, so queries carry no tenant_id at all.
CREATE SCHEMA tenant_kuzey;
CREATE SCHEMA tenant_guney;
CREATE TABLE tenant_kuzey.requirements (id int PRIMARY KEY, code text NOT NULL UNIQUE);
CREATE TABLE tenant_guney.requirements (id int PRIMARY KEY, code text NOT NULL UNIQUE);
INSERT INTO tenant_kuzey.requirements VALUES (1, 'REQ-1'), (2, 'REQ-2');
INSERT INTO tenant_guney.requirements VALUES (1, 'REQ-1');

-- Per request, inside its transaction. SET LOCAL ends with the
-- transaction, so a pooled connection can't carry it to the next request.
SET LOCAL search_path TO tenant_guney;
SELECT id, code FROM requirements ORDER BY id;

-- A report across tenants is one query per schema.
SELECT 'guney' AS tenant, count(*) AS requirements FROM tenant_guney.requirements
UNION ALL
SELECT 'kuzey', count(*) FROM tenant_kuzey.requirements
ORDER BY tenant;

-- Every migration runs once per schema. One that stopped halfway leaves
-- the tenants on different schemas.
ALTER TABLE tenant_kuzey.requirements ADD COLUMN priority smallint NOT NULL DEFAULT 3;
SELECT table_schema, count(*) AS columns
FROM information_schema.columns
WHERE table_schema LIKE 'tenant\_%' AND table_name = 'requirements'
GROUP BY table_schema
ORDER BY table_schema;

-- The new application code expects the column; Güney never got it.
SELECT id, code, priority FROM requirements ORDER BY id;

files.sql/modeling/05-multi-tenant/examples/03:
-- Column tenancy enforced by the database: row-level security.
CREATE TABLE requirements (
  tenant_id int  NOT NULL DEFAULT current_setting('app.tenant')::int,
  id        int  PRIMARY KEY,
  code      text NOT NULL,
  UNIQUE (tenant_id, code)
);
INSERT INTO requirements VALUES (1, 1, 'REQ-1'), (1, 2, 'REQ-2'), (2, 3, 'REQ-1');

ALTER TABLE requirements ENABLE ROW LEVEL SECURITY;
-- The table owner bypasses policies unless they are forced on it too.
ALTER TABLE requirements FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON requirements
  USING (tenant_id = current_setting('app.tenant')::int);

-- Superusers and BYPASSRLS roles skip every policy. The app role must not.
SELECT rolsuper, rolbypassrls FROM pg_roles WHERE rolname = current_user;

-- Per request, inside its transaction: true means "local to it".
SELECT set_config('app.tenant', '2', true);

-- No tenant filter anywhere below: the policy adds it.
SELECT tenant_id, id, code FROM requirements ORDER BY id;
UPDATE requirements SET code = 'REQ-9' WHERE id = 1;     -- tenant 1's row
INSERT INTO requirements (id, code) VALUES (4, 'REQ-2'); -- tenant_id from the setting
SELECT tenant_id, id, code FROM requirements ORDER BY id;

-- A row for another tenant fails the policy's check.
INSERT INTO requirements (tenant_id, id, code) VALUES (1, 5, 'REQ-3');

files.sql/modern/01-16-to-18/examples/03_plann:
CREATE TABLE test_runs (
  status text NOT NULL,  -- three distinct values
  ran_on date NOT NULL
);
INSERT INTO test_runs
SELECT (ARRAY['failed', 'passed', 'skipped'])[g % 3 + 1], date '2026-01-01' + g % 300
FROM generate_series(1, 300000) AS g;
CREATE INDEX test_runs_status_ran_on ON test_runs (status, ran_on);
ANALYZE test_runs;
SELECT pg_relation_size('test_runs_status_ran_on') / 8192 AS index_pages;

-- PG 18 skip scan: the query never names status, the index's first column.
SELECT count(*) FROM test_runs WHERE ran_on = '2026-06-01';
-- Run it again under EXPLAIN ANALYZE, which in PG 18 also reports Index
-- Searches and, without asking, Buffers.
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT count(*) FROM test_runs WHERE ran_on = '2026-06-01';

-- PG 18 asynchronous I/O: how this server is configured.
SELECT current_setting('io_method') AS io_method,
       current_setting('io_workers') AS io_workers,
       current_setting('effective_io_concurrency') AS effective_io_concurrency;

files.sql/modifying/01-insert-update/examples/:
CREATE TABLE products (sku text PRIMARY KEY, price numeric(10,2) NOT NULL);
INSERT INTO products VALUES
  ('TEA-01', 210.00), ('COF-01', 145.00), ('LOK-01', 180.00),
  ('SIM-01', 15.00),  ('BAK-01', 1250.00);

CREATE TABLE price_list (sku text PRIMARY KEY, new_price numeric(10,2) NOT NULL);
INSERT INTO price_list VALUES ('TEA-01', 235.00), ('LOK-01', 195.00), ('XYZ-99', 1.00);

CREATE TABLE discontinued (sku text PRIMARY KEY);
INSERT INTO discontinued VALUES ('SIM-01'), ('COF-01');

-- UPDATE ... FROM joins the target to other tables; each joined row is
-- one update. Unmatched products (and XYZ-99) are left alone.
UPDATE products p
SET price = l.new_price
FROM price_list l
WHERE l.sku = p.sku;

-- DELETE ... USING: the same join idea, for deletes.
DELETE FROM products p
USING discontinued d
WHERE d.sku = p.sku;

SELECT sku, price FROM products ORDER BY sku;

-- The standard-SQL form, a subquery per row, touches EVERY row: BAK-01
-- has no new price, so it gets NULL. Here NOT NULL stops it.
UPDATE products
SET price = (SELECT l.new_price FROM price_list l WHERE l.sku = products.sku);

files.sql/modifying/02-returning-upsert/exampl:
-- LEARN(sql.modifying.returning-upsert): atomic upsert + read-back in one statement.

CREATE TABLE stock (sku text PRIMARY KEY, qty int NOT NULL CHECK (qty >= 0));
INSERT INTO stock VALUES ('widget', 10), ('gadget', 3);

-- Deliver a shipment: insert new skus, add to existing ones.
INSERT INTO stock (sku, qty)
VALUES ('widget', 5), ('gizmo', 7)
ON CONFLICT (sku) DO UPDATE
SET qty = stock.qty + EXCLUDED.qty
RETURNING sku, qty;

-- MERGE: same shape, but free to also delete or conditionally update.
CREATE TABLE incoming (sku text, qty int);
INSERT INTO incoming VALUES ('gadget', -2), ('doodad', 1);

MERGE INTO stock s
USING incoming i ON s.sku = i.sku
WHEN MATCHED AND s.qty + i.qty <= 0 THEN DELETE
WHEN MATCHED THEN UPDATE SET qty = s.qty + i.qty
WHEN NOT MATCHED THEN INSERT (sku, qty) VALUES (i.sku, i.qty)
RETURNING merge_action(), s.sku AS sku, s.qty AS qty;

files.sql/modifying/03-soft-delete/examples/01:
-- LEARN(sql.modifying.soft-delete): a deleted_at flag instead of DELETE, and what it breaks.
CREATE TABLE users (
  id         int GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  email      text NOT NULL UNIQUE,
  deleted_at timestamptz            -- NULL means live
);
INSERT INTO users (email) VALUES ('selin@example.com'), ('umut@example.com');

-- "Delete" Selin: an UPDATE. The row, and her data, stay.
UPDATE users SET deleted_at = '2026-11-01 10:00+03'
WHERE email = 'selin@example.com';

-- Every query must now remember the filter. Forget it once and a
-- deleted account is back in a list, an export, a count.
SELECT email FROM users ORDER BY id;
SELECT email FROM users WHERE deleted_at IS NULL ORDER BY id;

-- Selin signs up again. The UNIQUE constraint can't tell her deleted
-- row from a live one.
INSERT INTO users (email) VALUES ('selin@example.com');

files.sql/modifying/03-soft-delete/examples/02:
CREATE TABLE users (
  id         int GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  email      text NOT NULL,
  deleted_at timestamptz
);
-- Unique among live rows only: deleted rows are not in this index.
CREATE UNIQUE INDEX users_email_live ON users (email) WHERE deleted_at IS NULL;

-- One place that knows what "live" means; app queries read from it.
CREATE VIEW live_users AS
  SELECT id, email FROM users WHERE deleted_at IS NULL;

INSERT INTO users (email) VALUES ('selin@example.com'), ('umut@example.com');
UPDATE users SET deleted_at = '2026-11-01 10:00+03' WHERE id = 1;

-- Re-signup works now: the old row is outside the index predicate.
INSERT INTO users (email) VALUES ('selin@example.com');

SELECT id, email, deleted_at IS NOT NULL AS deleted FROM users ORDER BY id;
SELECT id, email FROM live_users ORDER BY id;

-- Two LIVE rows with one email are still impossible.
INSERT INTO users (email) VALUES ('umut@example.com');

files.sql/modifying/03-soft-delete/examples/03:
CREATE TABLE customers (
  id         int PRIMARY KEY,
  name       text,
  email      text,
  deleted_at timestamptz
);
CREATE TABLE orders (
  id          int PRIMARY KEY,
  customer_id int NOT NULL REFERENCES customers ON DELETE CASCADE,
  total       numeric(10,2) NOT NULL
);
INSERT INTO customers VALUES
  (1, 'Ayşe Kaya', 'ayse@example.com', NULL),
  (2, 'Can Demir', 'can@example.com',  NULL);
INSERT INTO orders VALUES (10, 1, 250.00), (11, 2, 720.00), (12, 2, 35.00);

-- Soft-delete Can. The foreign key only knows DELETE: CASCADE doesn't
-- fire, and a new order for him still passes the FK check.
UPDATE customers SET deleted_at = '2026-11-01 10:00+03' WHERE id = 2;
INSERT INTO orders VALUES (13, 2, 99.00);

-- Every join to customers now needs its own "AND c.deleted_at IS NULL".
SELECT c.name, count(*) AS orders, sum(o.total) AS revenue
FROM orders o
JOIN customers c ON c.id = o.customer_id
GROUP BY c.name
ORDER BY c.name;

-- If the orders must outlive the customer (invoices, tax records),
-- keep the row but erase what identifies him: the FK stays valid.
UPDATE customers SET name = NULL, email = NULL WHERE id = 2;
SELECT id, name, email, deleted_at IS NOT NULL AS deleted
FROM customers ORDER BY id;

-- If they needn't, a real DELETE lets the declared CASCADE do its job.
DELETE FROM customers WHERE id = 2;
SELECT id, customer_id, total FROM orders ORDER BY id;

files.sql/querying/01-select/examples/02_order:
CREATE TABLE scores (
  id     int PRIMARY KEY,
  player text NOT NULL,
  points int            -- NULL: hasn't played yet
);
INSERT INTO scores VALUES
  (1, 'deniz', 70), (2, 'emre', NULL), (3, 'selin', 90),
  (4, 'umut', 85),  (5, 'zeynep', 85), (6, 'ali', 60);

-- No ORDER BY means no promised order. Updating deniz (id 1) wrote a
-- new row version at the end of the table, so he's no longer "first".
UPDATE scores SET points = 72 WHERE id = 1;
SELECT id, player FROM scores LIMIT 3;

-- NULL sorts as larger than any value, so DESC puts it first.
SELECT player, points FROM scores ORDER BY points DESC LIMIT 2;

-- A leaderboard: NULLs last, and a unique tie-breaker (umut and zeynep
-- both have 85) so the cut at 2 is always the same rows.
SELECT player, points FROM scores
ORDER BY points DESC NULLS LAST, id
LIMIT 2;

-- Page 2 of the same ordering. OFFSET still computes the skipped rows.
SELECT player, points FROM scores
ORDER BY points DESC NULLS LAST, id
LIMIT 2 OFFSET 2;

-- "Top 2, including anyone tied with the last one" (PG 13+). The outer
-- ORDER BY fixes the display order, which ties leave open.
SELECT player, points
FROM (SELECT * FROM scores
      ORDER BY points DESC NULLS LAST
      FETCH FIRST 2 ROWS WITH TIES) AS top
ORDER BY points DESC, player;

files.sql/querying/01-select/examples/03_turki:
CREATE TABLE cities (name text PRIMARY KEY);
INSERT INTO cities VALUES
  ('Zonguldak'), ('İzmir'), ('Ankara'), ('Çorum'),
  ('Iğdır'), ('Ağrı'), ('Şırnak'), ('Isparta');

-- The database's collation (here the builtin C.UTF-8) sorts by Unicode
-- code point: every ASCII letter beats Ç, İ, Ş, and ğ comes after n and s.
SELECT name FROM cities ORDER BY name;

-- Turkish alphabetical order is a per-query (or per-column) choice:
-- A, Ağ, An, Ç, I, İ, Ş, Z.
SELECT name FROM cities ORDER BY name COLLATE "tr-x-icu";

-- Comparisons follow the collation too: "names before J" is a
-- different set of rows under each one.
SELECT name FROM cities WHERE name < 'J' ORDER BY name;
SELECT name FROM cities WHERE name < 'J' COLLATE "tr-x-icu"
ORDER BY name COLLATE "tr-x-icu";

files.sql/querying/02-null-logic/examples/01_t:
-- LEARN(sql.querying.null-logic): three-valued logic in one result set.

CREATE TABLE users (name text, email text);
INSERT INTO users VALUES
  ('ada', 'ada@example.com'),
  ('brin', NULL),
  ('cay', 'cay@example.com');

-- 1. Plain inequality: NULL rows silently vanish.
SELECT name FROM users WHERE email <> 'cay@example.com';

-- 2. The null-safe inequality: brin appears.
SELECT name FROM users WHERE email IS DISTINCT FROM 'cay@example.com';

-- 3. Display default for a missing value.
SELECT name, COALESCE(email, '(no email)') AS email FROM users ORDER BY name;

files.sql/search/03-trigram/examples/01_simila:
-- LEARN(sql.search.trigram): fuzzy matching by shared three-letter pieces.
CREATE EXTENSION pg_trgm;
SELECT show_trgm('Antalya') AS antalya, show_trgm('ığdır') AS igdir;

CREATE TABLE cities (name text PRIMARY KEY);
INSERT INTO cities VALUES
  ('Adana'), ('Ankara'), ('Antalya'), ('Aydın'), ('Çanakkale'), ('Eskişehir'),
  ('Iğdır'), ('Isparta'), ('İstanbul'), ('İzmir'), ('Kırşehir'), ('Şanlıurfa');

-- A typo still shares most trigrams. % means: similarity above 0.3.
SELECT name, round(similarity(name, 'Antlya')::numeric, 2) AS sim
FROM cities
WHERE name % 'Antlya';

-- "Did you mean": the nearest name by distance (<-> is 1 - similarity).
SELECT q AS typed, best.name AS nearest,
       round(similarity(best.name, q)::numeric, 2) AS sim
FROM (VALUES ('Istambul'), ('IZMIR'), ('eskisehir'), ('sanliurfa'),
             ('igdir'), ('ızmır')) AS t(q),
     LATERAL (SELECT name FROM cities ORDER BY name <-> q, name LIMIT 1) AS best
ORDER BY q;

files.sql/search/03-trigram/examples/02_unacce:
CREATE EXTENSION pg_trgm;
CREATE EXTENSION unaccent;
SELECT unaccent('Şanlıurfa, Iğdır, İzmir, Gümüşhane, Çeşme') AS unaccented;

-- One search key for every way of typing a name. RETURN binds unaccent and its
-- dictionary now; IMMUTABLE is a promise we make, not one Postgres checks.
CREATE FUNCTION search_key(text) RETURNS text
  LANGUAGE sql IMMUTABLE PARALLEL SAFE STRICT
  RETURN lower(unaccent('unaccent'::regdictionary, $1));

CREATE TABLE places (name text PRIMARY KEY);
INSERT INTO places VALUES
  ('Adana'), ('Ankara'), ('Antalya'), ('Aydın'), ('Çanakkale'), ('Eskişehir'),
  ('Iğdır'), ('Isparta'), ('İstanbul'), ('İzmir'), ('Kırşehir'), ('Şanlıurfa');
INSERT INTO places SELECT 'Köy ' || g FROM generate_series(1, 10000) AS g;
CREATE INDEX places_name_key ON places USING gin (search_key(name) gin_trgm_ops);
ANALYZE places;

SELECT q AS typed, search_key(q) AS key, best.name AS nearest,
       round(similarity(search_key(best.name), search_key(q))::numeric, 2) AS sim
FROM (VALUES ('Istambul'), ('IZMIR'), ('eskisehir'), ('sanliurfa'),
             ('igdir'), ('ızmır')) AS t(q),
     LATERAL (SELECT name FROM places
              ORDER BY search_key(name) <-> search_key(q), name LIMIT 1) AS best
ORDER BY q;

-- The index serves queries that spell the same expression.
EXPLAIN (COSTS OFF)
SELECT name FROM places WHERE search_key(name) % search_key('SANLIURFA');

-- The price of folding: distinct Turkish words get the same key.
SELECT search_key('kır') = search_key('kir') AS "kır = kir",
       search_key('ılık') = search_key('ilik') AS "ılık = ilik";

-- unaccent itself is only STABLE, so it can't go into an index directly.
CREATE INDEX ON places USING gin (lower(unaccent(name)) gin_trgm_ops);

