files.sql/security-ops/02-rls/examples/03_pool:
-- Runtime sql-nontx: one connection, several transactions, the way a pool
-- hands the same server session to request after request.
CREATE TABLE projects (id int PRIMARY KEY, tenant_id bigint NOT NULL, name text NOT NULL);
INSERT INTO projects VALUES (1, 1, 'Acme brakes'), (2, 2, 'Globex rail');
ALTER TABLE projects ENABLE ROW LEVEL SECURITY;
ALTER TABLE projects FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON projects
  USING (tenant_id = nullif(current_setting('app.tenant', true), '')::bigint);

-- Request 1 (tenant 1): the setting lives exactly as long as its transaction.
BEGIN;
SELECT set_config('app.tenant', '1', true);
SELECT name FROM projects;
COMMIT;

-- Request 2 forgot to set a tenant: the variable is still defined, but empty.
SELECT quote_literal(current_setting('app.tenant', true)) AS leftover,
       count(*) AS visible
FROM projects;

-- Request 3 (tenant 2) sets it for the whole session instead...
SELECT set_config('app.tenant', '2', false);
SELECT name FROM projects;
-- ...and request 4, someone else's, runs on the same connection without
-- setting a tenant. It inherits tenant 2.
SELECT name FROM projects;

-- The same policy without nullif: an empty leftover breaks the cast.
ALTER POLICY tenant_isolation ON projects
  USING (tenant_id = current_setting('app.tenant', true)::bigint);
RESET app.tenant;
SELECT name FROM projects;

files.sql/security-ops/03-pooling-config/examp:
-- LEARN(sql.security-ops.pooling-config): connections and memory are the two knobs to learn first.
-- context: when a change takes effect, and who may make it. boot_val is the
-- built-in default; the live values depend on your server, so they aren't shown.
SELECT name, context, boot_val, unit
FROM pg_settings
WHERE name IN ('max_connections', 'superuser_reserved_connections',
               'reserved_connections', 'shared_buffers', 'effective_cache_size',
               'work_mem', 'hash_mem_multiplier', 'maintenance_work_mem',
               'temp_file_limit', 'idle_in_transaction_session_timeout')
ORDER BY context, name;

-- context 'user': any session may change it for itself, even for one transaction.
SET LOCAL work_mem = '64MB';
SHOW work_mem;
SET LOCAL idle_in_transaction_session_timeout = '30s';
SHOW idle_in_transaction_session_timeout;

-- context 'postmaster': the memory and the process slots are set up at start.
SET LOCAL shared_buffers = '1GB';

CREATE TABLE trace_links (
  id             int PRIMARY KEY,
  requirement_id int NOT NULL,
  test_case_id   int NOT NULL,
  note           text NOT NULL
);
INSERT INTO trace_links
SELECT g, g % 5000, g % 997, md5(g::text) FROM generate_series(1, 50000) AS g;
ANALYZE trace_links;

-- How the top Sort node ran, read from EXPLAIN ANALYZE's JSON output.
-- The query really runs; its rows are discarded.
CREATE FUNCTION sort_run(query text, OUT method text, OUT stored_in text)
LANGUAGE plpgsql AS $$
DECLARE plan json;
BEGIN
  EXECUTE 'EXPLAIN (ANALYZE, FORMAT JSON) ' || query INTO plan;
  method    := plan -> 0 -> 'Plan' ->> 'Sort Method';
  stored_in := plan -> 0 -> 'Plan' ->> 'Sort Space Type';
END $$;

-- Sorting all 50,000 rows in memory takes about 4.6 MB.
SET LOCAL work_mem = '4MB';  -- the built-in default
SELECT * FROM sort_run('SELECT * FROM trace_links ORDER BY note');
SET LOCAL work_mem = '8MB';
SELECT * FROM sort_run('SELECT * FROM trace_links ORDER BY note');

-- Back to 4MB, but only the first 20 rows are wanted.
SET LOCAL work_mem = '4MB';
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF)
SELECT * FROM trace_links ORDER BY note LIMIT 20;

-- Runtime sql-nontx: one server session, as a pool hands it from client to
-- client. Client 1 leaves session state behind:
SET work_mem = '256MB';
SELECT set_config('app.tenant', '1', false);
PREPARE project_by_id (int) AS SELECT $1 AS id;
CREATE TEMP TABLE import_rows (line text);
SELECT pg_advisory_lock(7310);
LISTEN requirement_changed;

-- What client 2 inherits if it gets this server session next.
SELECT (SELECT source = 'session' FROM pg_settings WHERE name = 'work_mem') AS work_mem_set,
       current_setting('app.tenant', true) AS tenant,
       (SELECT count(*) FROM pg_prepared_statements) AS prepared,
       to_regclass('pg_temp.import_rows') IS NOT NULL AS temp_table,
       (SELECT count(*) FROM pg_locks
        WHERE locktype = 'advisory' AND pid = pg_backend_pid()) AS advisory_locks,
       (SELECT count(*) FROM pg_listening_channels()) AS listening;

-- PgBouncer in session mode sends this before giving the server session
-- to another client (its default server_reset_query).
DISCARD ALL;

SELECT (SELECT source = 'session' FROM pg_settings WHERE name = 'work_mem') AS work_mem_set,
       current_setting('app.tenant', true) AS tenant,
       (SELECT count(*) FROM pg_prepared_statements) AS prepared,
       to_regclass('pg_temp.import_rows') IS NOT NULL AS temp_table,
       (SELECT count(*) FROM pg_locks
        WHERE locktype = 'advisory' AND pid = pg_backend_pid()) AS advisory_locks,
       (SELECT count(*) FROM pg_listening_channels()) AS listening;

files.sql/security-ops/04-backup-migrations/ex:
-- LEARN(sql.security-ops.backup-migrations): PITR replays the WAL, so what isn't in the WAL can't come back.
-- Every change to an ordinary table is written to the write-ahead log (WAL)
-- first. Archiving ships that log; point-in-time recovery replays it.
CREATE TABLE audit_log (id int PRIMARY KEY, event text NOT NULL);
-- UNLOGGED skips the WAL: faster writes, no crash safety, no recovery.
CREATE UNLOGGED TABLE import_scratch (id int PRIMARY KEY, event text NOT NULL);

-- How many WAL records a statement wrote, from EXPLAIN (ANALYZE, WAL).
CREATE FUNCTION wal_records(stmt text) RETURNS bigint LANGUAGE plpgsql AS $$
DECLARE plan json;
BEGIN
  EXECUTE 'EXPLAIN (ANALYZE, WAL, FORMAT JSON) ' || stmt INTO plan;
  RETURN (plan -> 0 -> 'Plan' ->> 'WAL Records')::bigint;
END $$;

SELECT wal_records($$INSERT INTO audit_log
                     SELECT g, 'login ' || g FROM generate_series(1, 1000) AS g$$) AS logged,
       wal_records($$INSERT INTO import_scratch
                     SELECT g, 'login ' || g FROM generate_series(1, 1000) AS g$$) AS unlogged;

-- Both tables hold 1000 rows now; after a crash or a restore, only one would.
SELECT relname, relpersistence, (SELECT count(*) FROM audit_log) AS audit_rows,
       (SELECT count(*) FROM import_scratch) AS scratch_rows
FROM pg_class WHERE relname IN ('audit_log', 'import_scratch') ORDER BY relname;

-- A named WAL position to recover to, taken just before a risky migration.
SELECT pg_create_restore_point('before-migration-0042');

-- A case-insensitive unique index, built without blocking writes.
A: CREATE UNIQUE INDEX CONCURRENTLY users_email_lower ON users (lower(email));
-- It failed on the duplicate, and left something behind.
A: SELECT indexrelid::regclass AS index, indisvalid, indisready
   FROM pg_index WHERE indrelid = 'users'::regclass ORDER BY 1;
A: INSERT INTO users (email) VALUES ('AYSE@example.com');

-- Clean up: drop the leftover, fix the data, try again.
A: DROP INDEX CONCURRENTLY users_email_lower;
A: DELETE FROM users WHERE email <> lower(email);

-- Meanwhile B starts a read-only report that keeps one snapshot.
B: BEGIN ISOLATION LEVEL REPEATABLE READ;
B: SELECT count(*) FROM users;
A: CREATE UNIQUE INDEX CONCURRENTLY users_email_lower ON users (lower(email));
B: SELECT command, phase FROM pg_stat_progress_create_index;
B: COMMIT;
A: SELECT indexrelid::regclass AS index, indisvalid, indisready
   FROM pg_index WHERE indrelid = 'users'::regclass ORDER BY 1;

-- Runtime sql-nontx: every statement commits on its own, as in a migration tool.
CREATE TABLE projects (id bigint PRIMARY KEY, code text NOT NULL UNIQUE);
CREATE TABLE requirements (id bigint PRIMARY KEY, project_code text NOT NULL);
INSERT INTO projects SELECT g, 'P' || g FROM generate_series(1, 10) AS g;
INSERT INTO requirements SELECT g, 'P' || (g % 10 + 1) FROM generate_series(1, 1000) AS g;
CREATE VIEW my_locks AS
  SELECT relation::regclass AS tbl, mode FROM pg_locks
  WHERE pid = pg_backend_pid() AND locktype = 'relation'
    AND relation IN ('projects'::regclass, 'requirements'::regclass);

-- Goal: replace project_code with a real foreign key. Expand: a nullable column.
ALTER TABLE requirements ADD COLUMN project_id bigint;

-- Guard new writes now, check old rows later.
BEGIN;
ALTER TABLE requirements ADD CONSTRAINT requirements_project_fk
  FOREIGN KEY (project_id) REFERENCES projects NOT VALID;
SELECT * FROM my_locks ORDER BY tbl, mode;
COMMIT;

-- Backfill in batches, one transaction each, so no lock is held for long.
CREATE PROCEDURE backfill_project_id(batch int) LANGUAGE plpgsql AS $$
DECLARE n int;
BEGIN
  LOOP
    UPDATE requirements r SET project_id = p.id
    FROM projects p
    WHERE p.code = r.project_code
      AND r.id IN (SELECT id FROM requirements WHERE project_id IS NULL
                   ORDER BY id LIMIT batch);
    GET DIAGNOSTICS n = ROW_COUNT;
    EXIT WHEN n = 0;
    COMMIT;
    RAISE NOTICE 'committed a batch of % rows', n;
  END LOOP;
END $$;
CALL backfill_project_id(400);

-- Now check the old rows, under a lock that lets reads and writes continue.
BEGIN;
ALTER TABLE requirements VALIDATE CONSTRAINT requirements_project_fk;
SELECT * FROM my_locks ORDER BY tbl, mode;
COMMIT;

files.sql/security-ops/05-monitoring/examples/:
-- LEARN(sql.security-ops.monitoring): when it's slow, first ask who is waiting, on what, and for whom.
A: INSERT INTO sessions VALUES ('A', pg_backend_pid());
B: INSERT INTO sessions VALUES ('B', pg_backend_pid());

-- A starts a transfer, then stalls before COMMIT (a slow HTTP call, say).
A: BEGIN;
A: UPDATE accounts SET balance = balance - 10 WHERE id = 1;
B: SELECT s.name, a.state, a.wait_event_type, a.wait_event, a.query
   FROM pg_stat_activity a JOIN sessions s USING (pid)
   WHERE s.name = 'A';

-- B wants the same row and has to wait.
B: UPDATE accounts SET balance = balance + 10 WHERE id = 1;
A: SELECT s.name, a.state, a.wait_event_type, a.wait_event,
          (SELECT array_agg(b.name) FROM sessions b
           WHERE b.pid = ANY (pg_blocking_pids(a.pid))) AS blocked_by
   FROM pg_stat_activity a JOIN sessions s USING (pid)
   WHERE s.name = 'B';
A: SELECT l.locktype, l.mode, l.granted
   FROM pg_locks l JOIN sessions s USING (pid)
   WHERE s.name = 'B' AND NOT l.granted;
A: COMMIT;

CREATE TABLE test_runs (
  id           int PRIMARY KEY,
  test_case_id int NOT NULL,
  status       text NOT NULL
);
INSERT INTO test_runs
SELECT g, g % 500, CASE WHEN g % 10 = 0 THEN 'failed' ELSE 'passed' END
FROM generate_series(1, 20000) AS g;
ANALYZE test_runs;

-- This transaction's counters for the table. pg_stat_user_tables has the same
-- columns, accumulated from every session since the last statistics reset.
CREATE VIEW counters AS
  SELECT seq_scan, seq_tup_read, idx_scan, idx_tup_fetch, n_tup_ins
  FROM pg_stat_xact_user_tables WHERE relname = 'test_runs';
SELECT * FROM counters;

-- A dashboard asks for one test case's runs. No index on test_case_id yet.
SELECT count(*) FROM test_runs WHERE test_case_id = 42;
SELECT count(*) FROM test_runs WHERE test_case_id = 43;
SELECT * FROM counters;

CREATE INDEX test_runs_case ON test_runs (test_case_id);
SELECT count(*) FROM test_runs WHERE test_case_id = 42;
SELECT count(*) FROM test_runs WHERE test_case_id = 43;
SELECT * FROM counters;

-- The shared view hasn't seen any of it yet.
SELECT seq_scan, idx_scan FROM pg_stat_user_tables WHERE relname = 'test_runs';

A: INSERT INTO sessions VALUES ('A', pg_backend_pid());

-- A starts a report that runs far longer than anyone wants.
A: SELECT pg_sleep(4);
B: SELECT state, wait_event_type, wait_event, query
   FROM pg_stat_activity WHERE pid = (SELECT pid FROM sessions WHERE name = 'A');
B: SELECT pg_cancel_backend(pid) AS cancelled FROM sessions WHERE name = 'A';

-- The guard that doesn't need a human: a statement timeout.
A: SET statement_timeout = '200ms';
A: SELECT pg_sleep(1);
A: SELECT 'the session is still usable' AS status;

files.sql/server-side/01-views/examples/01_nam:
-- LEARN(sql.server-side.views): a view stores a query, never rows.
CREATE TABLE requirements (
  id    int  PRIMARY KEY,
  code  text NOT NULL UNIQUE,
  title text NOT NULL
);
CREATE TABLE test_cases (
  id             int  PRIMARY KEY,
  requirement_id int  NOT NULL REFERENCES requirements,
  status         text NOT NULL  -- result of the latest run
);
INSERT INTO requirements VALUES
  (1, 'REQ-LOGIN', 'Kullanıcı girişi'),
  (2, 'REQ-EXPORT', 'CSV dışa aktarım'),
  (3, 'REQ-AUDIT', 'Denetim izi');
INSERT INTO test_cases VALUES (10, 1, 'passed'), (11, 1, 'failed'), (12, 2, 'passed');

-- One definition of "coverage" for every report, endpoint and psql session.
CREATE VIEW requirement_coverage AS
SELECT r.code,
       count(t.id) AS tests,
       count(t.id) FILTER (WHERE t.status = 'passed') AS passed
FROM requirements r
LEFT JOIN test_cases t ON t.requirement_id = r.id
GROUP BY r.id, r.code;

SELECT * FROM requirement_coverage WHERE passed < tests OR tests = 0 ORDER BY code;

-- The planner expands the view like a macro and pushes the filter down.
EXPLAIN (COSTS OFF) SELECT * FROM requirement_coverage WHERE code = 'REQ-LOGIN';

-- SELECT * is expanded once, when the view is created.
CREATE VIEW requirement_list AS SELECT * FROM requirements;
ALTER TABLE requirements ADD COLUMN priority int NOT NULL DEFAULT 2;
SELECT * FROM requirement_list ORDER BY id;
SELECT trim(regexp_replace(pg_get_viewdef('requirement_list'::regclass), '\s+', ' ', 'g')) AS stored_query;

-- Views pin the columns they use.
ALTER TABLE test_cases ALTER COLUMN status TYPE varchar(10);

files.sql/server-side/01-views/examples/02_upd:
CREATE TABLE test_cases (
  id         int  PRIMARY KEY,
  project_id int  NOT NULL,
  title      text NOT NULL,
  status     text NOT NULL
);
INSERT INTO test_cases VALUES
  (1, 1, 'Giriş', 'failed'), (2, 1, 'Çıkış', 'passed'), (3, 2, 'Fatura', 'failed');

-- One table, no aggregates, DISTINCT or LIMIT: automatically updatable.
CREATE VIEW project1_cases AS
SELECT id, project_id, title, status FROM test_cases WHERE project_id = 1;

-- Writes through the view see only the view's rows.
UPDATE project1_cases SET status = 'retest' WHERE status = 'failed';
SELECT id, project_id, status FROM test_cases ORDER BY id;

-- Without a check option, the view accepts rows it would not show.
INSERT INTO project1_cases VALUES (4, 2, 'Rapor', 'failed');
SELECT count(*) AS visible_through_view FROM project1_cases WHERE id = 4;

-- WITH CHECK OPTION: every written row must satisfy the view's WHERE.
CREATE OR REPLACE VIEW project1_cases AS
SELECT id, project_id, title, status FROM test_cases WHERE project_id = 1
WITH CHECK OPTION;
UPDATE project1_cases SET status = 'passed' WHERE id = 1;
UPDATE project1_cases SET project_id = 2 WHERE id = 2;

files.sql/server-side/01-views/examples/03_mat:
-- A materialized view runs its query once and stores the result.
A: CREATE MATERIALIZED VIEW pass_rates AS
   SELECT requirement, count(*) AS runs, count(*) FILTER (WHERE passed) AS passed
   FROM test_runs
   GROUP BY requirement;
A: CREATE UNIQUE INDEX ON pass_rates (requirement);

-- New runs arrive; the stored rows don't change until a refresh.
B: INSERT INTO test_runs (requirement, passed) VALUES ('REQ-LOGIN', true);
B: SELECT * FROM pass_rates ORDER BY requirement;

-- A plain REFRESH rebuilds it under an ACCESS EXCLUSIVE lock: readers wait.
A: BEGIN;
A: REFRESH MATERIALIZED VIEW pass_rates;
B: SELECT * FROM pass_rates ORDER BY requirement;
A: COMMIT;

-- CONCURRENTLY computes the new result, diffs it against the stored one
-- and applies the difference; readers keep seeing the old rows meanwhile.
B: INSERT INTO test_runs (requirement, passed) VALUES ('REQ-EXPORT', false);
A: BEGIN;
A: REFRESH MATERIALIZED VIEW CONCURRENTLY pass_rates;
B: SELECT * FROM pass_rates ORDER BY requirement;
A: COMMIT;
B: SELECT * FROM pass_rates ORDER BY requirement;

