-- Runtime sql-nontx: autocommit, so CALL runs in a transaction of its own.
CREATE TABLE test_runs (id int PRIMARY KEY, ran_on date NOT NULL);
CREATE TABLE test_runs_archive (LIKE test_runs);
INSERT INTO test_runs
SELECT g, date '2026-01-01' + g / 100 FROM generate_series(1, 1000) AS g;

-- A procedure may COMMIT: each batch becomes durable on its own, so a
-- big cleanup never holds its locks for the whole run.
CREATE PROCEDURE archive_runs(cutoff date, batch_size int)
LANGUAGE plpgsql
AS $$
DECLARE
  moved int;
BEGIN
  LOOP
    WITH batch AS (
      DELETE FROM test_runs
      WHERE id IN (SELECT id FROM test_runs WHERE ran_on < cutoff ORDER BY id LIMIT batch_size)
      RETURNING *
    )
    INSERT INTO test_runs_archive SELECT * FROM batch;
    GET DIAGNOSTICS moved = ROW_COUNT;
    EXIT WHEN moved = 0;
    COMMIT;
    RAISE NOTICE 'archived % runs', moved;
  END LOOP;
END
$$;

CALL archive_runs('2026-01-04', 120);
SELECT (SELECT count(*) FROM test_runs) AS live,
       (SELECT count(*) FROM test_runs_archive) AS archived;

-- Inside a transaction block the caller owns the transaction, so the
-- procedure may not end it.
BEGIN;
CALL archive_runs('2026-01-08', 120);

files.sql/server-side/03-triggers/examples/02_:
CREATE TABLE test_cases (id int PRIMARY KEY, title text NOT NULL, status text NOT NULL);
CREATE TABLE audit_log (
  id      bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tbl     text  NOT NULL,
  op      text  NOT NULL,
  row_id  int   NOT NULL,
  changes jsonb NOT NULL,
  at      timestamptz NOT NULL DEFAULT now(),
  by_role text  NOT NULL DEFAULT current_user
);

-- One generic function for every audited table: TG_* says where it fired.
CREATE FUNCTION audit_row() RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  old_row jsonb := CASE WHEN TG_OP <> 'INSERT' THEN to_jsonb(OLD) END;
  new_row jsonb := CASE WHEN TG_OP <> 'DELETE' THEN to_jsonb(NEW) END;
BEGIN
  INSERT INTO audit_log (tbl, op, row_id, changes)
  VALUES (TG_TABLE_NAME, TG_OP, (coalesce(new_row, old_row) ->> 'id')::int,
          CASE TG_OP
            WHEN 'UPDATE' THEN (SELECT jsonb_object_agg(k, jsonb_build_array(old_row -> k, v))
                                FROM jsonb_each(new_row) AS e(k, v)
                                WHERE old_row -> k IS DISTINCT FROM v)
            ELSE coalesce(new_row, old_row)
          END);
  RETURN NULL;  -- AFTER trigger: the return value is ignored
END
$$;

CREATE TRIGGER test_cases_audit
  AFTER INSERT OR UPDATE OR DELETE ON test_cases
  FOR EACH ROW EXECUTE FUNCTION audit_row();

INSERT INTO test_cases VALUES (1, 'Giriş', 'failed'), (2, 'Çıkış', 'passed');
UPDATE test_cases SET status = 'passed' WHERE id = 1;
DELETE FROM test_cases WHERE id = 2;

-- A change that is rolled back takes its audit row with it.
SAVEPOINT before_mistake;
UPDATE test_cases SET title = 'Yanlış' WHERE id = 1;
ROLLBACK TO before_mistake;

SELECT id, tbl, op, row_id, changes FROM audit_log ORDER BY id;

files.sql/server-side/03-triggers/examples/03_:
CREATE TABLE requirements (
  id         int  PRIMARY KEY,
  code       text NOT NULL,
  status     text NOT NULL,
  deleted_at timestamptz
);
CREATE TABLE test_cases (
  id             int  PRIMARY KEY,
  requirement_id int  NOT NULL REFERENCES requirements,
  status         text NOT NULL
);
INSERT INTO requirements VALUES (1, 'REQ-LOGIN', 'failing', NULL), (2, 'REQ-OLD', 'passing', NULL);
INSERT INTO test_cases VALUES (10, 1, 'failed'), (11, 1, 'failed'), (12, 1, 'passed');

-- Trigger 1: turn every DELETE into a soft delete.
CREATE FUNCTION soft_delete() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  UPDATE requirements SET deleted_at = now() WHERE id = OLD.id;
  RETURN NULL;  -- skip the real DELETE
END
$$;
CREATE TRIGGER requirements_soft_delete BEFORE DELETE ON requirements
  FOR EACH ROW EXECUTE FUNCTION soft_delete();

-- Trigger 2: roll test results up into the requirement's status.
CREATE FUNCTION roll_up() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE NOTICE 'roll_up for test case %', NEW.id;
  UPDATE requirements
  SET status = CASE WHEN (SELECT bool_and(status = 'passed') FROM test_cases
                          WHERE requirement_id = NEW.requirement_id)
                    THEN 'passing' ELSE 'failing' END
  WHERE id = NEW.requirement_id;
  RETURN NULL;
END
$$;
CREATE TRIGGER test_cases_roll_up AFTER UPDATE ON test_cases
  FOR EACH ROW EXECUTE FUNCTION roll_up();

-- The DELETE reports 0 rows, yet the row changed.
DELETE FROM requirements WHERE code = 'REQ-OLD';
SELECT code, status, deleted_at IS NOT NULL AS deleted FROM requirements ORDER BY id;

-- One UPDATE statement; three trigger calls and three hidden UPDATEs.
UPDATE test_cases SET status = 'passed' WHERE requirement_id = 1;
SELECT code, status FROM requirements ORDER BY id;

-- Nothing in either statement mentions this. Only the catalog does.
SELECT event_object_table AS on_table, trigger_name, action_timing, event_manipulation AS event
FROM information_schema.triggers
WHERE event_object_schema = current_schema()
ORDER BY on_table, trigger_name;

files.sql/server-side/04-listen-notify-ext/exa:
-- Runtime sql-nontx: autocommit, like psql, so each statement is its own
-- transaction unless BEGIN says otherwise.
LISTEN test_runs;
SELECT pg_listening_channels() AS listening;

-- LISTEN and UNLISTEN are transactional: they take effect at COMMIT.
BEGIN;
LISTEN requirements;
SELECT pg_listening_channels() AS listening ORDER BY 1;
COMMIT;
SELECT pg_listening_channels() AS listening ORDER BY 1;

BEGIN;
UNLISTEN *;
ROLLBACK;
SELECT count(*) AS still_listening FROM pg_listening_channels();

-- NOTIFY takes a literal payload; pg_notify() takes any expression.
-- This session listens on test_runs, so it gets these back itself; the
-- runner just doesn't display asynchronous messages (a pgx program does).
NOTIFY test_runs, 'run 42 finished';
SELECT pg_notify('test_runs', json_build_object('run', 42, 'status', 'failed')::text);

-- Payloads must be shorter than 8000 bytes: bytes, not characters.
SELECT octet_length(repeat('ş', 3999)) AS bytes_3999, octet_length(repeat('ş', 4000)) AS bytes_4000;
SELECT pg_notify('test_runs', repeat('ş', 3999));
SELECT pg_notify('test_runs', repeat('ş', 4000));

files.sql/subqueries-ctes/03-modifying/example:
-- LEARN(sql.subqueries-ctes.modifying): RETURNING turns a write into rows the rest of the statement can read.
CREATE TABLE test_runs (
  id        int PRIMARY KEY,
  test_case text NOT NULL,
  ran_on    date NOT NULL,
  passed    boolean NOT NULL
);
CREATE TABLE test_runs_archive (LIKE test_runs INCLUDING ALL);
INSERT INTO test_runs VALUES
  (1, 'Login', '2026-10-02', true), (2, 'Login', '2026-11-12', false),
  (3, 'Export', '2026-10-20', true), (4, 'Export', '2026-11-13', true);

-- Move October's runs to the archive in one statement: a run can't be
-- deleted without being archived, or archived twice.
WITH moved AS (
  DELETE FROM test_runs
  WHERE ran_on < date '2026-11-01'
  RETURNING *
)
INSERT INTO test_runs_archive
SELECT * FROM moved;

SELECT 'live' AS place, id FROM test_runs
UNION ALL
SELECT 'archive', id FROM test_runs_archive
ORDER BY place, id;

-- A parent and its children in one round trip: generated ids flow from
-- the first INSERT's RETURNING into the second.
CREATE TABLE requirements (
  id   int GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  code text NOT NULL UNIQUE
);
CREATE TABLE test_cases (
  id             int GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  requirement_id int NOT NULL REFERENCES requirements,
  title          text NOT NULL
);
WITH req AS (
  INSERT INTO requirements (code) VALUES ('REQ-EXPORT') RETURNING id
), tests AS (
  INSERT INTO test_cases (requirement_id, title)
  SELECT req.id, t.title
  FROM req, (VALUES ('CSV header row'), ('UTF-8 with BOM for Excel')) AS t(title)
  RETURNING requirement_id, id, title
)
SELECT * FROM tests ORDER BY id;

CREATE TABLE test_cases (id int PRIMARY KEY, title text NOT NULL, status text NOT NULL);
INSERT INTO test_cases VALUES
  (1, 'Login', 'failed'), (2, 'Logout', 'passed'), (3, 'Export', 'failed');

-- Every part of the statement reads the same snapshot, taken before any of
-- it ran. The table still shows the old status; RETURNING shows the new one.
WITH reopened AS (
  UPDATE test_cases SET status = 'retest'
  WHERE status = 'failed'
  RETURNING id, status
)
SELECT t.id, t.status AS in_table, r.status AS returned
FROM test_cases t
LEFT JOIN reopened r ON r.id = t.id
ORDER BY t.id;

-- The next statement sees the change.
SELECT id, status FROM test_cases ORDER BY id;

-- Get-or-create a tag. If the INSERT adds a row, only RETURNING can show it;
-- if the tag already exists, the INSERT returns nothing and the SELECT finds it.
CREATE TABLE tags (id int GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name text UNIQUE NOT NULL);
INSERT INTO tags (name) VALUES ('security');

WITH ins AS (
  INSERT INTO tags (name) VALUES ('kvkk') ON CONFLICT (name) DO NOTHING
  RETURNING id, 'created' AS how
)
SELECT id, how FROM ins
UNION ALL
SELECT id, 'found' FROM tags WHERE name = 'kvkk';

WITH ins AS (
  INSERT INTO tags (name) VALUES ('security') ON CONFLICT (name) DO NOTHING
  RETURNING id, 'created' AS how
)
SELECT id, how FROM ins
UNION ALL
SELECT id, 'found' FROM tags WHERE name = 'security';

-- Data-modifying WITH is allowed only on the top-level statement.
SELECT count(*)
FROM (WITH gone AS (DELETE FROM tags RETURNING id) SELECT id FROM gone) AS s;

CREATE TABLE test_cases (id int PRIMARY KEY, title text NOT NULL, status text NOT NULL);
CREATE TABLE status_changes (
  test_case_id int  NOT NULL REFERENCES test_cases,
  old_status   text NOT NULL,
  new_status   text NOT NULL
);
INSERT INTO test_cases VALUES
  (1, 'Login', 'failed'), (2, 'Logout', 'passed'), (3, 'Export', 'retest');

-- Change rows and write the audit trail in one statement. RETURNING old.*
-- and new.* (PG 18) hand both versions of each row to the next step.
WITH changed AS (
  UPDATE test_cases SET status = 'passed'
  WHERE id IN (1, 2, 3) AND status <> 'passed'
  RETURNING id, old.status AS old_status, new.status AS new_status
), logged AS (
  INSERT INTO status_changes (test_case_id, old_status, new_status)
  SELECT id, old_status, new_status FROM changed
  RETURNING *
)
SELECT * FROM logged ORDER BY test_case_id;

-- Logout was already passed: not updated, so not logged.
SELECT id, status FROM test_cases ORDER BY id;

files.sql/tables-types/01-text-numbers/example:
CREATE TABLE users (
  full_name text       NOT NULL,  -- no arbitrary limit: the usual choice
  handle    varchar(6) NOT NULL   -- the limit is checked on every write
);

INSERT INTO users VALUES
  ('Şükrü Işık',   'şükrü'),
  ('İpek Çağlar',  'ipekç'),
  ('Ada Lovelace', 'ada');

-- length() counts characters, octet_length() counts UTF-8 bytes.
-- varchar(n) counts characters too: 'şükrü' fits in 6 although it is 8 bytes.
SELECT handle, length(handle) AS chars, octet_length(handle) AS bytes
FROM users
ORDER BY handle;

-- Case mapping follows the collation. The database default maps i to I;
-- Turkish rules need an ICU collation.
SELECT upper(handle) AS default_rules,
       upper(handle COLLATE "tr-x-icu") AS turkish_rules
FROM users
ORDER BY handle;

-- An explicit cast to varchar(n) truncates silently (the SQL standard says so)...
SELECT 'kahramanmaraşlı'::varchar(6) AS cast_result;

-- ...but storing an over-long value is an error.
INSERT INTO users VALUES ('Kahramanmaraşlı Ayşe', 'kahramanmaraşlı');

-- integer: 4 bytes, up to 2,147,483,647. bigint: 8 bytes, up to about 9.2e18.
SELECT pg_column_size(1::integer) AS integer_bytes,
       pg_column_size(1::bigint)  AS bigint_bytes;

-- Division of two integers truncates toward zero, as in Go, C and Java.
-- Python's -7 // 2 is -4; here -7 / 2 is -3. One numeric operand changes the type.
SELECT 7 / 2 AS int_div, -7 / 2 AS neg_div, 7 % 2 AS remainder, 7 / 2.0 AS numeric_div;

CREATE TABLE counters (
  page text    PRIMARY KEY,
  hits integer NOT NULL
);
INSERT INTO counters VALUES ('home', 2147483647), ('about', 1);

-- Aggregates widen their result: sum(integer) returns bigint, so this works.
SELECT sum(hits) AS total, pg_typeof(sum(hits)) AS total_type FROM counters;

-- Row arithmetic does not widen. One more hit on 'home' leaves integer's
-- range, and Postgres raises an error instead of wrapping around.
UPDATE counters SET hits = hits + 1 WHERE page = 'home';

-- A literal with a decimal point is numeric (exact) unless you cast it.
SELECT pg_typeof(0.1) AS literal_type,
       0.1 + 0.2 = 0.3 AS numeric_equal,
       0.1::float8 + 0.2::float8 = 0.3::float8 AS float_equal,
       0.1::float8 + 0.2::float8 AS float_sum;

CREATE TABLE payments (
  amount numeric(12, 2)   NOT NULL,  -- exact: 10 digits before the point, 2 after
  approx double precision NOT NULL   -- the mistake, kept for comparison
);

-- Ten payments of 0.10 TL.
INSERT INTO payments SELECT 0.10, 0.10 FROM generate_series(1, 10);

SELECT sum(amount) AS exact_total,
       sum(approx) AS float_total,
       sum(approx) = 1 AS float_total_is_one
FROM payments;

-- numeric(12, 2) rounds extra decimals on the way in, ties away from zero.
-- round() on a float rounds ties to even (on most platforms).
SELECT 19.995::numeric(12, 2) AS stored_as,
       round(2.5) AS numeric_round,
       round(2.5::float8) AS float_round;

-- Too many digits before the point is an error, never a silent wrap.
INSERT INTO payments VALUES (12345678901.00, 0);

files.sql/tables-types/02-time/examples/01_ins:
SET TimeZone = 'Europe/Istanbul';

CREATE TABLE meetings (
  title    text        NOT NULL,
  at_tz    timestamptz NOT NULL,  -- an instant, stored as UTC
  at_local timestamp   NOT NULL   -- a wall-clock reading with no zone
);

-- The same literals, with explicit offsets, go into both columns.
INSERT INTO meetings VALUES
  ('Istanbul standup', '2026-11-13 09:00:00+03', '2026-11-13 09:00:00+03'),
  ('Berlin review',    '2026-11-13 08:30:00+01', '2026-11-13 08:30:00+01');

-- timestamptz shows each instant in the session's zone; timestamp kept the
-- digits and silently dropped the offsets.
SELECT title, at_tz, at_local FROM meetings ORDER BY at_tz;

-- So the wall-clock column puts the later meeting first.
SELECT title FROM meetings ORDER BY at_local;

-- A colleague in Berlin reads the same rows: timestamptz follows the reader.
SET TimeZone = 'Europe/Berlin';
SELECT title, at_tz, at_local FROM meetings ORDER BY at_tz;

files.sql/tables-types/02-time/examples/02_zon:
SET TimeZone = 'UTC';

CREATE TABLE orders (id int PRIMARY KEY, placed_at timestamptz NOT NULL);
INSERT INTO orders VALUES
  (1, '2026-11-12 20:30:00+00'),   -- 23:30 in Istanbul
  (2, '2026-11-12 21:30:00+00');   -- 00:30 on the 13th in Istanbul

-- "Which day?" depends on whose calendar. ::date uses the session's zone;
-- AT TIME ZONE first turns the instant into Istanbul wall-clock time.
SELECT id,
       placed_at::date AS utc_day,
       (placed_at AT TIME ZONE 'Europe/Istanbul')::date AS istanbul_day
FROM orders
ORDER BY id;

-- Zone names carry history: Turkey's winter offset was +02 until 2016.
SELECT timestamp '2016-01-15 12:00' AT TIME ZONE 'Europe/Istanbul' AS winter_2016,
       timestamp '2026-01-15 12:00' AT TIME ZONE 'Europe/Istanbul' AS winter_2026;

-- Offsets written as zone strings are a trap. 'UTC+3' is POSIX syntax and
-- means three hours WEST of Greenwich. An interval means what it says.
SELECT timestamptz '2026-11-13 06:00+00' AT TIME ZONE 'Europe/Istanbul' AS by_name,
       timestamptz '2026-11-13 06:00+00' AT TIME ZONE INTERVAL '+03:00' AS by_interval,
       timestamptz '2026-11-13 06:00+00' AT TIME ZONE 'UTC+3' AS posix_utc_plus_3;

-- A bare '+03' even depends on the session (PostgreSQL 18): POSIX (UTC-3)
-- here, but Europe/Istanbul's own abbreviation is "+03", and it wins there.
SELECT timestamptz '2026-11-13 06:00+00' AT TIME ZONE '+03' AS bare_in_utc_session;
SET TimeZone = 'Europe/Istanbul';
SELECT timestamptz '2026-11-13 06:00+00' AT TIME ZONE '+03' AS bare_in_istanbul_session;

files.sql/tables-types/03-ids/examples/01_iden:
-- The modern way: an identity column (SQL standard, PostgreSQL 10+).
CREATE TABLE tickets (
  id    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  title text NOT NULL
);

INSERT INTO tickets (title) VALUES ('Login fails'), ('Typo on pricing page')
RETURNING id, title;

-- Sequence values are never handed back: a rolled-back insert leaves a gap.
SAVEPOINT before_insert;
INSERT INTO tickets (title) VALUES ('Rolled back');
ROLLBACK TO SAVEPOINT before_insert;

INSERT INTO tickets (title) VALUES ('After the rollback')
RETURNING id, title;

-- It is still backed by a sequence, one the column owns and manages.
SELECT pg_get_serial_sequence('tickets', 'id')::regclass AS backing_sequence;

-- GENERATED ALWAYS refuses a hand-written id unless you say
-- OVERRIDING SYSTEM VALUE, so accidents can't happen quietly.
INSERT INTO tickets (id, title) VALUES (10, 'Imported by hand');

files.sql/tables-types/03-ids/examples/02_seri:
-- The legacy way: serial is shorthand for integer + a sequence + a DEFAULT.
CREATE TABLE old_tickets (
  id    serial PRIMARY KEY,
  title text NOT NULL
);

-- Nothing marks it as an identity: it is an ordinary integer column whose
-- default happens to call nextval().
SELECT data_type, column_default, is_identity
FROM information_schema.columns
WHERE table_schema = current_schema()
  AND table_name = 'old_tickets' AND column_name = 'id';

-- An import writes ids by hand, and serial accepts them without a word...
INSERT INTO old_tickets (id, title) VALUES (1, 'Imported'), (2, 'Imported too');

-- ...but the sequence never saw them, so the next default is 1 again.
INSERT INTO old_tickets (title) VALUES ('First new ticket');

files.sql/tables-types/04-jsonb-arrays/example:
-- Option 1, enum: a real type whose values sort in declaration order.
CREATE TYPE ticket_status AS ENUM ('open', 'in_progress', 'done');

-- Option 2, lookup table: values are rows, so they can carry data.
CREATE TABLE statuses (
  code     text PRIMARY KEY,
  label_tr text NOT NULL,
  position int  NOT NULL UNIQUE
);
INSERT INTO statuses VALUES ('open', 'Açık', 10), ('in_progress', 'Sürüyor', 20), ('done', 'Bitti', 30);

CREATE TABLE tickets (
  id        int PRIMARY KEY,
  as_enum   ticket_status NOT NULL,
  as_lookup text NOT NULL REFERENCES statuses,
  -- Option 3, CHECK: plain text, the list lives in the table definition.
  as_check  text NOT NULL CHECK (as_check IN ('open', 'in_progress', 'done'))
);
INSERT INTO tickets VALUES
  (1, 'done', 'done', 'done'),
  (2, 'open', 'open', 'open'),
  (3, 'in_progress', 'in_progress', 'in_progress');

-- enum sorts by declaration, text alphabetically.
SELECT array_agg(as_enum ORDER BY as_enum)   AS enum_order,
       array_agg(as_check ORDER BY as_check) AS text_order
FROM tickets;

-- The lookup table supplies a Turkish label and its own sort order.
SELECT t.id, s.label_tr
FROM tickets t JOIN statuses s ON s.code = t.as_lookup
ORDER BY s.position;

-- Adding a value: one statement each for enum and lookup; CHECK is replaced.
ALTER TYPE ticket_status ADD VALUE 'blocked' BEFORE 'done';
INSERT INTO statuses VALUES ('blocked', 'Engellendi', 25);
ALTER TABLE tickets
  DROP CONSTRAINT tickets_as_check_check,
  ADD CONSTRAINT tickets_as_check_check
    CHECK (as_check IN ('open', 'in_progress', 'blocked', 'done'));

-- Removing a value: an enum has no DROP VALUE at all; the lookup table
-- refuses while rows still use it.
DELETE FROM statuses WHERE code = 'open';

files.sql/tables-types/05-alter/examples/01_re:
CREATE TABLE accounts (
  id   integer PRIMARY KEY,
  name varchar(100) NOT NULL
);
CREATE INDEX accounts_name ON accounts (name);
INSERT INTO accounts SELECT g, 'Kullanıcı ' || g FROM generate_series(1, 1000) AS g;

-- Table and index data live in files named by relfilenode. A rewrite copies
-- everything into new files, so the numbers change. Log them after each step.
CREATE FUNCTION files(OUT tbl oid, OUT idx oid) LANGUAGE sql
  AS $$ SELECT pg_relation_filenode('accounts'), pg_relation_filenode('accounts_name') $$;
CREATE TABLE steps (n int GENERATED ALWAYS AS IDENTITY, change text, tbl oid, idx oid);
INSERT INTO steps (change, tbl, idx) SELECT '(start)', tbl, idx FROM files();

ALTER TABLE accounts ADD COLUMN note text;
INSERT INTO steps (change, tbl, idx) SELECT 'add column, no default', tbl, idx FROM files();
ALTER TABLE accounts ADD COLUMN plan text NOT NULL DEFAULT 'free';
INSERT INTO steps (change, tbl, idx) SELECT 'add column, constant default', tbl, idx FROM files();
ALTER TABLE accounts ADD COLUMN token uuid NOT NULL DEFAULT uuidv7();
INSERT INTO steps (change, tbl, idx) SELECT 'add column, volatile default', tbl, idx FROM files();
ALTER TABLE accounts ADD COLUMN plan_label text GENERATED ALWAYS AS (upper(plan));
INSERT INTO steps (change, tbl, idx) SELECT 'add virtual generated column', tbl, idx FROM files();
ALTER TABLE accounts ALTER COLUMN name TYPE varchar(200);
INSERT INTO steps (change, tbl, idx) SELECT 'varchar(100) -> varchar(200)', tbl, idx FROM files();
ALTER TABLE accounts ALTER COLUMN name TYPE text;
INSERT INTO steps (change, tbl, idx) SELECT 'varchar(200) -> text', tbl, idx FROM files();
ALTER TABLE accounts ALTER COLUMN name TYPE text COLLATE "tr-x-icu";
INSERT INTO steps (change, tbl, idx) SELECT 'collation -> tr-x-icu', tbl, idx FROM files();
ALTER TABLE accounts ALTER COLUMN id TYPE bigint;
INSERT INTO steps (change, tbl, idx) SELECT 'integer -> bigint', tbl, idx FROM files();
ALTER TABLE accounts DROP COLUMN note;
INSERT INTO steps (change, tbl, idx) SELECT 'drop column', tbl, idx FROM files();

SELECT change,
       tbl <> lag(tbl) OVER (ORDER BY n) AS table_rewritten,
       idx <> lag(idx) OVER (ORDER BY n) AS name_index_rebuilt
FROM steps
ORDER BY n;

files.sql/tables-types/05-alter/examples/02_lo:
-- Runtime sql-nontx: every statement commits on its own, as in psql, so the
-- table exists before we look at the locks a single ALTER takes.
CREATE TABLE accounts (id bigint PRIMARY KEY, email text NOT NULL);
INSERT INTO accounts SELECT g, 'user' || g || '@example.com' FROM generate_series(1, 1000) AS g;
CREATE VIEW my_locks AS
  SELECT mode FROM pg_locks
  WHERE pid = pg_backend_pid() AND locktype = 'relation' AND relation = 'accounts'::regclass;

BEGIN;
ALTER TABLE accounts ADD COLUMN country text;
SELECT mode FROM my_locks ORDER BY mode;
COMMIT;

BEGIN;
ALTER TABLE accounts ADD CONSTRAINT email_has_at CHECK (email LIKE '%@%') NOT VALID;
SELECT mode FROM my_locks ORDER BY mode;
COMMIT;

BEGIN;
ALTER TABLE accounts VALIDATE CONSTRAINT email_has_at;
