-- LEARN(sql.transactions.isolation-levels): watch a non-repeatable read happen, then stop it.
-- sql-multisession: steps tagged A:/B: run on two connections in this order.

-- A: begin; read
A: BEGIN;
A: SELECT balance FROM accounts WHERE id = 'a';   -- 100

-- B: move 40 out, commit
B: BEGIN;
B: UPDATE accounts SET balance = balance - 40 WHERE id = 'a';
B: COMMIT;

-- A: read again in the SAME transaction
A: SELECT balance FROM accounts WHERE id = 'a';   -- 60 (non-repeatable read!)
A: COMMIT;

-- Prevent it: REPEATABLE READ pins one snapshot for the whole transaction.
A: BEGIN ISOLATION LEVEL REPEATABLE READ;
A: SELECT balance FROM accounts WHERE id = 'a';   -- 60

B: BEGIN;
B: UPDATE accounts SET balance = balance - 40 WHERE id = 'a';
B: COMMIT;

A: SELECT balance FROM accounts WHERE id = 'a';   -- still 60
A: COMMIT;

files.sql/transactions/03-serializable/example:
-- Rule, checked in application code: at least one doctor stays on call.
-- Alice and Bob both feel ill and ask to go off call at the same moment.
A: BEGIN ISOLATION LEVEL REPEATABLE READ;
B: BEGIN ISOLATION LEVEL REPEATABLE READ;

-- Each checks the rule: two on call, so one may leave.
A: SELECT count(*) AS on_call FROM doctors WHERE on_call;
B: SELECT count(*) AS on_call FROM doctors WHERE on_call;

-- Each takes only themselves off: different rows, so no write conflict.
A: UPDATE doctors SET on_call = false WHERE name = 'alice';
B: UPDATE doctors SET on_call = false WHERE name = 'bob';
A: COMMIT;
B: COMMIT;

-- Both checks passed, and the rule is broken.
A: SELECT count(*) AS on_call FROM doctors WHERE on_call;

-- The same two transactions, now SERIALIZABLE. Nothing else changes.
A: BEGIN ISOLATION LEVEL SERIALIZABLE;
B: BEGIN ISOLATION LEVEL SERIALIZABLE;
A: SELECT count(*) AS on_call FROM doctors WHERE on_call;
B: SELECT count(*) AS on_call FROM doctors WHERE on_call;
A: UPDATE doctors SET on_call = false WHERE name = 'alice';
B: UPDATE doctors SET on_call = false WHERE name = 'bob';

-- No step waits. The first commit wins; the second could not have happened
-- in any serial order, so it fails with SQLSTATE 40001.
A: COMMIT;
B: COMMIT;

-- The retry: run the WHOLE transaction again, including the check.
B: BEGIN ISOLATION LEVEL SERIALIZABLE;
B: SELECT count(*) AS on_call FROM doctors WHERE on_call;
-- One left: the application refuses, and Bob stays on call.
B: ROLLBACK;

A: SELECT name, on_call FROM doctors ORDER BY name;

