// LEARN(ts.architecture.explicit-states): an async value is a union of states, each carrying only its own data.
import { renderToStaticMarkup } from "react-dom/server";

// One generic type for every async value in the app.
type Remote<T> =
  | { status: "idle" }
  | { status: "loading"; stale?: T } // stale: the last good value, kept while reloading
  | { status: "failed"; error: string; stale?: T }
  | { status: "ready"; data: T };

// One handler per status. The mapped type makes a missing handler a compile error.
type Handlers<T, R> = {
  [S in Remote<T>["status"]]: (state: Extract<Remote<T>, { status: S }>) => R;
};
function match<T, R>(state: Remote<T>, handlers: Handlers<T, R>): R {
  // tsc can't correlate handlers[state.status] with state's variant, so the
  // one cast lives here, behind a signature that is checked at every call.
  const handler = handlers[state.status] as (state: Remote<T>) => R;
  return handler(state);
}

function Completed({ state }: { state: Remote<number> }) {
  return match(state, {
    idle: () => <p>-</p>,
    loading: (s) => (
      <p aria-busy="true">{s.stale === undefined ? "yükleniyor" : `${s.stale} ders, yenileniyor`}</p>
    ),
    failed: (s) => (
      <p role="alert">{s.stale === undefined ? s.error : `${s.stale} ders (eski: ${s.error})`}</p>
    ),
    ready: (s) => <p>{`${s.data} ders`}</p>,
  });
}
// Leave a status out and the call does not compile:
// match(state, { idle: () => "", loading: () => "", ready: () => "" });
// error TS2741: Property 'failed' is missing in type '{ idle: () => string; loading: () => string; ready: () => string; }' but required in type 'Handlers<number, string>'.

// A first load, a background refresh, a failed refresh, a retry that succeeds.
const timeline: Remote<number>[] = [
  { status: "idle" },
  { status: "loading" },
  { status: "ready", data: 12 },
  { status: "loading", stale: 12 },
  { status: "failed", error: "ağ hatası", stale: 12 },
  { status: "loading", stale: 12 },
  { status: "ready", data: 13 },
];
for (const state of timeline) {
  console.log(state.status.padEnd(8), renderToStaticMarkup(<Completed state={state} />));
}

// LEARN(ts.architecture.explicit-states): the core decides (state, effects as data); it never performs I/O.

type State =
  | { status: "idle" }
  | { status: "loading"; attempt: number }
  | { status: "backoff"; attempt: number; error: string }
  | { status: "failed"; error: string }
  | { status: "ready"; titles: string[] };

type Event =
  | { type: "open" }
  | { type: "loaded"; attempt: number; titles: string[] }
  | { type: "rejected"; attempt: number; error: string }
  | { type: "timer" };

// Effects are descriptions of I/O, for the shell to carry out.
type Effect = { type: "fetch"; attempt: number } | { type: "sleep"; ms: number };

const MAX_ATTEMPTS = 3;
const load = (attempt: number): [State, Effect[]] => [
  { status: "loading", attempt },
  [{ type: "fetch", attempt }],
];

function step(s: State, e: Event): [State, Effect[]] {
  switch (e.type) {
    case "open":
      return s.status === "idle" || s.status === "failed" ? load(1) : [s, []];
    case "loaded":
      if (s.status !== "loading" || s.attempt !== e.attempt) return [s, []]; // stale reply
      return [{ status: "ready", titles: e.titles }, []];
    case "rejected":
      if (s.status !== "loading" || s.attempt !== e.attempt) return [s, []];
      if (s.attempt === MAX_ATTEMPTS) return [{ status: "failed", error: e.error }, []];
      return [
        { status: "backoff", attempt: s.attempt, error: e.error },
        [{ type: "sleep", ms: 100 * 2 ** (s.attempt - 1) }],
      ];
    case "timer":
      return s.status === "backoff" ? load(s.attempt + 1) : [s, []];
  }
}

// Testing the core is replaying events: no timers, no fetch mocks, no React.
const script: Event[] = [
  { type: "open" },
  { type: "rejected", attempt: 1, error: "503" },
  { type: "timer" },
  { type: "rejected", attempt: 1, error: "late reply" }, // from a request we gave up on
  { type: "loaded", attempt: 2, titles: ["Klasörler", "Durum"] },
  { type: "open" },
];
let state: State = { status: "idle" };
for (const event of script) {
  const [next, effects] = step(state, event);
  const shown = next === state ? "(ignored)" : JSON.stringify(next);
  console.log(event.type.padEnd(9) + [shown, ...effects.map((fx) => JSON.stringify(fx))].join(" "));
  state = next;
}

// LEARN(ts.architecture.explicit-states): the shell performs effects and feeds results back as events.

// The core from the previous example, condensed into if-chains. Same rules.
type State =
  | { status: "idle" }
  | { status: "loading"; attempt: number }
  | { status: "backoff"; attempt: number; error: string }
  | { status: "failed"; error: string }
  | { status: "ready"; titles: string[] };
type Event =
  | { type: "open" }
  | { type: "loaded"; attempt: number; titles: string[] }
  | { type: "rejected"; attempt: number; error: string }
  | { type: "timer" };
type Effect = { type: "fetch"; attempt: number } | { type: "sleep"; ms: number };
type Next = [State, Effect[]];
const load = (attempt: number): Next => [{ status: "loading", attempt }, [{ type: "fetch", attempt }]];
function step(s: State, e: Event): Next {
  if (e.type === "open") return s.status === "idle" || s.status === "failed" ? load(1) : [s, []];
  if (e.type === "timer") return s.status === "backoff" ? load(s.attempt + 1) : [s, []];
  if (s.status !== "loading" || s.attempt !== e.attempt) return [s, []];
  if (e.type === "loaded") return [{ status: "ready", titles: e.titles }, []];
  if (s.attempt === 3) return [{ status: "failed", error: e.error }, []];
  const backoff: State = { status: "backoff", attempt: s.attempt, error: e.error };
  return [backoff, [{ type: "sleep", ms: 100 * 2 ** (s.attempt - 1) }]];
}

// The view is part of the core as well: state in, text out (JSX in a real app).
const view = (s: State): string =>
  s.status === "idle" ? "-"
  : s.status === "loading" ? `yükleniyor (deneme ${s.attempt})`
  : s.status === "backoff" ? `${s.error}, tekrar denenecek`
  : s.status === "failed" ? `başarısız: ${s.error}`
  : s.titles.join(", ");

// The shell: the only code that touches the network, timers and the screen.
// It makes no decisions; every one of them came from step().
function start(fetchTitles: (attempt: number) => Promise<string[]>): (e: Event) => void {
  let state: State = { status: "idle" };
  const dispatch = (event: Event) => {
    const [next, effects] = step(state, event);
    if (next !== state) console.log(`${next.status.padEnd(8)}${view(next)}`);
    state = next;
    for (const fx of effects) {
      if (fx.type === "sleep") setTimeout(() => dispatch({ type: "timer" }), fx.ms);
      else
        fetchTitles(fx.attempt).then(
          (titles) => dispatch({ type: "loaded", attempt: fx.attempt, titles }),
          (err: Error) => dispatch({ type: "rejected", attempt: fx.attempt, error: err.message }),
        );
    }
  };
  return dispatch;
}

// A server that fails the first request, like a cold start.
const fakeFetch = async (attempt: number) => {
  if (attempt === 1) throw new Error("503");
  return ["Klasörler", "Durum", "Kalıplar"];
};
start(fakeFetch)({ type: "open" });

